
// 163C1: rede de segurança para falhas críticas durante a inicialização.
window.__CALIFIT_APP_READY__=false;
window.__CALIFIT_BOOT_STARTED_AT__=(typeof performance!=='undefined'&&performance.now)?performance.now():Date.now();

// 167D.1: identifica somente iOS/iPadOS para evitar o zoom automático de campos abaixo de 16 px.
const CALIFIT_IOS_FOCUS=/iP(?:ad|hone|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
document.documentElement.classList.toggle('califit-ios-focus',CALIFIT_IOS_FOCUS);

function mostrarFalhaCarregamentoCalifit(){
  if(window.__CALIFIT_TEST_MODE__||document.getElementById('califit-startup-fallback')) return;
  const box=document.createElement('div');
  box.id='califit-startup-fallback';
  box.setAttribute('role','alert');
  box.style.cssText='position:fixed;inset:0;z-index:99999;background:#f4f4f0;color:#1a1a1a;display:flex;align-items:center;justify-content:center;padding:24px;font-family:Inter,Roboto,Arial,sans-serif';
  box.innerHTML='<div style="width:100%;max-width:360px;background:#fff;border:1px solid #e8e8e3;border-radius:16px;padding:22px;box-shadow:0 18px 50px rgba(0,0,0,.18)"><div style="font-size:var(--type-section);font-weight:var(--fw-extra);margin-bottom:8px">Não foi possível carregar o CaliFit Pro</div><div style="font-size:var(--type-label);line-height:var(--lh-loose);color:#666;margin-bottom:16px">Seus dados locais não foram apagados. Feche e abra o app novamente. Se o problema continuar, preserve o arquivo de backup mais recente antes de limpar dados ou reinstalar.</div><button type="button" onclick="location.reload()" style="width:100%;min-height:44px;border:0;border-radius:var(--rad-md);background:#111;color:#fff;font-weight:var(--fw-strong);cursor:pointer">Tentar novamente</button></div>';
  (document.body||document.documentElement).appendChild(box);
}
if(typeof window.addEventListener==='function'){
  window.addEventListener('error',()=>{if(!window.__CALIFIT_APP_READY__) mostrarFalhaCarregamentoCalifit();});
  window.addEventListener('unhandledrejection',()=>{if(!window.__CALIFIT_APP_READY__) mostrarFalhaCarregamentoCalifit();});
}
