const DPT=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const DPT_FULL=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const CORES={forca:'#3f5cff',tecnica:'#1565c0',metabolico:'#b71c1c',misto:'#ad5d00',mobilidade:'#6a1b9a',descanso:'#757575',atividade:'#00695c',deload:'#4a148c'};
const OBJL={forca:'Ganhar força',massa:'Ganhar massa muscular',resist:'Melhorar condicionamento',calistenia:'Evoluir na calistenia',mobilidade:'Melhorar mobilidade e movimento',saude:'Saúde e condicionamento geral',def:'Definição',seca:'Secar',recomp:'Recomposição',core:'Core'};
const FOCO_LABEL={reduzir_gordura:'Reduzir gordura corporal',composicao:'Melhorar composição corporal',core:'Fortalecer core',mobilidade:'Melhorar mobilidade',resistencia_muscular:'Aumentar resistência muscular',equilibrio:'Melhorar equilíbrio e estabilidade',retorno:'Preparar retorno gradual aos exercícios',manter_massa:'Manter massa muscular'};
const META_TECNICA_LABEL={primeira_barra:'Primeira barra completa',mais_barras:'Aumentar número de barras',flexoes:'Melhorar flexões',paralelas:'Evoluir nas paralelas',lsit:'Evoluir no L-sit',prancha_core:'Melhorar prancha e core',agachamento_unilateral:'Evoluir no agachamento unilateral',nao_sei:'Ainda não sei'};
const EQUIP_ALIAS={'Colete de carga':'Colete com peso','Colete de peso':'Colete com peso','Dip belt':'Cinto de carga','Cinto de treino com peso':'Cinto de carga','Cinto com peso':'Cinto de carga','Pull-up station':'Estação de barra','Elásticos':'Elásticos/faixas de resistência','Elástico':'Elásticos/faixas de resistência','Elásticos/Theraband':'Elásticos/faixas de resistência','Faixa de resistência':'Elásticos/faixas de resistência','Faixas de resistência':'Elásticos/faixas de resistência','Pesos tornozelo':'Pesos de tornozelo'};
const EQUIPAMENTOS_EXIGEM_CARGA=['Kettlebell','Halteres','Colete com peso','Cinto de carga','Mochila lastrada','Medicine Ball','Pesos de tornozelo'];
const EQUIP_CARGA_ALIAS={
  kettlebell:'Kettlebell',kb:'Kettlebell',
  halteres:'Halteres',dumbbells:'Halteres',halter:'Halteres',
  colete:'Colete com peso','colete com peso':'Colete com peso',
  cinto:'Cinto de carga','cinto de carga':'Cinto de carga','dip belt':'Cinto de carga','cinto com peso':'Cinto de carga',
  mochila:'Mochila lastrada','mochila lastrada':'Mochila lastrada',
  'medicine ball':'Medicine Ball','med ball':'Medicine Ball','bola medicinal':'Medicine Ball',
  'pesos de tornozelo':'Pesos de tornozelo',tornozeleira:'Pesos de tornozelo',tornozeleiras:'Pesos de tornozelo',
  elasticos:'Elásticos/faixas de resistência',elastico:'Elásticos/faixas de resistência',
  'faixa de resistencia':'Elásticos/faixas de resistência','faixas de resistencia':'Elásticos/faixas de resistência',
  theraband:'Elásticos/faixas de resistência'
};
const EQUIP_GRUPOS={
  'Sem equipamento':['Peso corporal'],
  'Estruturas e apoios':['Barra fixa','Estação de barra','Barras paralelas','Paralela de chão','Argolas','TRX/Suspensão','Banco/Cadeira','Step/Degrau'],
  'Cargas externas':['Kettlebell','Halteres','Colete com peso','Cinto de carga','Mochila lastrada','Medicine Ball','Pesos de tornozelo'],
  'Resistências':['Elásticos/faixas de resistência'],
  'Acessórios':['Tapete/Colchão','Roda abdominal','Corda de pular','Bosu']
};
const LIMITACOES_GRUPOS={
  'Parte superior':[['cervical','Pescoço/cervical'],['ombro','Ombro'],['cotovelo','Cotovelo'],['punho','Punho/mão']],
  'Tronco':[['toracica','Coluna torácica'],['lombar','Lombar']],
  'Parte inferior':[['quadril','Quadril'],['adutores','Virilha/adutores'],['quadriceps','Quadríceps'],['posterior_coxa','Posterior da coxa'],['joelho','Joelho'],['panturrilha_aquiles','Panturrilha/Aquiles'],['tornozelo','Tornozelo'],['pe','Pé/calcanhar'],['fascite_plantar','Fascite plantar']],
  'Cirurgia, recuperação e outros':[['recuperacao_lesao','Cirurgia/lesão em recuperação'],['instabilidade','Equilíbrio/instabilidade'],['outra','Outra limitação'],['nenhuma','Nenhuma dor / sem limitação atual']]
};
function labelLimitacao(v){
  if(v==='recuperacao_lesao') return 'Cirurgia/lesão em recuperação';
  if(v==='nenhuma') return 'Nenhuma dor / sem limitação atual';
  return Object.values(LIMITACOES_GRUPOS).flat().find(x=>x[0]===v)?.[1]||String(v||'');
}
function labelsLimitacoes(lista=[]){return normalizarLimitacoes(lista).filter(v=>v!=='nenhuma').map(labelLimitacao).filter(Boolean);}
function normalizarEquipamentoNome(v){
  const direto=EQUIP_ALIAS[v]||v;
  return EQUIP_CARGA_ALIAS[normTxt(direto||'')]||direto;
}
function normalizarEquipamentos(lista){return [...new Set(arr(lista).map(normalizarEquipamentoNome).filter(Boolean))];}
function nomeTecnicoExercicio(ex){
  if(typeof ex==='string') return ex;
  return ex?.exercicioId||ex?.nomeOriginal||ex?.n||ex?.nome||'';
}
function chaveCargaExercicio(ex){
  const n=normTxt(nomeTecnicoExercicio(ex));
  if(/halter/.test(n)) return 'Halteres';
  if(/kettlebell|\bkb\b|goblet/.test(n)) return 'Kettlebell';
  if(/medicine ball/.test(n)) return 'Medicine Ball';
  if(/mochila/.test(n)) return 'Mochila lastrada';
  if(/cinto|barra fixa com carga|barra com carga|paralelas com carga/.test(n)) return 'Cinto de carga';
  if(/colete/.test(n)) return 'Colete com peso';
  if(/tornozelo/.test(n)) return 'Pesos de tornozelo';
  return '';
}
function exercicioUsaCargaNumerica(ex){
  const equip=chaveCargaExercicio(ex);
  return !!equip&&equip!=='Elásticos/faixas de resistência'&&!usaElasticoExercicio(ex);
}
const CARGA_LIMITES={
  'Mochila lastrada':{min:1,max:60},
  'Colete com peso':{min:1,max:50},
  'Cinto de carga':{min:1,max:100},
  'Pesos de tornozelo':{min:.25,max:10},
  'Kettlebell':{min:1,max:80},
  'Medicine Ball':{min:1,max:30},
  'Halteres':{min:.5,max:80}
};
function limiteCargaEquipamento(equipamento){return CARGA_LIMITES[normalizarEquipamentoNome(equipamento)]||{min:.0001,max:300};}
function cargaPlausivelEquipamento(valor,equipamento){
  const n=Number(valor),lim=limiteCargaEquipamento(equipamento);
  return Number.isFinite(n)&&n>=lim.min&&n<=lim.max;
}
function normalizarConfigCarga(config={},equipamento=''){
  // 163P1.3.1: aceita formatos atuais e legados de carga sem descartar pesos válidos.
  // Backups antigos e runners externos podem trazer número, string, array ou aliases
  // como valores/cargas/pesoKg. O estado persistido continua normalizado no formato atual.
  let c={};
  if(Array.isArray(config)) c={pesos:config};
  else if(typeof config==='number') c={peso:config,tipo:'fixo'};
  else if(typeof config==='string'){
    const lista=parseListaCargas(config,equipamento);
    if(lista.valido&&lista.valores.length>1) c={pesos:lista.valores,tipo:'lista'};
    else if(lista.valido&&lista.valores.length===1) c={peso:lista.valores[0],tipo:'fixo'};
  }else if(config&&typeof config==='object') c={...config};
  const fontesLista=[c.pesos,c.valores,c.cargas,c.opcoes,c.disponiveis].find(Array.isArray)||[];
  const pesoBruto=c.peso??c.pesoKg??c.kg??c.valor??c.carga;
  const minBruto=c.min??c.minimo??c.pesoMin??c.cargaMin;
  const maxBruto=c.max??c.maximo??c.pesoMax??c.cargaMax??(c.tipo==='ajustavel'?pesoBruto:0);
  const pesos=[...new Set(arr(fontesLista).map(Number).filter(n=>cargaPlausivelEquipamento(n,equipamento)))].sort((a,b)=>a-b);
  const peso=cargaPlausivelEquipamento(pesoBruto,equipamento)?numeroDecimalPositivo(pesoBruto):0;
  const minimo=cargaPlausivelEquipamento(minBruto,equipamento)?numeroDecimalPositivo(minBruto):0;
  const maximo=cargaPlausivelEquipamento(maxBruto,equipamento)?numeroDecimalPositivo(maxBruto):0;
  const inc=parseIncrementoCarga(c.incremento??c.passo??c.step);
  const incremento=inc.valido?(inc.valor||0):0;
  const tipo=c.tipo==='ajustavel'?'ajustavel':pesos.length>1?'lista':(pesos.length===1||peso)?'fixo':(c.tipo||'');
  return{...c,tipo,pesos,peso,min:minimo,max:maximo,incremento};
}
function valoresConfiguraveisCarga(config={}){
  const c=normalizarConfigCarga(config);
  if(c.pesos.length) return c.pesos;
  if(c.tipo==='ajustavel'&&c.min>0&&c.max>=c.min&&c.incremento>0){
    const valores=[];
    for(let v=c.min;v<=c.max+1e-9&&valores.length<100;v+=c.incremento) valores.push(+v.toFixed(3));
    return valores;
  }
  if(c.tipo!=='ajustavel'&&c.peso>0) return [c.peso];
  return [];
}
function obterCargasEquipamento(perfil=ST.perfil,equipamento=''){
  const chave=normalizarEquipamentoNome(equipamento);
  const mapas=[perfil?.cargasEquipamentos,perfil?.cargas,perfil?.pesosEquipamentos].filter(v=>v&&typeof v==='object');
  let bruto;
  for(const mapa of mapas){
    if(Object.prototype.hasOwnProperty.call(mapa,chave)){bruto=mapa[chave];break;}
    const alias=Object.entries(mapa).find(([k])=>normalizarEquipamentoNome(k)===chave);
    if(alias){bruto=alias[1];break;}
  }
  const config=normalizarConfigCarga(bruto??{},chave);
  return{equipamento:chave,config,valores:valoresConfiguraveisCarga(config)};
}
function equipamentoExigeCarga(nomeEquipamento){
  const nome=normalizarEquipamentoNome(nomeEquipamento);
  return EQUIPAMENTOS_EXIGEM_CARGA.some(eq=>normTxt(eq)===normTxt(nome));
}
function cargaInformadaParaEquipamento(perfil,nomeEquipamento){
  const equip=normalizarEquipamentoNome(nomeEquipamento);
  if(!equipamentoExigeCarga(equip)) return true;
  return obterCargasEquipamento(perfil,equip).valores.some(v=>Number.isFinite(+v)&&+v>0);
}
function cargaIgnoradaPorDecisao(perfil,nomeEquipamento){
  const equip=normalizarEquipamentoNome(nomeEquipamento);
  const cfg=perfil?.cargasEquipamentos?.[equip]||{};
  return !!cfg.ignorarSemPeso;
}
function equipamentosCarregadosSemCarga(perfil={}){
  const eqs=normalizarEquipamentos(perfil.equipamentos);
  return eqs.filter(eq=>equipamentoExigeCarga(eq)&&!cargaInformadaParaEquipamento(perfil,eq));
}
function equipamentosCarregadosSemDecisao(perfil={}){
  return equipamentosCarregadosSemCarga(perfil).filter(eq=>!cargaIgnoradaPorDecisao(perfil,eq));
}
function equipamentosValidosParaPrescricao(perfil={}){
  const eqs=normalizarEquipamentos(perfil.equipamentos);
  const validos=eqs.filter(eq=>!equipamentoExigeCarga(eq)||cargaInformadaParaEquipamento(perfil,eq));
  return validos.length?validos:['Peso corporal'];
}
function perfilComEquipamentosValidos(perfil={}){
  const copia={...perfil,equipamentos:equipamentosValidosParaPrescricao(perfil)};
  copia.cargasEquipamentos=perfil.cargasEquipamentos||{};
  return copia;
}
function equipamentoCanonicoExigencia(token){
  const n=normTxt(token||'');
  if(/kettlebell|\bkb\b/.test(n)) return 'Kettlebell';
  if(/halter|dumbbell/.test(n)) return 'Halteres';
  if(/colete/.test(n)) return 'Colete com peso';
  if(/cinto|dip belt/.test(n)) return 'Cinto de carga';
  if(/mochila/.test(n)) return 'Mochila lastrada';
  if(/medicine|med ball|bola medicinal/.test(n)) return 'Medicine Ball';
  if(/tornozeleira|peso.*tornozelo|tornozelo/.test(n)) return 'Pesos de tornozelo';
  return '';
}
function avisoEquipamentosCargaPendenteHtml(perfil=ST.perfil){
  const pendentes=equipamentosCarregadosSemCarga(perfil);
  return pendentes.length?`<div class="info io">Peso não informado: ${escHtml(fraseListaHumana(pendentes))}. Esses equipamentos ficam no perfil, mas não serão usados em prescrições com carga até você informar o peso.</div>`:'';
}
function obterCargasDisponiveisExercicio(ex,perfil=ST.perfil){
  if(!exercicioUsaCargaNumerica(ex)) return{equipamento:'',config:{},valores:[]};
  const equipamento=chaveCargaExercicio(ex);
  return equipamento?obterCargasEquipamento(perfil,equipamento):{equipamento:'',config:{},valores:[]};
}
function cargasDisponiveisExercicio(nome,perfil=ST.perfil){
  return obterCargasDisponiveisExercicio(nome,perfil).valores;
}
function fmtKg(v){
  const n=Number(v);
  return Number.isFinite(n)?`${n.toLocaleString('pt-BR',{maximumFractionDigits:2})} kg`:'';
}
function listaKg(valores=[]){
  return fraseListaHumana(valores.map(fmtKg));
}
function niveisElasticoPerfil(perfil=ST.perfil){
  const cfg=perfil?.cargasEquipamentos?.['Elásticos/faixas de resistência']||{};
  const map={leve:'leve',media:'médio',medio:'médio',média:'médio','médio':'médio',moderada:'médio',forte:'forte',pesada:'forte'};
  return [...new Set(arr(cfg.niveis).map(v=>map[normTxt(v)]||String(v||'').trim()).filter(Boolean))];
}
function usaElasticoExercicio(ex){
  const n=normTxt(nomeTecnicoExercicio(ex));
  return /elastico|face pull|external rotation|rotacao externa|retracao escapular|manguito|escapular/.test(n);
}
function exercicioPreventivoElastico(ex){
  const n=normTxt(nomeTecnicoExercicio(ex));
  return /external rotation|rotacao externa|face pull|retracao escapular|manguito|escapular/.test(n);
}
function sugerirResistenciaElastico(exercicio,perfil=ST.perfil){
  if(!usaElasticoExercicio(exercicio)) return '';
  const flags=flagsSegurancaPerfil(perfil);
  const temDorRelacionada=flags.dorOmbro||flags.dorCervical||flags.dorPunho;
  const preventivo=exercicioPreventivoElastico(exercicio);
  if(preventivo) return perfil?.nivel==='init'||temDorRelacionada?'leve':'leve a moderada';
  if(temDorRelacionada) return 'leve';
  return perfil?.nivel==='init'?'leve a moderada':'moderada';
}
function linhasResistenciaElastico(exercicio,perfil=ST.perfil){
  if(!usaElasticoExercicio(exercicio)) return [];
  const niveis=niveisElasticoPerfil(perfil);
  const linhas=niveis.length
    ? [{label:'Resistências disponíveis',texto:fraseListaHumana(niveis)}]
    : [{label:'Resistência não cadastrada',texto:`Use uma resistência leve/moderada e ajuste pelo ${rotuloRpeUsuario()}.`}];
  linhas.push({label:'Resistência sugerida',texto:sugerirResistenciaElastico(exercicio,perfil)});
  if(niveis.length===1&&normTxt(niveis[0])==='forte'&&(perfil?.nivel==='init'||flagsSegurancaPerfil(perfil).dorOmbro||flagsSegurancaPerfil(perfil).dorCervical||flagsSegurancaPerfil(perfil).dorPunho)){
    linhas.push({label:'Atenção',texto:`Resistência disponível pode ser alta para este contexto. Use apenas se mantiver técnica e ${rotuloRpeUsuario()} adequado.`});
  }
  return linhas;
}
function resumoResistenciaElastico(exercicio,perfil=ST.perfil){
  return linhasResistenciaElastico(exercicio,perfil).map(l=>`${l.label}: ${l.texto}`).join(' ');
}
function htmlCargaResistenciaExercicio(exercicio,perfil=ST.perfil,inf=null){
  const linhas=linhasResistenciaElastico(exercicio,perfil);
  if(linhas.length) return linhas.map(l=>`<div class="ex-d"><strong>${escHtml(l.label)}:</strong> ${escHtml(l.texto)}</div>`).join('')+(modoIniciante()?`<div class="ex-d"><strong>Resistência:</strong> no elástico, é a força da faixa, não peso em kg.</div>`:'');
  const info=inf||infoExercicio(exercicio);
  const cargaDisponivel=resumoCargaDisponivelExercicio(exercicio,perfil);
  return `<div class="ex-d"><strong>Carga/resistência:</strong> ${escHtml(info.carga)}</div>${cargaDisponivel?`<div class="ex-d"><strong>${escHtml(cargaDisponivel.split(':')[0])}:</strong>${escHtml(cargaDisponivel.includes(':')?cargaDisponivel.slice(cargaDisponivel.indexOf(':')+1):cargaDisponivel)}</div>`:''}`;
}
function htmlAjudaResistenciaElastico(exercicio,perfil=ST.perfil){
  const linhas=linhasResistenciaElastico(exercicio,perfil);
  return linhas.length?`<div class="form-help">${linhas.map(l=>`${escHtml(l.label)}: ${escHtml(l.texto)}`).join('<br>')}</div>`:'';
}
function inicianteSemHistoricoSuficiente(perfil={}){
  if((perfil.nivel||'init')!=='init') return false;
  const marcas=Object.values(perfil.marcas||{}).map(v=>+v||0);
  const temMarcas=marcas.some(v=>v>0);
  const temHistorico=!!String(perfil.historicoTreino||'').trim()||arr(perfil.tiposTreinoRecentes).length>0;
  const freq=normTxt(perfil.frequenciaRecente||'');
  const freqRelevante=freq&&!['nao','nenhuma','ocasional'].includes(freq);
  return !temMarcas&&!temHistorico&&!freqRelevante;
}
function alternativaSemCargaInicial(exercicio,perfil=ST.perfil){
  const n=normTxt(nomeTecnicoExercicio(exercicio));
  if(/agachamento.*(colete|mochila|goblet|halter|kb)|step-up com colete|avanco com mochila/.test(n)){
    if(equipamentoDisponivel('Agachamento',perfil)) return 'Agachamento';
    if(equipamentoDisponivel('Step-up',perfil)) return 'Step-up';
    return 'Ponte de Glúteo';
  }
  if(/rdl kb|kettlebell swing|levantamento terra romeno|ponte de gluteo com mochila/.test(n)){
    return equipamentoDisponivel('Ponte de Glúteo',perfil)?'Ponte de Glúteo':'Bird Dog';
  }
  return '';
}
function normalizarCargaExternaIniciantePlano(plano,perfil=ST.perfil){
  if(!inicianteSemHistoricoSuficiente(perfil)||!plano?.dias) return plano;
  Object.values(plano.dias||{}).forEach(dia=>{
    if(!dia||['descanso','atividade','recuperacao'].includes(dia.tipo)) return;
    ['ex','core','ombro','aq'].forEach(bloco=>{
      dia[bloco]=(dia[bloco]||[]).map(ex=>{
        const alt=alternativaSemCargaInicial(ex,perfil);
        if(alt&&alt!==ex.n) return {...ex,n:alt,p:EXD[alt]?.prog||'',nota:[ex.nota,'carga externa removida no início: priorizar técnica sem carga'].filter(Boolean).join(' · ')};
        if(exercicioUsaCargaNumerica(ex)) return {...ex,nota:[ex.nota,`Carga externa opcional. Comece sem carga se a técnica não estiver consistente. Use apenas se mantiver técnica e ${rotuloRpeUsuario()} adequado.`].filter(Boolean).join(' · ')};
        return ex;
      });
    });
  });
  return plano;
}
function resumoCargaDisponivelExercicio(nome,perfil=ST.perfil){
  const elastic=resumoResistenciaElastico(nome,perfil);
  if(elastic) return elastic;
  const {equipamento,config,valores}=obterCargasDisponiveisExercicio(nome,perfil);
  const selecionado=normalizarEquipamentos(perfil?.equipamentos).includes(equipamento);
  const kbPesada=equipamento==='Kettlebell'&&perfil?.nivel==='init'&&valores.length&&Math.min(...valores)>=20;
  if(equipamento==='Pesos de tornozelo'&&valores.length>1) return `Pesos de tornozelo disponíveis: ${listaKg(valores)}`;
  if(equipamento==='Pesos de tornozelo'&&valores.length===1) return `Peso de tornozelo disponível: ${fmtKg(valores[0])}`;
  if(valores.length>1) return `Cargas disponíveis: ${listaKg(valores)}`;
  if(valores.length===1) return kbPesada?`Peso disponível: ${fmtKg(valores[0])}. Carga disponível pode ser alta para iniciante. Use somente se mantiver técnica e ${rotuloRpeUsuario()} adequado; caso contrário, faça a variação sem carga.`:`Peso disponível: ${fmtKg(valores[0])}`;
  if(config.tipo==='ajustavel'&&config.max>0) return `Carga disponível: ajustável até ${fmtKg(config.max)}`;
  if(selecionado&&equipamento) return `Carga não cadastrada. Use carga leve/moderada e ajuste pelo ${rotuloRpeUsuario()}.`;
  return '';
}
function sugerirCargaInicialExercicio(exercicio,perfil=ST.perfil,historico=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return null;
  const nome=nomeTecnicoExercicio(exercicio);
  const logs=(historico||[]).map(h=>h?.log||h);
  const usadas=logs.map(l=>cargaRegistradaExercicio(exercicio,l)).filter(Boolean);
  if(usadas.length) return{valor:usadas.at(-1),tipo:'usada',texto:`Carga usada mais recente: ${fmtKg(usadas.at(-1))}`};
  const {valores}=obterCargasDisponiveisExercicio(exercicio,perfil);
  if(!valores.length) return null;
  const menor=valores[0];
  if(chaveCargaExercicio(exercicio)==='Kettlebell'&&perfil?.nivel==='init'&&menor>=20) return{valor:null,tipo:'referencia',texto:`Carga disponível pode ser alta para iniciante. Use somente se mantiver técnica e ${rotuloRpeUsuario()} adequado; caso contrário, faça a variação sem carga.`};
  if(valores.length===1) return{valor:menor,tipo:'referencia',texto:`${fmtKg(menor)} disponível. Confirme que a carga permite execução controlada e sem dor; use uma alternativa sem carga se necessário.`};
  return{valor:menor,tipo:'referencia',texto:`Referência conservadora disponível: ${fmtKg(menor)}. Confirme execução controlada e sem dor.`};
}
function cargaAtualRegistradaExercicio(nome){
  if(!exercicioUsaCargaNumerica(nome)) return 0;
  const hist=coletarHistoricoExecucoes(nome).slice().reverse();
  for(const item of hist){
    const log=item?.log||item||{};
    const valor=cargaRegistradaExercicio(nome,log);
    if(valor>0) return valor;
  }
  return 0;
}
function proximaCargaDisponivel(nome,cargaAtual,perfil=ST.perfil){
  if(!exercicioUsaCargaNumerica(nome)) return 0;
  return cargasDisponiveisExercicio(nome,perfil).find(v=>v>+cargaAtual)||0;
}
function proximaCargaRealDisponivel(nome,cargaAtual,perfil=ST.perfil){
  return proximaCargaDisponivel(nome,cargaAtual,perfil);
}
function numerosPositivos(v){
  return [...new Set(String(v||'').trim().split(/[;\/\s\n]+/).map(x=>parseFloat(x.replace(',','.'))).filter(n=>Number.isFinite(n)&&n>0))].sort((a,b)=>a-b);
}
function numeroDecimalPositivo(v){
  const n=parseFloat(String(v??'').trim().replace(',','.'));
  return Number.isFinite(n)&&n>0?n:0;
}
function numeroDecimalEstrito(valor){
  const txt=String(valor??'').trim();
  if(!txt) return null;
  if(!/^\d+(?:[.,]\d+)?$/.test(txt)) return NaN;
  const n=Number(txt.replace(',','.'));
  return Number.isFinite(n)?n:NaN;
}
function validarNumeroCorporal(valor,{min,max,campo,opcional=false}={}){
  const txt=String(valor??'').trim();
  if(!txt&&opcional) return{valido:true,valor:null};
  const n=numeroDecimalEstrito(txt);
  if(!Number.isFinite(n)||n<min||n>max){
    return{valido:false,valor:null,mensagem:`${campo} fora da faixa esperada. Informe um valor entre ${min} e ${max}.`};
  }
  return{valido:true,valor:n};
}
function validarIdade(valor,{opcional=false}={}){return validarNumeroCorporal(valor,{min:10,max:100,campo:'Idade',opcional});}
function validarAlturaCm(valor,{opcional=false}={}){
  const r=validarNumeroCorporal(valor,{min:100,max:230,campo:'Altura',opcional});
  if(!r.valido) r.mensagem='Altura fora da faixa esperada. Informe em centímetros, por exemplo 165.';
  return r;
}
function validarPesoKg(valor,{opcional=false}={}){return validarNumeroCorporal(valor,{min:25,max:250,campo:'Peso',opcional});}
function validarGorduraCorporal(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:3,max:70,campo:'Gordura corporal',opcional});}
function validarMassaMuscular(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:5,max:80,campo:'Massa muscular esquelética',opcional});}
function validarAguaCorporal(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:25,max:80,campo:'Água corporal',opcional});}
function validarMassaOssea(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:1,max:8,campo:'Massa óssea',opcional});}
function validarGorduraVisceral(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:1,max:30,campo:'Gordura visceral',opcional});}
function validarTmb(valor,{opcional=true}={}){return validarNumeroCorporal(valor,{min:800,max:4000,campo:'Metabolismo basal',opcional});}
function valorCorporalValido(campo,valor){
  const validadores={peso:validarPesoKg,gordura:validarGorduraCorporal,massaMuscular:validarMassaMuscular,aguaCorp:validarAguaCorporal,gordVisceral:validarGorduraVisceral,tmb:validarTmb};
  const r=(validadores[campo]||((v)=>({valido:Number.isFinite(+v),valor:+v})))(valor);
  return r.valido&&r.valor!=null?r.valor:null;
}
function parseCargaUnica(valor,equipamento=''){
  const txt=String(valor??'').trim();
  if(!txt) return{valido:true,valor:null};
  const n=numeroDecimalEstrito(txt);
  if(!Number.isFinite(n)||n<=0) return{valido:false,valor:null,mensagem:'Use apenas números. Para várias cargas, separe por ponto e vírgula: 8; 12; 16.'};
  if(!cargaPlausivelEquipamento(n,equipamento)) return{valido:false,valor:null,mensagem:'Informe um peso plausível para este equipamento.'};
  return{valido:true,valor:n};
}
function parseIncrementoCarga(valor){
  const txt=String(valor??'').trim();
  if(!txt) return{valido:true,valor:null};
  const n=numeroDecimalEstrito(txt);
  if(!Number.isFinite(n)||n<=0) return{valido:false,valor:null,mensagem:'Informe o incremento apenas com número decimal positivo, sem texto.'};
  return{valido:true,valor:n};
}
function numeroCargaRegistrada(valor,equipamento=''){
  const txt=String(valor??'').trim();
  if(!txt) return 0;
  const n=numeroDecimalEstrito(txt);
  if(!Number.isFinite(n)||n<=0) return 0;
  if(equipamento&&!cargaPlausivelEquipamento(n,equipamento)) return 0;
  return n;
}
function cargaRegistradaExercicio(exercicio,log={}){
  if(!exercicioUsaCargaNumerica(exercicio)) return 0;
  const info=obterCargasDisponiveisExercicio(exercicio,ST.perfil);
  const equipamento=info?.equipamento||chaveCargaExercicio(exercicio)||'';
  return numeroCargaRegistrada(log?.cargaKg??log?.cargaUsada??log?.carga,equipamento);
}
function parseListaCargas(valor,equipamento=''){
  const txt=String(valor??'').trim();
  if(!txt) return{valido:true,valores:[]};
  if(/^\d+(?:\s*,\s*\d+){2,}$/.test(txt)){
    return{valido:false,valores:[],mensagem:'Use apenas números. Para várias cargas, separe por ponto e vírgula: 8; 12; 16.'};
  }
  const partes=txt.split(/[;\/\n]+/).map(v=>v.trim()).filter(Boolean);
  if(!partes.length) return{valido:true,valores:[]};
  const valores=[];
  for(const parte of partes){
    const r=parseCargaUnica(parte,equipamento);
    if(!r.valido) return{valido:false,valores:[],mensagem:r.mensagem};
    valores.push(r.valor);
  }
  return{valido:true,valores:[...new Set(valores)].sort((a,b)=>a-b)};
}
function objetivosLegados(perfil={}){
  return arr(perfil.objetivos).filter(v=>v&&!['forca','massa','resist','calistenia','mobilidade','saude','def','seca','recomp','core'].includes(v));
}
// 166D — preserva a intenção do objetivo legado antes de limitar focos complementares.
function migrarObjetivosPerfil(perfil){
  const antigos=arr(perfil.objetivos);
  const principaisAtuais=['forca','massa','resist','calistenia','mobilidade','saude'];
  const mapaFoco={def:'reduzir_gordura',seca:'reduzir_gordura',recomp:'composicao',core:'core'};
  const primeiro=antigos[0]||'';
  const focoPrincipalLegado=mapaFoco[primeiro]||'';
  const principalValido=principaisAtuais.includes(primeiro)?primeiro:'';
  const principal=principalValido||(focoPrincipalLegado?'saude':'')||antigos.find(v=>principaisAtuais.includes(v))||'saude';
  const focosAtuais=arr(perfil.focosComplementares);
  const focosLegadosSecundarios=antigos.slice(1).map(v=>mapaFoco[v]).filter(Boolean);
  const ordemFocos=focoPrincipalLegado
    ?[focoPrincipalLegado,...focosAtuais,...focosLegadosSecundarios]
    :[...focosAtuais,...focosLegadosSecundarios];
  const desconhecidos=antigos.filter(v=>v&&![...principaisAtuais,'def','seca','recomp','core'].includes(v));
  perfil.objetivos=[principal,...desconhecidos];
  perfil.focosComplementares=[...new Set(ordemFocos)].slice(0,2);
  perfil.metaTecnica=perfil.metaTecnica||'';
  return perfil;
}
const ATIVS=[{k:'Pilates',n:'Pilates'},{k:'Yoga',n:'Yoga'},{k:'Corrida',n:'Corrida'},{k:'Caminhada',n:'Caminhada intensa'},{k:'Musculacao',n:'Musculação'},{k:'Natacao',n:'Natação'},{k:'Ciclismo',n:'Ciclismo'},{k:'Outros',n:'Outros'}];
function duracaoAtividadeMin(atividade={}){
  return Math.max(0,+atividade.duracaoMin||+atividade.duracao||0);
}
function atividadeRelevante(atividade={}){
  const k=normTxt(atividade.k||atividade.nome);
  const intensidade=normTxt(atividade.intensidade);
  const impacto=arr(atividade.impacto).map(normTxt);
  const prioridade=normTxt(atividade.prioridade);
  const duracao=duracaoAtividadeMin(atividade);
  if(['yoga','pilates'].includes(k)){
    const intensa=['forte','intensa','intenso'].includes(intensidade);
    const moderada=['moderada','moderado'].includes(intensidade);
    if(prioridade==='principal'||intensa) return true;
    if(moderada&&duracao>=60) return true;
    if(moderada&&duracao>=45&&impacto.some(v=>['core','lombar'].includes(v))) return true;
    return false;
  }
  return duracao>=45||['forte','intensa','intenso'].includes(intensidade)||prioridade==='principal'||impacto.length>0;
}

function classificarCargaAtividade(atividade={}){
  const k=normTxt(atividade.k||atividade.nome||atividade.atividade);
  const intensidade=normTxt(atividade.intensidade);
  const prioridade=normTxt(atividade.prioridade);
  const duracao=duracaoAtividadeMin(atividade);
  const areas=arr(atividade.impacto).map(normTxt).filter(Boolean);
  let nivel={leve:1,moderada:2,moderado:2,forte:3,intensa:3,intenso:3}[intensidade]||0;
  if(!nivel&&duracao>=75) nivel=2;
  else if(!nivel&&duracao>=45) nivel=1;
  if(!nivel&&areas.length) nivel=1;
  if(prioridade==='principal') nivel=Math.max(nivel,2);
  if(['corrida','musculacao'].includes(k)&&duracao>=45) nivel=Math.max(nivel,2);
  if(['corrida','musculacao','ciclismo','natacao'].includes(k)&&duracao>=75) nivel=Math.max(nivel,3);
  if(['yoga','pilates'].includes(k)&&nivel<3&&duracao<60&&prioridade!=='principal'&&!areas.some(v=>/core|lombar/.test(v))) nivel=Math.min(nivel,1);
  const padroes=new Set();
  const areaTxt=areas.join(' ');
  if(k==='musculacao'){
    if(/costas|puxar|biceps/.test(areaTxt)) padroes.add('puxar');
    if(/ombro|peitoral|triceps|empurrar/.test(areaTxt)) padroes.add('empurrar');
    if(/perna|quadriceps|posterior|gluteo|joelho|quadril|panturrilha/.test(areaTxt)) padroes.add('pernas');
    if(/core|lombar|abdomen/.test(areaTxt)) padroes.add('core');
    if(!padroes.size&&nivel>=2) ['puxar','empurrar','pernas','core'].forEach(v=>padroes.add(v));
  }else{
    if(k==='natacao'||/costas|puxar|nado|superior/.test(areaTxt)) padroes.add('puxar');
    if(/ombro|peitoral|triceps|empurrar/.test(areaTxt)||(k==='natacao'&&nivel>=2)) padroes.add('empurrar');
    if(['corrida','ciclismo','caminhada'].includes(k)||/perna|joelho|quadril|inferior|corrida|panturrilha/.test(areaTxt)) padroes.add('pernas');
    if(['pilates','yoga'].includes(k)||/core|lombar|abdomen/.test(areaTxt)) padroes.add('core');
  }
  return{
    k,nome:atividade.nome||atividade.k||atividade.atividade||'Atividade complementar',nivel,duracao,prioridade,areas,
    padroes:[...padroes],
    intensa:nivel>=3,
    relevante:['yoga','pilates'].includes(k)?atividadeRelevante(atividade):(atividadeRelevante(atividade)||nivel>=2),
    impactoArticular:['corrida','caminhada'].includes(k)&&nivel>=2,
    cargaExterna:k==='musculacao'&&nivel>=2
  };
}
function distanciaCircularDias(a,b){
  const d=Math.abs((+a||0)-(+b||0));
  return Math.min(d,7-d);
}
function estrategiaRetornoGradual(perfil={},prontidao=null){
  const pr=prontidao||avaliarProntidaoInicial(perfil);
  const freq=perfil.frequenciaRecente||'';
  const focoRetorno=arr(perfil.focosComplementares).includes('retorno');
  const cirurgia=cirurgiaTemLimitacaoAtiva(perfil);
  const dor=pr.temDor||regioesDorPerfil(perfil).size>0;
  const avancadoDestreinado=pr.nivelDeclarado==='avanc'&&pr.nivelEfetivo!=='avanc';
  const pausaLonga=freq==='nao';
  const rotinaBaixa=freq==='ocasional';
  const motivos=[];
  if(cirurgia) motivos.push('cirurgia ou recuperação registrada');
  if(dor) motivos.push('dor ou limitação ativa');
  if(focoRetorno) motivos.push('objetivo de retorno gradual');
  if(pausaLonga) motivos.push('pausa recente sem treino');
  else if(rotinaBaixa) motivos.push('rotina recente ocasional');
  if(avancadoDestreinado) motivos.push('nível avançado em reativação');
  let grau='nenhum';
  if(cirurgia||dor) grau='alto';
  else if(focoRetorno||pausaLonga) grau='moderado';
  else if(rotinaBaixa||avancadoDestreinado||pr.modo==='reativacao'||pr.modo==='calibracao') grau='leve';
  const ativa=grau!=='nenhum';
  return{
    ativa,grau,motivos,
    fatorVolume:grau==='alto'?.75:grau==='moderado'?.82:grau==='leve'?.9:1,
    bloquearAgressivos:grau==='alto'||grau==='moderado',
    limitarImpacto:grau!=='nenhum',
    limitarCore:grau==='alto'||grau==='moderado',
    avancadoDestreinado,pausaLonga,cirurgia,dor
  };
}
function alternativaRetornoExercicio(ex,perfil={}){
  const meta=metaExercicio(ex)||{};
  const pad=padraoExercicioCodigo(ex);
  const candidatos=[
    ...arr(meta.alternativas),
    ...({core:['Dead Bug','Bird Dog'],agachar:['Agachamento','Ponte de Glúteo','Ponte Unilateral'],dobrarQ:['Ponte de Glúteo','Ponte Unilateral'],empurrar:['Flexão inclinada','Flexão no Solo'],puxarV:['Remada com Elástico','Remada Invertida'],puxarH:['Remada com Elástico','Remada Invertida']}[pad]||[])
  ];
  const original=nomeTecnicoExercicio(ex)||ex?.n||'';
  const escolhido=candidatos.find(nome=>nome&&normTxt(nome)!==normTxt(original)&&EXD[nome]&&equipamentoDisponivel(nome,perfil));
  return escolhido||'';
}
function aplicarRetornoGradualTreino(treino,perfil={},estrategia=null){
  const e=estrategia||estrategiaRetornoGradual(perfil);
  if(!e.ativa||!treino||['descanso','atividade','recuperacao'].includes(treino.tipo)) return treino;
  const t=cloneObj(treino);
  const ajustar=(ex,bloco='ex')=>{
    if(!ex) return ex;
    const meta=metaExercicio(ex)||{};
    const riscos=arr(meta.riscos);
    const agressivo=meta.agressividade==='alta'||meta.coreAgressivo||meta.hingePesado||meta.salto||meta.impacto||riscos.some(r=>['core_agressivo','hinge_pesado','salto','impacto','instabilidade'].includes(r));
    let novo={...ex};
    if(e.bloquearAgressivos&&agressivo){
      const alt=alternativaRetornoExercicio(ex,perfil);
      if(alt) novo={...novo,n:alt,p:EXD[alt]?.prog||novo.p,nota:[novo.nota,`retorno gradual: ${ex.n} substituído por variação mais estável`].filter(Boolean).join(' · ')};
      else novo.nota=[novo.nota,'retorno gradual: use amplitude confortável, sem explosão e sem falha'].filter(Boolean).join(' · ');
    }
    const cap=bloco==='core'?(e.limitarCore?2:3):(e.grau==='alto'?3:e.grau==='moderado'?4:5);
    if(novo.s) novo.s=Math.max(1,Math.min(+novo.s||1,cap));
    if(e.grau!=='leve'&&novo.ds>0) novo.ds=Math.min(240,(+novo.ds||0)+15);
    if(bloco==='core'&&e.limitarCore) novo.nota=[novo.nota,'core de retorno: controle respiratório e sem bracing agressivo'].filter(Boolean).join(' · ');
    return novo;
  };
  t.ex=(t.ex||[]).map(ex=>ajustar(ex,'ex'));
  t.core=(t.core||[]).map(ex=>ajustar(ex,'core')).slice(0,e.limitarCore?2:3);
  t.ombro=(t.ombro||[]).map(ex=>ajustar(ex,'ombro')).slice(0,2);
  if(t.circ){
    const voltas=Math.min(+t.circ.voltas||2,e.grau==='leve'?3:2);
    t.circ={...t.circ,voltas:Math.max(2,voltas),dsEx:Math.max(+t.circ.dsEx||0,30),dsVolta:Math.max(+t.circ.dsVolta||0,75)};
    t.ex=t.ex.map(ex=>({...ex,s:t.circ.voltas,nota:[ex.nota,'circuito de retorno: ritmo controlado, sem buscar falha'].filter(Boolean).join(' · ')}));
  }
  t.nota=[t.nota,`Estratégia de retorno gradual (${e.grau}): ${e.motivos.join(', ')}.`].filter(Boolean).join(' · ');
  t.retornoGradual={ativo:true,grau:e.grau,motivos:e.motivos};
  return t;
}
function tiposTreinoRecentesEfetivos(perfil={}){
  return perfil.frequenciaRecente==='nao'?[]:arr(perfil.tiposTreinoRecentes).filter(Boolean);
}
function experienciaRecenteResumo(perfil={}){
  const freq=perfil.frequenciaRecente||'';
  const hist=String(perfil.historicoTreino||'').trim();
  const tipos=tiposTreinoRecentesEfetivos(perfil);
  const outro=tipos.includes('outro');
  const linhas=[];
  if(freq==='nao') linhas.push('Rotina recente de força: 0 treinos por semana. O plano inicia em readaptação.');
  else if(freq==='ocasional') linhas.push('Rotina recente de força: menos de 1 treino por semana. O volume inicial será conservador.');
  else if(freq==='1-2') linhas.push('Rotina recente de força: 1–2 treinos por semana. O plano começa com volume moderado.');
  else if(freq==='3-4') linhas.push('Rotina recente de força: 3–4 treinos por semana. Rotina compatível com progressão gradual.');
  else if(freq==='5+') linhas.push('Rotina recente de força: 5 ou mais treinos por semana. A carga total semanal será considerada antes de progredir.');
  if(hist) linhas.push(`${outro?'Outro treino relatado':'Atividade relatada'}: ${hist}.${['nao','ocasional'].includes(freq)?' Usada como contexto, não como base para aumento automático.':''}`);
  if(outro&&!hist) linhas.push('Outro treino relatado, sem detalhes.');
  const prontidao=avaliarProntidaoInicial(perfil);
  if(prontidao.nivelEfetivo!==prontidao.nivelDeclarado) linhas.push(`Calibração inicial: ${prontidao.motivoCalibracao}`);
  return linhas;
}
function avaliarProntidaoInicial(perfil={}){
  const nivelDeclarado=['init','inter','avanc'].includes(perfil.nivel)?perfil.nivel:'init';
  const freq=normalizarFrequenciaRecenteCalifit(perfil.frequenciaRecente||'');
  const tipos=new Set(tiposTreinoRecentesEfetivos(perfil));
  const frequenciaForcaInformada=['ocasional','1-2','3-4','5+'].includes(freq);
  const treinoResistido=frequenciaForcaInformada||[...tipos].some(v=>['calistenia','musculacao','funcional'].includes(v));
  const marcasPerfil=Object.assign({flexoes:0,barras:0,dips:0,agachamentoUnilateral:0,prancha:0,lSit:0},perfil.marcas||{});
  const marcas=Object.values(marcasPerfil).map(Number).filter(v=>v>0);
  const temMarcas=marcas.length>0;
  const temHistorico=!!String(perfil.historicoTreino||'').trim();
  const evidenciaAvancada=temHistorico||[...tipos].some(v=>['calistenia','musculacao','funcional'].includes(v))||(+marcasPerfil.flexoes>=15)||(+marcasPerfil.barras>=4)||(+marcasPerfil.dips>=5)||(+marcasPerfil.agachamentoUnilateral>=8)||(+marcasPerfil.prancha>=60)||(+marcasPerfil.lSit>=10);
  const retorno=(perfil.focosComplementares||[]).includes('retorno');
  const cirurgiaAtiva=cirurgiaTemLimitacaoAtiva(perfil);
  const limitacoesAtivas=(perfil.limitacoes||[]).some(v=>{
    if(!v||v==='nenhuma') return false;
    if(v==='recuperacao_lesao') return cirurgiaAtiva;
    return true;
  });
  const temDor=regioesDorPerfil(perfil).size>0||limitacoesAtivas;
  const evidenciasTecnicas=treinoResistido||temMarcas||temHistorico;
  const baixa=['nao','ocasional'].includes(freq)||retorno||cirurgiaAtiva;
  const alta=['3-4','5+'].includes(freq)&&evidenciasTecnicas&&!retorno&&!cirurgiaAtiva;
  const experienciaRecente=alta?'alta':baixa||!freq?'baixa':'media';
  let nivelEfetivo=nivelDeclarado;
  let modo='normal';

  if(nivelDeclarado==='avanc'){
    if(freq==='nao'||retorno||cirurgiaAtiva){nivelEfetivo='inter';modo='retorno';}
    else if(freq==='ocasional'||freq==='1-2'){nivelEfetivo='inter';modo='reativacao';}
    else if(['3-4','5+'].includes(freq)&&!evidenciaAvancada){nivelEfetivo='avanc';modo='calibracao';}
    else if(freq&&(!treinoResistido||!evidenciasTecnicas)){nivelEfetivo='inter';modo='calibracao';}
  }else if(nivelDeclarado==='inter'){
    // 163B1: preservar a base técnica intermediária mesmo após pausa.
    // A readaptação reduz volume e densidade, sem tornar o plano idêntico ao iniciante.
    if(freq==='nao'||retorno||cirurgiaAtiva){nivelEfetivo='inter';modo='retorno';}
    else if(freq==='ocasional'&&!treinoResistido){nivelEfetivo='inter';modo='reativacao';}
  }

  const configFrequencia=configFrequenciaRecenteCalifit(freq,perfil);
  let fatorVolumeInicial=configFrequencia.fatorVolumeInicial;
  if(nivelDeclarado==='avanc'&&nivelEfetivo==='avanc'&&modo==='calibracao') fatorVolumeInicial=Math.min(fatorVolumeInicial,.90);
  if(retorno||cirurgiaAtiva) fatorVolumeInicial=Math.min(fatorVolumeInicial,.82);
  if(temDor) fatorVolumeInicial=Math.min(fatorVolumeInicial,.9);

  const contradicoes=[];
  if(nivelDeclarado==='avanc'&&['nao','ocasional','1-2'].includes(freq)) contradicoes.push('Nível avançado com rotina recente insuficiente para começar em volume avançado pleno.');
  if(nivelDeclarado==='inter'&&freq==='nao') contradicoes.push('Nível intermediário após pausa recente: início em base de readaptação.');
  if(nivelDeclarado==='avanc'&&modo==='calibracao') contradicoes.push('Nível avançado ativo sem marcas ou histórico técnico suficientes: primeira semana usada como calibração.');
  if(nivelDeclarado!=='init'&&freq&&!evidenciasTecnicas) contradicoes.push('Há pouca evidência recente para confirmar o volume do nível declarado.');

  const calibrado=nivelEfetivo!==nivelDeclarado||fatorVolumeInicial<1;
  const motivoCalibracao=nivelEfetivo!==nivelDeclarado
    ?`${nivelLabel(nivelDeclarado)} preservado como experiência técnica, com base ${{init:'iniciante',inter:'intermediária',avanc:'avançada'}[nivelEfetivo]||nivelLabel(nivelEfetivo).toLowerCase()} no início.`
    :modo==='calibracao'?'Nível avançado preservado, com volume inicial reduzido até os primeiros check-ins confirmarem a tolerância.'
    :fatorVolumeInicial<1?'Volume inicial reduzido conforme a frequência recente e o contexto de segurança.':'';
  const configNivel=configNivelTreinoCalifit(nivelEfetivo,{nivelDeclarado,nivelEfetivo,modo,temDor,cirurgiaAtiva});
  return{
    nivelDeclarado,nivelEfetivo,modo,fatorVolumeInicial,calibrado,motivoCalibracao,frequenciaRecente:freq,
    experienciaRecente,dadosSuficientes:!!(freq||temMarcas||temHistorico||tipos.size),
    treinoResistido,temMarcas,temHistorico,evidenciaAvancada,temDor,cirurgiaAtiva,contradicoes,
    configFrequencia,configNivel,
    aplicarAdaptacao:calibrado||temDor||contradicoes.length>0
  };
}

