// ═══════════════════════════════════════════════════════════
function normTxt(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}

function nivelLabel(n){
  return {init:'Iniciante',inter:'Intermediário',avanc:'Avançado'}[n]||'Iniciante';
}
function cfgNivel(niv){
  const n=niv||'init';
  return {
    init:{label:'Iniciante',s:2,r:'6–8',ds:120,sC:2,rC:'20s',forcaS:3,forcaPadrao:3,forcaCurta:3,pernaBase:2,repsBarraCircuito:'3–5',repsEmpCircuito:'6–8',repsCore:'3–4',aqCompleto:false,forcaExtra:0,circVoltas:3,circDsEx:30,circDsVolta:75,complexidade:'estável',prog:'conservadora'},
    inter:{label:'Intermediário',s:3,r:'8–12',ds:90,sC:3,rC:'40s',forcaS:4,forcaPadrao:4,forcaCurta:4,pernaBase:3,repsBarraCircuito:'5',repsEmpCircuito:'10',repsCore:'6',aqCompleto:true,forcaExtra:1,circVoltas:4,circDsEx:25,circDsVolta:60,complexidade:'padrão',prog:'gradual'},
    avanc:{label:'Avançado',s:4,r:'10–15',ds:75,sC:3,rC:'45s',forcaS:5,forcaPadrao:5,forcaCurta:4,pernaBase:4,repsBarraCircuito:'5–6',repsEmpCircuito:'12',repsCore:'8',aqCompleto:true,forcaExtra:1,circVoltas:4,circDsEx:20,circDsVolta:60,complexidade:'avançada controlada',prog:'volume, tempo, alavanca, carga ou densidade'}
  }[n]||cfgNivel('init');
}
const ORDEM_NIVEL_PLANO={init:0,inter:1,avanc:2};

// 163M3 — nível técnico define complexidade, volume-base, densidade e velocidade de progressão.
// Frequência recente continua sendo tratada separadamente como capacidade de trabalho atual.
function configNivelTreinoCalifit(nivel='init',prontidao={}){
  const n=['init','inter','avanc'].includes(nivel)?nivel:'init';
  const base={
    init:{rotulo:'base técnica iniciante',maxPrincipal:3,maxAcessorio:2,maxCore:2,maxOmbro:2,maxVoltasCircuito:2,minDescansoPrincipal:105,minDescansoAcessorio:75,fatorProgressaoSemana3:1,foco:'técnica, controle e repetibilidade',complexidadeMaxima:'init'},
    inter:{rotulo:'base técnica intermediária',maxPrincipal:4,maxAcessorio:3,maxCore:3,maxOmbro:2,maxVoltasCircuito:4,minDescansoPrincipal:75,minDescansoAcessorio:60,fatorProgressaoSemana3:1.04,foco:'volume moderado, equilíbrio de padrões e progressão consistente',complexidadeMaxima:'inter'},
    avanc:{rotulo:'base técnica avançada',maxPrincipal:5,maxAcessorio:4,maxCore:3,maxOmbro:3,maxVoltasCircuito:5,minDescansoPrincipal:60,minDescansoAcessorio:45,fatorProgressaoSemana3:1.08,foco:'intensidade, alavanca, pausa, amplitude, carga e densidade',complexidadeMaxima:'avanc'}
  }[n];
  const nivelDeclarado=prontidao.nivelDeclarado||n;
  const modo=prontidao.modo||'normal';
  const avancadoEmRetorno=nivelDeclarado==='avanc'&&n==='inter';
  const calibracaoAvancada=nivelDeclarado==='avanc'&&n==='avanc'&&modo==='calibracao';
  const ajustada=calibracaoAvancada?{...base,maxPrincipal:4,maxAcessorio:3,maxVoltasCircuito:3,fatorProgressaoSemana3:1,foco:'calibração técnica avançada com volume inicial moderado'}:base;
  return Object.freeze({...ajustada,nivelEfetivo:n,nivelDeclarado,modo,avancadoEmRetorno,calibracaoAvancada});
}
function fatorPeriodizacaoNivelCalifit(nivel='init',semanaNoBloco=1,modo='normal'){
  const sem=Math.min(4,Math.max(1,+semanaNoBloco||1));
  const n=['init','inter','avanc'].includes(nivel)?nivel:'init';
  if(modo&&modo!=='normal') return 1;
  const mapa={
    init:{1:1,2:1,3:1,4:1},
    inter:{1:1,2:1,3:1.04,4:1},
    avanc:{1:1,2:1.03,3:1.08,4:1}
  };
  return mapa[n][sem];
}

// 163M2 — a frequência recente calibra capacidade de trabalho, não nível técnico.
// A mesma experiência declarada pode começar com volumes e densidades diferentes
// conforme a regularidade das últimas quatro semanas e a quantidade de dias planejados.
function normalizarFrequenciaRecenteCalifit(valor=''){
  const v=normTxt(valor).replace(/\s+/g,'').replace(/[–—_]/g,'-');
  if(['nao','não','0','nenhuma','retomando'].includes(v)) return 'nao';
  if(['ocasional','menosde1','<1'].includes(v)) return 'ocasional';
  if(['1-2','1a2','1ate2'].includes(v)) return '1-2';
  if(['3-4','3a4','3ate4'].includes(v)) return '3-4';
  if(['5+','5mais','5oumais'].includes(v)) return '5+';
  return '';
}
function configFrequenciaRecenteCalifit(frequencia='',perfil={}){
  const freq=normalizarFrequenciaRecenteCalifit(frequencia);
  const diasPlanejados=Math.max(1,arr(perfil?.diasTreino).length||3);
  const altaCargaSemanal=freq==='5+'&&diasPlanejados>=5;
  const base={
    '':{fatorVolumeInicial:.90,descansoExtra:10,maxExercicios:4,maxCore:2,maxOmbro:2,maxVoltasCircuito:3,maxNovosTempo:1,rotulo:'rotina recente não informada',progressao:'consolidação conservadora'},
    nao:{fatorVolumeInicial:.68,descansoExtra:25,maxExercicios:3,maxCore:1,maxOmbro:1,maxVoltasCircuito:2,maxNovosTempo:0,rotulo:'readaptação após pausa',progressao:'duas semanas de consolidação antes de ampliar volume'},
    ocasional:{fatorVolumeInicial:.80,descansoExtra:15,maxExercicios:4,maxCore:2,maxOmbro:1,maxVoltasCircuito:2,maxNovosTempo:1,rotulo:'retorno ocasional',progressao:'uma semana de consolidação antes de ampliar volume'},
    '1-2':{fatorVolumeInicial:.92,descansoExtra:5,maxExercicios:4,maxCore:2,maxOmbro:2,maxVoltasCircuito:3,maxNovosTempo:1,rotulo:'rotina moderada',progressao:'progressão após confirmar tolerância'},
    '3-4':{fatorVolumeInicial:1,descansoExtra:0,maxExercicios:5,maxCore:3,maxOmbro:2,maxVoltasCircuito:4,maxNovosTempo:2,rotulo:'rotina regular',progressao:'progressão gradual padrão'},
    '5+':{fatorVolumeInicial:altaCargaSemanal?.96:1,descansoExtra:altaCargaSemanal?5:0,maxExercicios:altaCargaSemanal?4:5,maxCore:altaCargaSemanal?2:3,maxOmbro:2,maxVoltasCircuito:altaCargaSemanal?3:4,maxNovosTempo:altaCargaSemanal?1:2,rotulo:altaCargaSemanal?'rotina alta com volume distribuído':'rotina alta',progressao:altaCargaSemanal?'progressão controlada pela carga semanal':'progressão gradual padrão'}
  }[freq];
  return Object.freeze({frequenciaRecente:freq,diasPlanejados,altaCargaSemanal,...base});
}
function fatorPeriodizacaoFrequenciaCalifit(frequencia='',semanaNoBloco=1,diasPlanejados=3){
  const sem=Math.min(4,Math.max(1,+semanaNoBloco||1));
  const freq=normalizarFrequenciaRecenteCalifit(frequencia);
  const altaCargaSemanal=freq==='5+'&&(+diasPlanejados||3)>=5;
  const mapa={
    '':{1:.85,2:.95,3:1.05,4:.55},
    nao:{1:.82,2:.90,3:1.00,4:.55},
    ocasional:{1:.85,2:.95,3:1.05,4:.55},
    '1-2':{1:.85,2:1.00,3:1.10,4:.52},
    '3-4':{1:.85,2:1.00,3:1.15,4:.50},
    '5+':altaCargaSemanal?{1:.85,2:.98,3:1.08,4:.50}:{1:.85,2:1.00,3:1.15,4:.50}
  };
  return mapa[freq][sem];
}
function nivelPermiteExercicio(nome,nivel='init'){
  const meta=metaExercicioPorNome(nome);
  const minimo=meta?.nivelMinimo||'init';
  return (ORDEM_NIVEL_PLANO[nivel]??0)>=(ORDEM_NIVEL_PLANO[minimo]??0);
}
function ajustarSeriesProntidao(ex,fator=1,minimo=2){
  if(!ex||!ex.s||fator>=1) return ex;
  const atuais=Math.max(1,+ex.s||1);
  if(atuais<=minimo) return ex;
  const calculado=fator>=.9?Math.round(atuais*fator):Math.floor(atuais*fator);
  const alvo=Math.max(minimo,calculado);
  return alvo<atuais?{...ex,s:alvo}:ex;
}
function normalizarTreinoPorNivelEProntidao(treino,nivel='init',prontidao={},perfil={}){
  if(!treino||['descanso','atividade','recuperacao'].includes(treino.tipo)) return treino;
  const t={...treino};
  const freq=prontidao.frequenciaRecente||perfil.frequenciaRecente||'';
  const configFrequencia=prontidao.configFrequencia||configFrequenciaRecenteCalifit(freq,perfil);
  const fator=Math.min(1,Math.max(.65,+prontidao.fatorVolumeInicial||configFrequencia.fatorVolumeInicial||1));
  const configNivel=prontidao.configNivel||configNivelTreinoCalifit(nivel,{...prontidao,nivelEfetivo:nivel});
  const caps={principal:configNivel.maxPrincipal,acessorio:configNivel.maxAcessorio,core:configNivel.maxCore,ombro:configNivel.maxOmbro,circuito:configNivel.maxVoltasCircuito};
  const ajustar=(ex,cap,minimo=2)=>{
    if(!ex||!ex.s) return ex;
    let novo={...ex,s:Math.max(1,Math.min(+ex.s||1,cap))};
    novo=ajustarSeriesProntidao(novo,fator,minimo);
    return novo;
  };
  const avancadoEmRetorno=prontidao.nivelDeclarado==='avanc'&&nivel==='inter';
  const capPrincipalFreq=(()=>{
    if(freq==='nao') return nivel==='init'?2:(avancadoEmRetorno?3:2);
    if(freq==='ocasional') return nivel==='init'?2:3;
    if(freq==='1-2') return nivel==='init'?3:(avancadoEmRetorno?4:3);
    return caps.principal;
  })();
  t.ex=(t.ex||[]).map((ex,i)=>{
    const minimoPrimeiro=avancadoEmRetorno
      ?(['nao','ocasional'].includes(freq)?3:4)
      :nivel==='init'?2:(nivel==='inter'?(freq==='nao'?2:3):4);
    const minimoSegundo=nivel==='init'?2:(nivel==='inter'?(freq==='nao'?2:3):3);
    const minimoPrincipal=i===0?minimoPrimeiro:i===1?minimoSegundo:2;
    const cap=i<2?Math.min(caps.principal,capPrincipalFreq):caps.acessorio;
    return ajustar(ex,cap,i<2?minimoPrincipal:2);
  });
  if(!t.circ&&t.ex.length>configFrequencia.maxExercicios) t.ex=t.ex.slice(0,configFrequencia.maxExercicios);
  t.core=(t.core||[]).map(ex=>ajustar(ex,Math.min(caps.core,configFrequencia.maxCore),nivel==='avanc'?3:2)).slice(0,configFrequencia.maxCore);
  t.ombro=(t.ombro||[]).map(ex=>ajustar(ex,Math.min(caps.ombro,configFrequencia.maxOmbro),1)).slice(0,configFrequencia.maxOmbro);
  if(t.circ){
    let voltas=Math.min(+t.circ.voltas||2,caps.circuito,configFrequencia.maxVoltasCircuito);
    if(fator<.9&&voltas>2) voltas--;
    t.circ={...t.circ,voltas:Math.max(2,voltas)};
    t.ex=t.ex.slice(0,configFrequencia.maxExercicios).map(ex=>({...ex,s:t.circ.voltas}));
  }
  if(configFrequencia.descansoExtra>0){
    const ampliarDescanso=ex=>ex&&(+ex.ds||0)>0?{...ex,ds:Math.min(240,(+ex.ds||0)+configFrequencia.descansoExtra)}:ex;
    t.ex=arr(t.ex).map(ampliarDescanso);
    t.core=arr(t.core).map(ampliarDescanso);
    t.ombro=arr(t.ombro).map(ampliarDescanso);
  }
  const descansoMinimoNivel=(ex,i=0,bloco='ex')=>{
    if(!ex||!(+ex.ds||0)) return ex;
    let minimo=bloco==='ex'?(i<2?configNivel.minDescansoPrincipal:configNivel.minDescansoAcessorio):configNivel.minDescansoAcessorio;
    if(t.tipo==='metabolico'||t.circ) minimo=Math.min(minimo,nivel==='init'?45:nivel==='inter'?30:20);
    return (+ex.ds||0)<minimo?{...ex,ds:minimo}:ex;
  };
  t.ex=arr(t.ex).map((ex,i)=>descansoMinimoNivel(ex,i,'ex'));
  t.core=arr(t.core).map((ex,i)=>descansoMinimoNivel(ex,i,'core'));
  t.ombro=arr(t.ombro).map((ex,i)=>descansoMinimoNivel(ex,i,'ombro'));
  if(t.circ){
    t.circ={...t.circ,dsEx:Math.max(+t.circ.dsEx||0,nivel==='init'?30:nivel==='inter'?25:20),dsVolta:Math.max(+t.circ.dsVolta||0,nivel==='init'?75:60)};
  }
  if(nivel==='avanc'&&!prontidao.calibrado&&!prontidao.temDor&&!prontidao.cirurgiaAtiva&&!t.circ){
    t.ex=t.ex.map((ex,i)=>{
      if(i>=2) return ex;
      const comSerie=(+ex.s||0)<4?{...ex,s:4}:{...ex};
      const notaNivel='Nível avançado: progrida por alavanca, pausa, amplitude, carga ou densidade sem perder a técnica.';
      return {...comSerie,nota:[comSerie.nota,!normTxt(comSerie.nota||'').includes(normTxt(notaNivel))?notaNivel:''].filter(Boolean).join(' · ')};
    });
  }else if(nivel==='init'&&t.ex.length){
    const notaNivel='Nível iniciante: priorize controle, amplitude confortável e repetições consistentes antes de dificultar a variação.';
    t.ex[0]={...t.ex[0],nota:[t.ex[0].nota,!normTxt(t.ex[0].nota||'').includes(normTxt(notaNivel))?notaNivel:''].filter(Boolean).join(' · ')};
  }
  t.calibracaoInicial={
    nivelDeclarado:prontidao.nivelDeclarado||nivel,
    nivelEfetivo:nivel,
    modo:prontidao.modo||'normal',
    fatorVolumeInicial:fator,
    frequenciaRecente:freq
  };
  t.calibracaoFrequencia={...configFrequencia,fatorVolumeAplicado:fator};
  t.calibracaoNivel={...configNivel};
  const notaNivelTreino=`Nível aplicado: ${configNivel.rotulo}; foco em ${configNivel.foco}.`;
  const notaFreq=`Frequência recente: ${configFrequencia.rotulo}; ${configFrequencia.progressao}.`;
  if(!normTxt(t.nota||'').includes(normTxt(notaNivelTreino))) t.nota=[t.nota,notaNivelTreino].filter(Boolean).join(' · ');
  if(!normTxt(t.nota||'').includes(normTxt(notaFreq))) t.nota=[t.nota,notaFreq].filter(Boolean).join(' · ');
  return aplicarRetornoGradualTreino(t,perfil,estrategiaRetornoGradual(perfil,prontidao));
}
function rotuloNivelPlano(prontidao={}){
  const declarado=nivelLabel(prontidao.nivelDeclarado||'init');
  const nivelEfetivo=prontidao.nivelEfetivo||prontidao.nivelDeclarado||'init';
  const efetivo=nivelLabel(nivelEfetivo);
  const base={init:'iniciante',inter:'intermediária',avanc:'avançada'}[nivelEfetivo]||efetivo.toLowerCase();
  return declarado===efetivo?declarado:`${declarado} em retorno · base ${base}`;
}

function equipamentoSet(perfil){
  const itens=normalizarEquipamentos(perfil?.equipamentos);
  return new Set(itens.length?itens:['Peso corporal']);
}
function textoPerfilSeguranca(perfil={}){
  const detalhes=Object.values(perfil.detalhesLimitacoes||{}).flatMap(d=>[d?.lado,d?.intensidade,d?.movimentos,d?.observacao]);
  return normTxt([
    ...(perfil.limitacoes||[]),
    ...(perfil.exerciciosEvitar||[]),
    ...detalhes,
  ].filter(Boolean).join(' '));
}
