function riscoMeta(meta,risco){return arr(meta?.riscos).includes(risco)||arr(meta?.padroes).includes(risco)||!!meta?.[risco];}
function exigenciasEquipamentoMeta(meta){return arr(meta?.exige||meta?.equipamentos).map(equipamentoNomePorExigencia).filter(Boolean);}
function equipamentoNomePorExigencia(token){
  const n=normTxt(token||'');
  const carga=equipamentoCanonicoExigencia(n);if(carga) return carga;
  if(/barra/.test(n)) return 'Barra fixa';
  if(/estacao/.test(n)) return 'Estação de barra';
  if(/paralela/.test(n)) return 'Barras paralelas';
  if(/argola/.test(n)) return 'Argolas';
  if(/trx|suspens/.test(n)) return 'TRX/Suspensão';
  if(/banco|cadeira/.test(n)) return 'Banco/Cadeira';
  if(/step|degrau/.test(n)) return 'Step/Degrau';
  if(/elastico|elástico|faixa/.test(n)) return 'Elásticos/faixas de resistência';
  if(/tapete|colchao|colchão/.test(n)) return 'Tapete/Colchão';
  if(/roda/.test(n)) return 'Roda abdominal';
  if(/corda/.test(n)) return 'Corda de pular';
  if(/bosu/.test(n)) return 'Bosu';
  if(/handgrip/.test(n)) return 'Handgrip';
  if(/peso corporal|nenhum/.test(n)) return 'Peso corporal';
  return '';
}
function categoriaMeta(meta){
  const p=arr(meta?.padroes);
  if(p.includes('mobilidade')) return 'mobilidade';
  if(p.includes('core')) return 'core';
  if(p.includes('empurrar')) return 'empurrar';
  if(p.includes('puxar')) return 'puxar';
  if(p.includes('agachar')) return 'pernas';
  if(p.includes('hinge')) return 'hinge';
  if(p.includes('metabolico')||p.includes('impacto')) return 'condicionamento';
  return 'forca';
}
function tipoPrescricaoMeta(nome,meta){
  const n=normTxt(nome);
  if(/hold|prancha|wall sit|respiracao|caminhada|mobilidade|alongamento/.test(n)) return 'tempo';
  return 'reps';
}
function normalizarMetaExercicio(nome,meta={}){
  const padrao=arr(meta.padrao||meta.padroes);
  const regioes=[...new Set([...arr(meta.regioes),...arr(meta.regioesPrimarias),...arr(meta.regioesSecundarias)])];
  const equipamentos=exigenciasEquipamentoMeta(meta);
  const riscos=arr(meta.riscos);
  return Object.assign({},meta,{nome,categoria:meta.categoria||categoriaMeta(meta),padrao,padroes:padrao,regioes,regioesPrimarias:arr(meta.regioesPrimarias),regioesSecundarias:arr(meta.regioesSecundarias),equipamentos,equipamentosNecessarios:equipamentos,nivelMinimo:meta.nivelMinimo||'init',agressividade:meta.agressividade||'media',tipoPrescricao:meta.tipoPrescricao||tipoPrescricaoMeta(nome,meta),unilateral:!!(meta.unilateral||padrao.includes('unilateral')),lado:meta.lado||(padrao.includes('unilateral')?'por lado':''),coreAgressivo:!!(meta.coreAgressivo||riscos.includes('core_agressivo')),bracingForte:!!(meta.bracingForte||riscos.includes('bracing_forte')),hingePesado:!!(meta.hingePesado||riscos.includes('hinge_pesado')),apoioPunho:!!(meta.apoioPunho||riscos.includes('apoio_punho')),overhead:!!(meta.overhead||riscos.includes('overhead')||padrao.includes('overhead')),impacto:!!(meta.impacto||riscos.includes('impacto')),salto:!!(meta.salto||riscos.includes('salto')),instabilidade:!!(meta.instabilidade||riscos.includes('instabilidade')||padrao.includes('instabilidade')),cargaExterna:!!(meta.cargaExterna||padrao.includes('carregado')||equipamentos.some(e=>EQUIPAMENTOS_EXIGEM_CARGA.includes(e))),amplitudeProfundaJoelho:!!(meta.amplitudeProfundaJoelho||riscos.includes('joelho_profundo')||riscos.includes('amplitude_profunda')),tracaoOmbroBarra:!!(meta.tracaoOmbroBarra||(padrao.includes('puxar')&&equipamentos.includes('Barra fixa'))),alternativas:arr(meta.alternativas)});
}
function nomeCanonicoMetaExercicio(nome){
  const n=normTxt(nome||'');
  return META_EXERCICIOS[nome]?nome:(ALIASES_META_EXERCICIOS[n]||Object.keys(META_EXERCICIOS).find(k=>normTxt(k)===n)||'');
}
function exerciciosSemMetadados(){return INVENTARIO_EXERCICIOS.filter(nome=>!metaExercicioPorNome(nome));}
function validarCoberturaMetadadosExercicios(){return{ok:!exerciciosSemMetadados().length,faltantes:exerciciosSemMetadados(),total:INVENTARIO_EXERCICIOS.length};}
function metaExercicioPorNome(nome){
  const can=nomeCanonicoMetaExercicio(nome);
  return can?normalizarMetaExercicio(can,META_EXERCICIOS[can]):null;
}
function metaExercicio(ex){
  return metaExercicioPorNome(nomeTecnicoExercicio(ex));
}
