// 163P1.1 — LIMPEZA TÉCNICA PRÉ-RELEASE: onboarding sem ações duplicadas e rotação automática segura de semanas.
// Mantém registros concluídos ao regenerar o plano, preserva várias atividades no mesmo dia
// e impede que uma atividade selecionada seja descartada silenciosamente por falta de dia.
// 163H: consolidação, auditoria local, lembrete de backup e consistência visual.
const APP_SCHEMA_VERSION=17;
const APP_RELEASE='68A';
const PWA_RELEASE=APP_RELEASE;
const DEF=()=>({
  schemaVersion:APP_SCHEMA_VERSION,
  perfil:{nome:'',genero:'M',peso:0,altura:0,idade:0,gordura:0,massaMuscular:0,nivel:'init',objetivos:[],focosComplementares:[],metaTecnica:'',equipamentos:[],cargasEquipamentos:{},limitacoes:[],estadoDoresOnboarding:'',detalhesLimitacoes:{},saude:{cirurgia:{tipo:'',data:'',regiao:'',status:'',liberacao:'',restricoes:'',movimentosEvitar:'',reavaliarEm:'',observacoes:'',atualizadoEm:''},condicoesGerais:'',orientacaoProfissional:''},ativExtras:[],diasTreino:[],tempoMaxTreino:0,metaPeso:0,metaGordura:0,historicoTreino:'',frequenciaRecente:'',tiposTreinoRecentes:[],contextoAtual:'',marcas:{flexoes:0,barras:0,dips:0,agachamentoUnilateral:0,prancha:0,lSit:0},doresAtuais:[],exerciciosEvitar:[],exerciciosPreferidos:[]},
  plano:null,planoBaseEstrutural:null,planoBaseSemTempo:null,planoBaseSemAtividadesRealizadas:null,semanas:[],checkins:[],contextoTreinador:{ultimoCheckinResumo:'',alertasAtuais:[],exerciciosFaceis:[],exerciciosDificeis:[],recomendacoesAtuais:[],ultimaIntencao:'',ultimaMensagem:'',ultimaRespostaEm:'',ultimaReferenciaTemporal:'',ultimaRegioes:[],ultimaAcaoEstado:'',ultimaAcaoResultado:''},previaProximaSemana:null,perfilAlterado:false,bio:[],pesoDiario:[],corpo:{historicoMetas:[]},lembretes:{ativo:true,treinoHoje:true,checkin:true,fecharSemana:true,corpoBio:true,backup:true,horarioTreino:'08:00',horarioCheckin:'20:00',horarioFecharSemana:'18:00',horarioCorpoBio:'08:00',corpoBioFrequenciaDias:7,backupFrequenciaDias:30,ultimoBackupEm:'',ultimoDismissPorTipo:{},adiadoAtePorTipo:{}},chat:[],exec:{},ajustesTempoDiario:{},manutencao:{ultimaRotacaoSemanasEm:'',semanasArquivadas:0,bytesLiberadosRotacao:0},ctx:'',done:false
});
let ST=DEF();
const STORAGE_KEY='cf8';
let _avisoFalhaSalvar=false;
let _avisoUsoStorage=false;
const _acoesCriticas=new Set();
let _toastTimer=null;

function arr(v){
  return Array.isArray(v)?v:[];
}
function normalizarTempoMaxTreino(valor){
  const n=Number(valor);
  // 163M1: migra o antigo limite de 40 min para a nova faixa de 45 min sem quebrar perfis salvos.
  if(n===40) return 45;
  return [10,20,30,45,60].includes(n)?n:0;
}
function normalizarLimiteAjusteTempoCalifit(valor){
  const n=Number(valor);
  if(n===40) return 45;
  return [10,15,20,30,45,60].includes(n)?n:0;
}
function normalizarTempoDisponivelHojeCalifit(valor){
  const n=Number(valor);
  // 166F — a antiga opção experimental de 15 min migra para 20 min.
  if(n===15) return 20;
  return [10,20,30,45,60].includes(n)?n:0;
}
function normalizarPreferenciasLembretesCalifit(prefs={}){
  const base=DEF().lembretes;
  const src=prefs&&typeof prefs==='object'&&!Array.isArray(prefs)?prefs:{};
  const dismiss=src.ultimoDismissPorTipo&&typeof src.ultimoDismissPorTipo==='object'&&!Array.isArray(src.ultimoDismissPorTipo)?src.ultimoDismissPorTipo:{};
  const adiado=src.adiadoAtePorTipo&&typeof src.adiadoAtePorTipo==='object'&&!Array.isArray(src.adiadoAtePorTipo)?src.adiadoAtePorTipo:{};
  const hora=(v,fallback)=>{
    const m=String(v||'').match(/^(\d{2}):(\d{2})$/);
    if(!m) return fallback;
    const h=+m[1],mn=+m[2];
    return h>=0&&h<=23&&mn>=0&&mn<=59?String(v):fallback;
  };
  const freq=Number(src.corpoBioFrequenciaDias);
  const freqBackup=Number(src.backupFrequenciaDias);
  const ultimoBackup=String(src.ultimoBackupEm||'').trim();
  const ultimoBackupValido=ultimoBackup&&!Number.isNaN(new Date(ultimoBackup).getTime())?new Date(ultimoBackup).toISOString():'';
  return{
    ativo:src.ativo!==false,
    treinoHoje:src.treinoHoje!==false,
    checkin:src.checkin!==false,
    fecharSemana:src.fecharSemana!==false,
    corpoBio:src.corpoBio!==false,
    backup:src.backup!==false,
    horarioTreino:hora(src.horarioTreino,'08:00'),
    horarioCheckin:hora(src.horarioCheckin,'20:00'),
    horarioFecharSemana:hora(src.horarioFecharSemana,'18:00'),
    horarioCorpoBio:hora(src.horarioCorpoBio,'08:00'),
    corpoBioFrequenciaDias:Number.isFinite(freq)&&freq>=1?Math.min(90,Math.floor(freq)):7,
    backupFrequenciaDias:Number.isFinite(freqBackup)&&freqBackup>=7?Math.min(180,Math.floor(freqBackup)):30,
    ultimoBackupEm:ultimoBackupValido,
    ultimoDismissPorTipo:Object.assign({},base.ultimoDismissPorTipo,dismiss),
    adiadoAtePorTipo:Object.assign({},base.adiadoAtePorTipo||{},adiado)
  };
}
function obterPreferenciasLembretesCalifit(){
  ST.lembretes=normalizarPreferenciasLembretesCalifit(ST.lembretes);
  return cloneObj(ST.lembretes);
}
function salvarPreferenciasLembretesCalifit(prefs){
  ST.lembretes=normalizarPreferenciasLembretesCalifit(Object.assign({},obterPreferenciasLembretesCalifit(),prefs||{}));
  salvar();
  return obterPreferenciasLembretesCalifit();
}
function ativarTodosTiposLembretesCalifit(){
  const prefs=obterPreferenciasLembretesCalifit();
  ['treinoHoje','checkin','fecharSemana','corpoBio','backup'].forEach(k=>prefs[k]=true);
  return salvarPreferenciasLembretesCalifit(prefs);
}
function desativarTodosTiposLembretesCalifit(){
  const prefs=obterPreferenciasLembretesCalifit();
  ['treinoHoje','checkin','fecharSemana','corpoBio','backup'].forEach(k=>prefs[k]=false);
  return salvarPreferenciasLembretesCalifit(prefs);
}
function chaveDiaLocalCalifit(d=new Date()){
  const x=new Date(d);
  return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
}
function lembreteDispensadoHojeCalifit(tipo,agora=new Date()){
  const prefs=obterPreferenciasLembretesCalifit();
  return prefs.ultimoDismissPorTipo?.[tipo]===chaveDiaLocalCalifit(agora);
}
function minutosHorarioCalifit(hhmm){
  const m=String(hhmm||'').match(/^(\d{2}):(\d{2})$/);
  if(!m) return 0;
  const h=Math.max(0,Math.min(23,+m[1]||0));
  const mnt=Math.max(0,Math.min(59,+m[2]||0));
  return h*60+mnt;
}
function minutosAgoraCalifit(d=new Date()){
  const x=new Date(d);
  return x.getHours()*60+x.getMinutes();
}
function lembreteAdiadoCalifit(tipo,agora=new Date()){
  const prefs=obterPreferenciasLembretesCalifit();
  const ate=prefs.adiadoAtePorTipo?.[tipo];
  return !!(ate&&new Date(ate)>new Date(agora));
}
function dispensarLembreteCalifit(tipo,agoraOpcional=new Date()){
  const prefs=obterPreferenciasLembretesCalifit();
  prefs.ultimoDismissPorTipo=Object.assign({},prefs.ultimoDismissPorTipo,{[tipo]:chaveDiaLocalCalifit(agoraOpcional)});
  ST.lembretes=prefs;
  salvar();
  return obterPreferenciasLembretesCalifit();
}
function adiarLembreteCalifit(tipo,minutos=60,agoraOpcional=new Date()){
  const prefs=obterPreferenciasLembretesCalifit();
  const ate=new Date(agoraOpcional);
  ate.setMinutes(ate.getMinutes()+Math.max(5,+minutos||60));
  prefs.adiadoAtePorTipo=Object.assign({},prefs.adiadoAtePorTipo,{[tipo]:ate.toISOString()});
  ST.lembretes=prefs;
  salvar();
  return obterPreferenciasLembretesCalifit();
}
function limparDismissLembretesCalifit(tipoOpcional,agoraOpcional=new Date()){
  const prefs=obterPreferenciasLembretesCalifit();
  const hoje=chaveDiaLocalCalifit(agoraOpcional);
  const atual=Object.assign({},prefs.ultimoDismissPorTipo||{});
  if(tipoOpcional) delete atual[tipoOpcional];
  else Object.keys(atual).forEach(k=>{if(atual[k]===hoje) delete atual[k];});
  prefs.ultimoDismissPorTipo=atual;
  ST.lembretes=prefs;
  salvar();
  return obterPreferenciasLembretesCalifit();
}
function registrosFeitosSemanaCalifit(sem=getSem()){
  return Object.values(sem?.registros||{}).filter(r=>r?.tipo==='feito'&&r.treino);
}
function ultimoRegistroDataCalifit(lista=[]){
  return arr(lista).slice().sort((a,b)=>new Date(b.data||0)-new Date(a.data||0))[0]||null;
}
function diasDesdeDataCalifit(data,agora=new Date()){
  if(!data) return Infinity;
  const a=inicioDiaLocal(agora).getTime();
  const d=inicioDiaLocal(data).getTime();
  return Math.max(0,Math.floor((a-d)/86400000));
}
function haDadosRelevantesParaBackupCalifit(){
  const semanasComRegistro=arr(ST.semanas).some(s=>Object.keys(s?.registros||{}).length>0);
  return semanasComRegistro||arr(ST.checkins).length>0||arr(ST.pesoDiario).length>=2||arr(ST.bio).length>0;
}
function statusBackupLocalCalifit(agoraOpcional=new Date()){
  const agora=new Date(agoraOpcional);
  const prefs=obterPreferenciasLembretesCalifit();
  const ultimo=prefs.ultimoBackupEm?new Date(prefs.ultimoBackupEm):null;
  const dias=ultimo&&!Number.isNaN(ultimo.getTime())?diasDesdeDataCalifit(ultimo,agora):Infinity;
  const frequencia=Math.max(7,+prefs.backupFrequenciaDias||30);
  return{
    temDados:haDadosRelevantesParaBackupCalifit(),
    ultimoBackupEm:ultimo&&!Number.isNaN(ultimo.getTime())?ultimo.toISOString():'',
    diasDesdeBackup:dias,
    frequenciaDias:frequencia,
    pendente:haDadosRelevantesParaBackupCalifit()&&(!ultimo||dias>=frequencia)
  };
}
function candidatosLembretesCalifit(agoraOpcional){
  const agora=agoraOpcional?new Date(agoraOpcional):new Date();
  const prefs=obterPreferenciasLembretesCalifit();
  if(!prefs.ativo) return [];
  const sem=getSem();
  const hoje=agora.getDay();
  const dia=ST.plano?.dias?.[hoje];
  const regHoje=sem?.registros?.[hoje];
  const itens=[];
  const add=item=>{
    if(!item||!prefs[item.tipo]) return;
    if(lembreteAdiadoCalifit(item.tipo,agora)) return;
    itens.push(item);
  };
  if(dia&&dia.tipo!=='descanso'&&dia.tipo!=='atividade'&&regHoje?.tipo!=='feito'){
    const cedo=minutosAgoraCalifit(agora)<minutosHorarioCalifit(prefs.horarioTreino);
    add({tipo:'treinoHoje',titulo:'Treino do dia',texto:`Hoje tem ${dia.nome||tipoLabel(dia.tipo)}.`,acao:'Abrir treino de hoje',tab:0,prioridade:cedo?5:90,suave:cedo});
  }
  const feitos=registrosFeitosSemanaCalifit(sem);
  const incompleto=ultimoRegistroDataCalifit(feitos.filter(r=>!checkinMinimoCompleto(r.treino||r)));
  if(incompleto){
    const cedo=minutosAgoraCalifit(agora)<minutosHorarioCalifit(prefs.horarioCheckin);
    add({tipo:'checkin',titulo:'Check-in pendente',texto:'Há treino concluído com feedback mínimo incompleto.',acao:'Fazer check-in',tab:1,prioridade:cedo?60:95,suave:cedo});
  }
  const pertoFim=hoje>=5;
  const checkSemana=(ST.checkins||[]).some(c=>String(c.semanaId)===String(sem?.id));
  if(semanaComPreviaPendente(sem)){
    add({tipo:'fecharSemana',titulo:'Próxima semana pronta para revisão',texto:'A semana terminou e a prévia foi preservada para você revisar antes de aplicar.',acao:'Revisar prévia',tab:1,prioridade:98,suave:false});
  }else if(sem?.aberta&&pertoFim&&(feitos.length>=1||checkSemana)){
    const cedo=minutosAgoraCalifit(agora)<minutosHorarioCalifit(prefs.horarioFecharSemana);
    add({tipo:'fecharSemana',titulo:'Fechar semana',texto:'Revise a semana e gere a prévia quando estiver pronto.',acao:'Fechar semana',tab:1,prioridade:cedo?40:85,suave:cedo});
  }
  const peso=registroPesoMaisRecente(ST);
  const bio=ultimoRegistroDataCalifit(ST.bio||[]);
  const freq=prefs.corpoBioFrequenciaDias||7;
  const pesoAntigo=!peso||diasDesdeDataCalifit(peso.data,agora)>=freq;
  const bioAntiga=!bio||diasDesdeDataCalifit(bio.data,agora)>=Math.max(freq,30);
  if(pesoAntigo||bioAntiga){
    const cedo=minutosAgoraCalifit(agora)<minutosHorarioCalifit(prefs.horarioCorpoBio);
    add({tipo:'corpoBio',titulo:'Atualizar corpo',texto:pesoAntigo?'Peso sem atualização recente.':'Bioimpedância sem atualização recente.',acao:'Atualizar corpo',tab:2,prioridade:cedo?10:70,suave:cedo});
  }
  const backup=statusBackupLocalCalifit(agora);
  if(backup.pendente){
    const texto=backup.ultimoBackupEm?`Último backup há ${backup.diasDesdeBackup} dias.`:'Você já tem histórico local e ainda não registrou um backup.';
    add({tipo:'backup',titulo:'Proteger seu histórico',texto,acao:'Exportar backup',tab:3,prioridade:65,suave:true});
  }
  return itens.sort((a,b)=>(b.prioridade||0)-(a.prioridade||0));
}
function avaliarLembretesComDispensadosCalifit(agoraOpcional){
  const agora=agoraOpcional?new Date(agoraOpcional):new Date();
  const todos=candidatosLembretesCalifit(agora);
  const ativos=[],dispensadosHoje=[];
  todos.forEach(item=>{
    if(lembreteDispensadoHojeCalifit(item.tipo,agora)) dispensadosHoje.push(item);
    else ativos.push(item);
  });
  return{ativos,dispensadosHoje};
}
function avaliarLembretesCalifit(agoraOpcional){
  return avaliarLembretesComDispensadosCalifit(agoraOpcional).ativos.slice(0,3);
}
function limparMetadadosTempoPlano(plano){
  if(!plano) return plano;
  const limpo=cloneObj(plano);
  delete limpo._baseSemTempo;
  delete limpo._baseEstrutural;
  Object.values(limpo.dias||{}).forEach(dia=>{
    if(!dia) return;
    ['duracaoOriginal','duracaoAjustada','tempoMaxAplicado','tempoAlvoAplicado','tempoAlvoMin','tempoAlvoMax','tempoSemLimite','ajusteTempo','ajustesTempo','avisoTempo','tempoDiarioAplicado','tempoDiarioLimite','tempoDiarioData','tempoDiarioOrigem','tempoLimiteCumprido','tempoAbaixoFaixaJustificado','justificativaTempo'].forEach(k=>delete dia[k]);
  });
  return limpo;
}
function limparMetadadosTemporaisEPeriodizacao(plano){
  const limpo=limparMetadadosTempoPlano(plano);
  if(!limpo) return limpo;
  delete limpo._baseSemTempo;
  delete limpo._baseEstrutural;
  delete limpo.planoOrigem;
  delete limpo.planoBaseOrigem;
  delete limpo.planoBaseSemTempo;
  delete limpo.planoBaseEstrutural;
  delete limpo.alteracoesAplicadas;
  delete limpo.alteracoes;
  delete limpo.resumoAjustes;
  delete limpo.checkinId;
  delete limpo.criadaEm;
  delete limpo.semanaOrigemId;
  delete limpo.tipoSemana;
  delete limpo.semanaNoBloco;
  Object.values(limpo.dias||{}).forEach(dia=>{
    if(!dia) return;
    delete dia.tipoSemana;
    ['aq','ex','core','ombro'].forEach(bloco=>{
      dia[bloco]=(dia[bloco]||[]).map(ex=>{
        const e={...ex};
        delete e.__volumeAjustado;
        delete e.ocorrenciaKey;
        delete e.diaIdx;
        delete e.bloco;
        delete e.indice;
        return e;
      });
    });
  });
  return limpo;
}
function separarPlanoBaseEstrutural(plano){
  return limparMetadadosTemporaisEPeriodizacao(plano?._baseEstrutural||plano?._baseSemTempo||plano);
}
function separarPlanoBaseSemTempo(plano){
  const base=limparMetadadosTempoPlano(plano?._baseSemTempo||plano);
  const visivel=cloneObj(plano);
  if(visivel) delete visivel._baseSemTempo;
  return{base,visivel};
}
function instalarPlanoGerado(planoGerado){
  ST.ajustesTempoDiario={};
  ST.planoBaseEstrutural=separarPlanoBaseEstrutural(planoGerado);
  ST.planoBaseSemTempo=limparMetadadosTempoPlano(planoGerado?._baseSemTempo||ST.planoBaseEstrutural||planoGerado);
  ST.planoBaseSemAtividadesRealizadas=cloneObj(ST.planoBaseSemTempo);
  ST.plano=ajustarPlanoAoTempo(cloneObj(ST.planoBaseSemTempo),ST.perfil);
  if(ST.plano) delete ST.plano._baseSemTempo;
  if(ST.plano) delete ST.plano._baseEstrutural;
}
function normalizarSaudePerfil(perfil={}){
  const base=DEF().perfil.saude;
  const saude=Object.assign({},base,perfil.saude||{});
  saude.cirurgia=Object.assign({},base.cirurgia,saude.cirurgia||{});
  const statusPermitidos=['','nao_informado','historico','recuperacao','limitacao_ativa','resolvida'];
  const liberacoesPermitidas=['','nao_informada','nao_liberado','parcial','total'];
  if(!statusPermitidos.includes(saude.cirurgia.status)) saude.cirurgia.status='';
  if(!liberacoesPermitidas.includes(saude.cirurgia.liberacao)) saude.cirurgia.liberacao='';
  if(cirurgiaVaziaOuPadrao(saude.cirurgia)) saude.cirurgia=cirurgiaVaziaCalifit();
  perfil.saude=saude;
  return saude;
}
function cirurgiaVaziaCalifit(){return Object.assign({},DEF().perfil.saude.cirurgia);}
function cirurgiaVaziaOuPadrao(c={}){
  const texto=String([c.tipo,c.data,c.regiao,c.restricoes,c.movimentosEvitar,c.reavaliarEm,c.observacoes].filter(v=>!valorVazioUsuario(v)).join(' ')).trim();
  const st=normalizarStatusSaude(c.status);
  const lib=normalizarLiberacaoSaude(c.liberacao);
  return !texto&&(!st||st==='nao_informado')&&(!lib||lib==='nao_informada');
}
function cirurgiaTemConteudoRelevante(c={}){
  if(!c||typeof c!=='object') return false;
  if(cirurgiaVaziaOuPadrao(c)) return false;
  const texto=String([c.tipo,c.data,c.regiao,c.restricoes,c.movimentosEvitar,c.reavaliarEm,c.observacoes].filter(v=>!valorVazioUsuario(v)).join(' ')).trim();
  const st=normalizarStatusSaude(c.status);
  const lib=normalizarLiberacaoSaude(c.liberacao);
  return !!texto||!!(st&&st!=='nao_informado')||!!(lib&&lib!=='nao_informada');
}
function limparCirurgiaSeSemConteudo(saude={}){
  const s=Object.assign({},DEF().perfil.saude,saude||{});
  s.cirurgia=Object.assign({},DEF().perfil.saude.cirurgia,s.cirurgia||{});
  if(!cirurgiaTemConteudoRelevante(s.cirurgia)) s.cirurgia=cirurgiaVaziaCalifit();
  return s;
}
function normalizarDorLegadaValor(v){
  const n=normTxt(v);
  if(!n) return '';
  if(dorNegativa(v)||/^(nao|não|sem dor)$/.test(n)) return 'nao';
  if(/leve/.test(n)) return 'leve';
  if(/moderad/.test(n)) return 'moderada';
  if(/forte|aguda|irradiad|piorando/.test(n)) return 'forte';
  return v;
}
function inferirRegiaoDorLegada(log={}){
  const txt=[log.dorRegiao,log.regiaoDor,log.obs,log.observacoes,log.comentario,log.comentarios].filter(Boolean).join(' ');
  const info=analisarDorTexto(txt);
  return info.temDor&&info.regioes?.length?info.regioes[0]:'';
}
function normalizarDorRegistroMigracao(log){
  if(!log||typeof log!=='object') return log;
  const dorNorm=normalizarDorLegadaValor(log.dor);
  if(dorNorm!==log.dor) log.dor=dorNorm;
  if(!log.dorRegiao){
    const reg=inferirRegiaoDorLegada(log);
    if(reg) log.dorRegiao=reg;
  }
  return log;
}
function normalizarDoresEstadoMigracao(estado){
  const normalizarEx=ex=>{
    if(!ex||typeof ex!=='object') return;
    normalizarDorRegistroMigracao(ex);
    if(ex.log) normalizarDorRegistroMigracao(ex.log);
  };
  Object.values(estado.exec||{}).forEach(normalizarDorRegistroMigracao);
  arr(estado.semanas).forEach(sem=>Object.values(sem?.registros||{}).forEach(reg=>{
    arr(reg?.treino?.exercicios).forEach(normalizarEx);
    arr(reg?.exercicios).forEach(normalizarEx);
  }));
}
function previaProximaSemanaIncompativel(preview){
  if(!preview) return false;
  const resumo=arr(preview.resumoAjustes);
  const motivos=arr(preview.motivos||preview.motivosAjuste);
  return !preview.decisaoPrevia||!preview.confianca||(!resumo.length&&!motivos.length);
}
function numeroCorporalMigrado(valor,validador){
  if(valor==null||valor===''||Number(valor)===0) return 0;
  const r=validador(valor,{opcional:true});
  return r.valido&&r.valor!=null?r.valor:0;
}
function migrarEstadoSalvo(dados){
  const base=DEF();
  const src=dados&&typeof dados==='object'&&!Array.isArray(dados)?dados:{};
  const perfil=Object.assign({},base.perfil,src.perfil||{});
  if(!['init','inter','avanc'].includes(perfil.nivel)) perfil.nivel='init';
  perfil.idade=numeroCorporalMigrado(perfil.idade,validarIdade);
  perfil.peso=numeroCorporalMigrado(perfil.peso,validarPesoKg);
  perfil.altura=numeroCorporalMigrado(perfil.altura,validarAlturaCm);
  perfil.gordura=numeroCorporalMigrado(perfil.gordura,validarGorduraCorporal);
  perfil.massaMuscular=numeroCorporalMigrado(perfil.massaMuscular,validarMassaMuscular);
  perfil.metaPeso=numeroCorporalMigrado(perfil.metaPeso,validarPesoKg);
  perfil.metaGordura=numeroCorporalMigrado(perfil.metaGordura,validarGorduraCorporal);
  perfil.marcas=Object.fromEntries(Object.entries(Object.assign({},base.perfil.marcas,perfil.marcas||{})).map(([k,v])=>[k,Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100000?Number(v):0]));
  perfil.objetivos=arr(perfil.objetivos);
  perfil.focosComplementares=arr(perfil.focosComplementares);
  perfil.tiposTreinoRecentes=perfil.frequenciaRecente==='nao'?[]:arr(perfil.tiposTreinoRecentes);
  perfil.equipamentos=normalizarEquipamentos(perfil.equipamentos);
  perfil.limitacoes=arr(perfil.limitacoes);
  perfil.ativExtras=arr(perfil.ativExtras);
  perfil.diasTreino=arr(perfil.diasTreino);
  perfil.tempoMaxTreino=normalizarTempoMaxTreino(perfil.tempoMaxTreino);
  perfil.doresAtuais=arr(perfil.doresAtuais);
  perfil.exerciciosEvitar=arr(perfil.exerciciosEvitar);
  perfil.exerciciosPreferidos=arr(perfil.exerciciosPreferidos);
  const cargasSrc={
    ...((perfil.cargas&&typeof perfil.cargas==='object'&&!Array.isArray(perfil.cargas))?perfil.cargas:{}),
    ...((perfil.pesosEquipamentos&&typeof perfil.pesosEquipamentos==='object'&&!Array.isArray(perfil.pesosEquipamentos))?perfil.pesosEquipamentos:{}),
    ...((perfil.cargasEquipamentos&&typeof perfil.cargasEquipamentos==='object'&&!Array.isArray(perfil.cargasEquipamentos))?perfil.cargasEquipamentos:{})
  };
  const cargasNormalizadas={};
  Object.entries(cargasSrc).forEach(([k,v])=>{
    const eq=normalizarEquipamentoNome(k),atual=cargasNormalizadas[eq];
    const candidato=normalizarConfigCarga(v,eq);
    const valoresAtuais=atual?valoresConfiguraveisCarga(atual):[];
    const valoresCandidato=valoresConfiguraveisCarga(candidato);
    cargasNormalizadas[eq]=valoresCandidato.length>=valoresAtuais.length?candidato:atual;
  });
  perfil.cargasEquipamentos=cargasNormalizadas;
  // Compatibilidade 163J1: perfis antigos que já tinham “Elásticos” recebem
  // explicitamente “Não sei o tipo”. Novas seleções continuam vazias até o usuário decidir.
  if(perfil.equipamentos.includes('Elásticos/faixas de resistência')){
    const chaveElastico='Elásticos/faixas de resistência';
    const cfgElastico=perfil.cargasEquipamentos[chaveElastico]||{};
    if(!Object.prototype.hasOwnProperty.call(cfgElastico,'tipos')){
      perfil.cargasEquipamentos[chaveElastico]={...cfgElastico,tipos:['generico'],tiposConfirmados:true};
    }
  }
  perfil.detalhesLimitacoes=perfil.detalhesLimitacoes&&typeof perfil.detalhesLimitacoes==='object'&&!Array.isArray(perfil.detalhesLimitacoes)?perfil.detalhesLimitacoes:{};
  const tinhaSaude=!!(src.perfil?.saude&&typeof src.perfil.saude==='object');
  normalizarSaudePerfil(perfil);
  if(!tinhaSaude&&perfil.limitacoes.includes('recuperacao_lesao')){
    perfil.saude.cirurgia.status='recuperacao';
    perfil.saude.cirurgia.liberacao='nao_informada';
  }
  migrarObjetivosPerfil(perfil);
  if(!perfil.contextoAtual&&src.ctx) perfil.contextoAtual=String(src.ctx);
  const contextoTreinador=Object.assign({},base.contextoTreinador,src.contextoTreinador||{});
  contextoTreinador.alertasAtuais=arr(contextoTreinador.alertasAtuais);
  contextoTreinador.exerciciosFaceis=arr(contextoTreinador.exerciciosFaceis);
  contextoTreinador.exerciciosDificeis=arr(contextoTreinador.exerciciosDificeis);
  contextoTreinador.recomendacoesAtuais=arr(contextoTreinador.recomendacoesAtuais);
  const corpo=Object.assign({},base.corpo,src.corpo||{});
  corpo.historicoMetas=arr(corpo.historicoMetas);
  const lembretes=normalizarPreferenciasLembretesCalifit(src.lembretes||base.lembretes);
  const manutencao=Object.assign({},base.manutencao,src.manutencao&&typeof src.manutencao==='object'&&!Array.isArray(src.manutencao)?src.manutencao:{});
  manutencao.semanasArquivadas=Math.max(0,+manutencao.semanasArquivadas||0);
  manutencao.bytesLiberadosRotacao=Math.max(0,+manutencao.bytesLiberadosRotacao||0);
  manutencao.ultimaRotacaoSemanasEm=String(manutencao.ultimaRotacaoSemanasEm||'');
  const planoBaseEstrutural=separarPlanoBaseEstrutural(src.planoBaseEstrutural||src.planoBaseSemTempo||src.plano||null);
  const planoBaseSemTempo=limparMetadadosTempoPlano(src.planoBaseSemTempo||src.plano||planoBaseEstrutural||null);
  const plano=src.plano?cloneObj(src.plano):null;
  if(plano) delete plano._baseSemTempo;
  const estado=Object.assign({},base,src,{
    schemaVersion:APP_SCHEMA_VERSION,
    perfil,
    contextoTreinador,
    corpo,
    lembretes,
    manutencao,
    plano,
    planoBaseEstrutural,
    planoBaseSemTempo,
    semanas:arr(src.semanas),
    checkins:arr(src.checkins),
    bio:arr(src.bio).filter(r=>r&&typeof r==='object'&&!Array.isArray(r)).map(r=>({
      ...r,
      peso:numeroCorporalMigrado(r.peso,validarPesoKg),
      gordura:numeroCorporalMigrado(r.gordura,validarGorduraCorporal),
      massaMuscular:numeroCorporalMigrado(r.massaMuscular,validarMassaMuscular),
      aguaCorp:numeroCorporalMigrado(r.aguaCorp,validarAguaCorporal),
      gordVisceral:numeroCorporalMigrado(r.gordVisceral,validarGorduraVisceral),
      tmb:numeroCorporalMigrado(r.tmb,validarTmb)
    })),
    pesoDiario:arr(src.pesoDiario).filter(r=>r&&typeof r==='object'&&!Array.isArray(r)&&validarPesoKg(r.peso).valido).map(r=>({...r,peso:validarPesoKg(r.peso).valor})),
    chat:arr(src.chat),
    exec:src.exec&&typeof src.exec==='object'&&!Array.isArray(src.exec)?src.exec:{},
    ajustesTempoDiario:normalizarAjustesTempoDiarioCalifit(src.ajustesTempoDiario)
  });
  if(!estado.ctx&&perfil.contextoAtual) estado.ctx=perfil.contextoAtual;
  normalizarDoresEstadoMigracao(estado);
  if((+src.schemaVersion||0)<17&&previaProximaSemanaIncompativel(estado.previaProximaSemana)) estado.previaProximaSemana=null;
  normalizarPrescricoesPlanoCalifit(estado.plano);
  normalizarPrescricoesPlanoCalifit(estado.planoBaseEstrutural);
  normalizarPrescricoesPlanoCalifit(estado.planoBaseSemTempo);
  estado.semanas.forEach(sem=>normalizarPrescricoesPlanoCalifit(sem?.plano||sem));
  return estado;
}
const LIMITE_SEMANAS_COMPLETAS_CALIFIT=12;
const LIMITE_SEMANAS_COMPLETAS_PRESSAO_CALIFIT=8;
function estimarBytesEstadoCalifit(estado=ST){
  try{return JSON.stringify(estado||{}).length*2;}catch(e){return 0;}
}
function semanaElegivelRotacaoCalifit(sem,estado=ST){
  if(!sem||sem.aberta||sem.fechada!==true||semanaOcultaCalifit(sem)) return false;
  if(idSemanaIgualCalifit(sem.id,estado?.semanaAtual)) return false;
  if(estado?.previaProximaSemana&&idSemanaIgualCalifit(sem.id,estado.previaProximaSemana.semanaOrigemId)) return false;
  return true;
}
function compactarSemanaArquivadaCalifit(sem,agora=new Date()){
  if(!sem||typeof sem!=='object') return{alterada:false,bytesLiberados:0};
  const jaArquivada=sem.arquivada===true&&sem.compactada===true;
  const antes=JSON.stringify(sem).length*2;
  [
    'planoAntesFechamento','planoBaseAntesFechamento','planoBaseEstruturalAntesFechamento',
    'plano','planoBase','planoBaseSemTempo','planoBaseEstrutural','planoBaseSemAtividadesRealizadas',
    'planoOrigem','planoBaseOrigem','planoBaseEstruturalOrigem','previa','exec','rascunhoPlano'
  ].forEach(k=>delete sem[k]);
  delete sem.previaPendente;
  sem.arquivada=true;
  sem.compactada=true;
  if(!sem.arquivadaEm) sem.arquivadaEm=new Date(agora).toISOString();
  const depois=JSON.stringify(sem).length*2;
  return{alterada:!jaArquivada||depois<antes,bytesLiberados:Math.max(0,antes-depois)};
}
function resumoRotacaoSemanasCalifit(estado=ST){
  const semanas=arr(estado?.semanas);
  const arquivadas=semanas.filter(s=>s?.arquivada===true).length;
  const completas=semanas.filter(s=>semanaElegivelRotacaoCalifit(s,estado)&&!s?.arquivada).length;
  const manutencao=Object.assign({},DEF().manutencao,estado?.manutencao||{});
  return{
    arquivadas,
    completas,
    limitePadrao:LIMITE_SEMANAS_COMPLETAS_CALIFIT,
    limitePressao:LIMITE_SEMANAS_COMPLETAS_PRESSAO_CALIFIT,
    ultimaRotacaoSemanasEm:String(manutencao.ultimaRotacaoSemanasEm||''),
    bytesLiberadosRotacao:Math.max(0,+manutencao.bytesLiberadosRotacao||0)
  };
}
function rotacionarSemanasAntigasCalifit({estado=ST,forcar=false,agora=new Date()}={}){
  if(!estado||typeof estado!=='object') return{arquivadas:0,totalArquivadas:0,bytesLiberados:0,limite:LIMITE_SEMANAS_COMPLETAS_CALIFIT};
  estado.semanas=arr(estado.semanas);
  estado.manutencao=Object.assign({},DEF().manutencao,estado.manutencao||{});
  const usoAntes=estimarBytesEstadoCalifit(estado);
  const pressao=usoAntes>4*1024*1024;
  const limite=(forcar||pressao)?LIMITE_SEMANAS_COMPLETAS_PRESSAO_CALIFIT:LIMITE_SEMANAS_COMPLETAS_CALIFIT;
  const elegiveis=estado.semanas.filter(s=>semanaElegivelRotacaoCalifit(s,estado))
    .sort((a,b)=>inicioSemanaTsCalifit(b)-inicioSemanaTsCalifit(a)||String(b.id).localeCompare(String(a.id)));
  let arquivadas=0,bytesLiberados=0;
  elegiveis.slice(limite).forEach(sem=>{
    if(sem.arquivada===true&&sem.compactada===true) return;
    const r=compactarSemanaArquivadaCalifit(sem,agora);
    if(r.alterada){arquivadas++;bytesLiberados+=r.bytesLiberados;}
  });
  if(arquivadas){
    estado.manutencao.ultimaRotacaoSemanasEm=new Date(agora).toISOString();
    estado.manutencao.semanasArquivadas=arr(estado.semanas).filter(s=>s?.arquivada===true).length;
    estado.manutencao.bytesLiberadosRotacao=Math.max(0,+estado.manutencao.bytesLiberadosRotacao||0)+bytesLiberados;
  }else{
    estado.manutencao.semanasArquivadas=arr(estado.semanas).filter(s=>s?.arquivada===true).length;
  }
  return{arquivadas,totalArquivadas:estado.manutencao.semanasArquivadas,bytesLiberados,limite,pressao,usoAntes,usoDepois:estimarBytesEstadoCalifit(estado)};
}
function estimarUsoLocalStorage(){
  try{
    let total=0;
    for(let i=0;i<localStorage.length;i++){
      const k=localStorage.key(i);
      total+=String(k||'').length+String(localStorage.getItem(k)||'').length;
    }
    return total*2;
  }catch(e){
    return 0;
  }
}
function alertarRiscoArmazenamento(){
  const uso=estimarUsoLocalStorage();
  if(!uso||_avisoUsoStorage) return;
  if(uso>4*1024*1024){
    _avisoUsoStorage=true;
    showToast('O armazenamento local está alto. A rotação automática já compactou as semanas elegíveis; exporte um backup para maior segurança.',7000);
  }
}
function salvar(){
  try{
    ST.schemaVersion=APP_SCHEMA_VERSION;
    if(ST.perfil){normalizarSaudePerfil(ST.perfil);sincronizarLimitacaoCirurgiaPerfil(ST.perfil);}
    normalizarEstadosSemanasCalifit({limparRascunhosVazios:false});
    arr(ST.semanas).forEach(sem=>normalizarCheckinsSemanaisCalifit(sem));
    rotacionarSemanasAntigasCalifit({estado:ST});
    if(ST.plano) normalizarPrescricoesPlanoCalifit(ST.plano);
    if(ST.plano) delete ST.plano._baseSemTempo;
    if(ST.plano) delete ST.plano._baseEstrutural;
    localStorage.setItem(STORAGE_KEY,JSON.stringify(ST));
    _avisoFalhaSalvar=false;
    alertarRiscoArmazenamento();
    return true;
  }catch(e){
    console.warn('Falha ao salvar no localStorage',e);
    if(!_avisoFalhaSalvar){
      _avisoFalhaSalvar=true;
      showToast('O armazenamento local está cheio ou indisponível. Exporte um backup antes de continuar.',7000);
    }
    return false;
  }
}
function load(){
  try{
    const s=localStorage.getItem(STORAGE_KEY);
    if(s){
      const d=JSON.parse(s);
      ST=migrarEstadoSalvo(d);
    }else{
      ST=DEF();
    }
  }catch(e){ST=DEF();}
  ST.perfil=Object.assign(DEF().perfil,ST.perfil||{});
  normalizarSaudePerfil(ST.perfil);
  ST.corpo=Object.assign(DEF().corpo,ST.corpo||{});
  ST.corpo.historicoMetas=arr(ST.corpo.historicoMetas);
  migrarObjetivosPerfil(ST.perfil);
  if(!ST.perfil.contextoAtual&&ST.ctx) ST.perfil.contextoAtual=ST.ctx;
  if(!ST.ctx&&ST.perfil.contextoAtual) ST.ctx=ST.perfil.contextoAtual;
  ST.perfil.equipamentos=normalizarEquipamentos(ST.perfil.equipamentos);
  ST.perfil.tempoMaxTreino=normalizarTempoMaxTreino(ST.perfil.tempoMaxTreino);
  if(!Array.isArray(ST.checkins)) ST.checkins=[];
  arr(ST.semanas).forEach(sem=>normalizarCheckinsSemanaisCalifit(sem));
  ST.contextoTreinador=Object.assign(DEF().contextoTreinador,ST.contextoTreinador||{});
  ['alertasAtuais','exerciciosFaceis','exerciciosDificeis','recomendacoesAtuais','ultimaRegioes'].forEach(k=>{
    if(!Array.isArray(ST.contextoTreinador[k])) ST.contextoTreinador[k]=[];
    ST.contextoTreinador[k]=ST.contextoTreinador[k].filter(v=>!valorVazioUsuario(v));
  });
  ['ultimaIntencao','ultimaMensagem','ultimaRespostaEm','ultimaReferenciaTemporal','ultimaAcaoEstado','ultimaAcaoResultado'].forEach(k=>{
    if(typeof ST.contextoTreinador[k]!=='string') ST.contextoTreinador[k]='';
  });
  if(!ST.contextoTreinador.ultimoCheckinResumo&&ST.checkins.length) reconstruirContextoTreinador();
  ST.perfil.marcas=Object.assign(DEF().perfil.marcas,ST.perfil.marcas||{});
  ['doresAtuais','exerciciosEvitar','exerciciosPreferidos'].forEach(k=>{
    if(!Array.isArray(ST.perfil[k])) ST.perfil[k]=[];
    ST.perfil[k]=ST.perfil[k].filter(v=>!valorVazioUsuario(v));
  });
  ST.perfil.limitacoes=normalizarLimitacoes(ST.perfil.limitacoes);
  ST.perfil.ativExtras=(ST.perfil.ativExtras||[]).map(a=>({
    k:a.k,
    nome:a.nome||a.n||a.k,
    dias:arr(a.dias).map(Number).filter(Number.isFinite),
    duracaoMin:duracaoAtividadeMin(a),
    intensidade:intensidadeComplementarNormalizada(a.intensidade)||'moderada',
    impacto:Array.isArray(a.impacto)?a.impacto:[],
    prioridade:a.prioridade||'complementar'
  })).filter(a=>a.k&&a.dias.length);
  arr(ST.semanas).forEach(sem=>{
    Object.entries(sem?.registros||{}).forEach(([dia,reg])=>{
      if(reg?.tipo==='atividade') sem.registros[dia]=normalizarRegistroAtividadesComplementaresCalifit(reg,atividadesPlanejadasDia(ST.plano?.dias?.[dia]||{}),+dia);
    });
  });
  ST.planoBaseEstrutural=separarPlanoBaseEstrutural(ST.planoBaseEstrutural||ST.planoBaseSemTempo||ST.plano);
  ST.planoBaseSemTempo=limparMetadadosTempoPlano(ST.planoBaseSemTempo||ST.planoBaseEstrutural||ST.plano);
  ST.planoBaseSemAtividadesRealizadas=limparMetadadosTempoPlano(ST.planoBaseSemAtividadesRealizadas||ST.planoBaseSemTempo);
  if(ST.planoBaseSemTempo){
    ST.planoBaseSemTempo=ajustarDescansosPlano(deduplicarPlano(ST.planoBaseSemTempo));
    ST.plano=ajustarPlanoAoTempo(cloneObj(ST.planoBaseSemTempo),ST.perfil);
  }
  if(ST.plano) delete ST.plano._baseSemTempo;
  if(ST.plano) delete ST.plano._baseEstrutural;
  limparAjustesTempoDiarioExpiradosCalifit();
  aplicarAjusteTempoDiarioPersistidoCalifit();
  if(ST.previaProximaSemana?.planoBaseSemTempo){
    ST.previaProximaSemana.planoBaseEstrutural=separarPlanoBaseEstrutural(ST.previaProximaSemana.planoBaseEstrutural||ST.planoBaseEstrutural||ST.previaProximaSemana.planoBaseSemTempo);
    ST.previaProximaSemana.planoBaseSemTempo=limparMetadadosTempoPlano(ST.previaProximaSemana.planoBaseSemTempo);
    ST.previaProximaSemana.plano=ajustarPlanoAoTempo(ajustarDescansosPlano(cloneObj(ST.previaProximaSemana.planoBaseSemTempo)),ST.perfil);
  }else if(ST.previaProximaSemana?.plano){
    ST.previaProximaSemana.planoBaseEstrutural=separarPlanoBaseEstrutural(ST.previaProximaSemana.planoBaseEstrutural||ST.planoBaseEstrutural||ST.previaProximaSemana.plano);
    ST.previaProximaSemana.planoBaseSemTempo=limparMetadadosTempoPlano(ST.previaProximaSemana.plano);
    ST.previaProximaSemana.plano=ajustarPlanoAoTempo(ajustarDescansosPlano(cloneObj(ST.previaProximaSemana.planoBaseSemTempo)),ST.perfil);
  }
  normalizarPreviaPendente();
  normalizarEstadosSemanasCalifit();
  const viradaCarregamento=ST.done?prepararViradaAutomaticaSemanaCalifit({persistir:false}):{alterada:false};
  const rotacaoCarregamento=rotacionarSemanasAntigasCalifit({estado:ST});
  if(rotacaoCarregamento.arquivadas||viradaCarregamento.alterada){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(ST));}catch(e){console.warn('Não foi possível persistir a manutenção automática das semanas no carregamento.',e);}}
  restaurarSubstituicoesTemporariasPlanoCalifit({somenteExpiradas:true});
  normalizarNumeracaoSemanas();
  if(ST.done){
    mostrarApp();
  }else{
    // 164H: preparação completa do onboarding somente no primeiro uso/reconfiguração.
    buildAtivs();
    hidratarOnboardingDoPerfil();
    renderCamposCargas($('ob-cargas'),'ob',ST.perfil);
    renderDetalhesLimitacoes($('ob-lim-detalhes'),'ob',ST.perfil);
    configurarDivulgacaoOnboarding();
    aplicarIconesCalifit($('ob')||document);
    mostrarSplash();
  }
}

// ═══════════════════════════════════════════════════════════
// UTILITÁRIOS UI
// ═══════════════════════════════════════════════════════════
function $(id){return document.getElementById(id);}
function on(id,ev,fn){const el=$(id);if(el) el.addEventListener(ev,fn);return el;}
function preservarScrollDuranteCalifit(fn){
  const x=window.scrollX||0,y=window.scrollY||document.documentElement?.scrollTop||0;
  const out=typeof fn==='function'?fn():undefined;
  setTimeout(()=>window.scrollTo?.(x,y),0);
  return out;
}
function garantirBotoesTipoButtonCalifit(container=document){
  container.querySelectorAll?.('button:not([type])').forEach(b=>b.type='button');
}
function valorVazioUsuario(v){
  const n=normTxt(v).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
  return !n||[
    'nenhum','nenhuma','nada','nao','sem','sem dor','sem dores','nao tenho','nao se aplica',
    'nao fiz','nao fiz ainda','ainda nao fiz','nao treinei','ainda nao treinei',
    'nenhum exercicio','nao houve exercicio','dia de descanso','foi descanso','descanso',
    'nao sei','nada ainda'
  ].includes(n);
}
function csvArr(v){return (v||'').split(',').map(x=>x.trim()).filter(x=>x&&!valorVazioUsuario(x));}
function normalizarLimitacoes(lista=[]){
  const vals=[...new Set((Array.isArray(lista)?lista:[]).filter(Boolean))];
  const reais=vals.filter(v=>v!=='nenhuma');
  return reais.length?reais:(vals.includes('nenhuma')?['nenhuma']:[]);
}
function estadoDoresOnboardingAtual(){
  const lims=normalizarLimitacoes(getObVals('ob-lims'));
  const estado=ST.perfil?.estadoDoresOnboarding||'';
  const perfilLims=normalizarLimitacoes(ST.perfil?.limitacoes||[]).filter(v=>v!=='nenhuma');
  if(lims.includes('nenhuma')) return{respondido:true,estado:'sem_dor',limitacoes:['nenhuma']};
  const reais=lims.filter(v=>v!=='nenhuma');
  if(reais.length) return{respondido:true,estado:'informado',limitacoes:reais};
  // Cirurgia/recuperação pode ser inferida pelos campos de saúde sem chip visível selecionado.
  // Nesse caso, a etapa já foi respondida e não deve bloquear a tela "Sua semana".
  if(perfilLims.length) return{respondido:true,estado:'informado',limitacoes:perfilLims};
  if(estado==='sem_dor') return{respondido:true,estado:'sem_dor',limitacoes:['nenhuma']};
  if(estado==='nao_informado') return{respondido:true,estado:'nao_informado',limitacoes:[]};
  return{respondido:false,estado:'',limitacoes:[]};
}
function aplicarEstadoDoresOnboarding(estado){
  ST.perfil.estadoDoresOnboarding=estado||'';
  $('ob-sem-dor')?.classList.toggle('on',estado==='sem_dor');
  $('ob-dor-depois')?.classList.toggle('on',estado==='nao_informado');
}
function limparChipsDoresOnboarding(){
  $('ob-lims')?.querySelectorAll('.oc').forEach(x=>x.classList.remove('on'));
}
function escHtml(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
