function iconeCalifitInline(nome){
  return iconeCalifit(nome).replace('class="cf-ico ','class="cf-ico cf-ico-inline ');
}
function tituloIcone(nome,texto){
  return `${iconeCalifitInline(nome)}${escHtml(texto)}`;
}
function aplicarIconesCalifit(root=document){
  root.querySelectorAll('[data-ico]').forEach(el=>{el.innerHTML=iconeCalifit(el.dataset.ico);});
}
function cloneObj(v){return JSON.parse(JSON.stringify(v));}
const TIPO_LABEL={forca:'força',tecnica:'técnica',metabolico:'metabólico',misto:'misto',mobilidade:'mobilidade',recuperacao:'recuperação',descanso:'descanso',atividade:'atividade',deload:'deload'};
function tipoLabel(v){return TIPO_LABEL[v]||v||'';}
function statusLabel(v){return {sim:'feito',parcial:'parcial',nao:'não feito',feito:'concluído',perdido:'perdido'}[v]||v||'—';}
function dorLabel(v){
  if(v==null||String(v).trim()==='') return 'não informada';
  return {nao:'não',não:'não',leve:'leve',moderada:'moderada',forte:'forte'}[v]||v||'não informada';
}
function tecnicaLabel(v){return {boa:'boa',regular:'regular',ruim:'ruim',nao_sei:'não sei avaliar'}[v]||v||'—';}
function recStatusLabel(v){return {manter:'manter',trocar:'trocar',regredir:'regredir',progredir:'progredir',reduzir_volume:'reduzir volume',revisar:'revisar'}[v]||String(v||'manter').replace(/_/g,' ');}
function qualidadeLabel(v){return {boa:'boa',media:'média',ruim:'ruim'}[v]||v||'não informado';}
function dataCurtaBR(d=new Date()){return new Date(d).toLocaleDateString('pt-BR');}
function dataCompletaHoje(){const d=new Date();return `${DPT_FULL[d.getDay()]}, ${dataCurtaBR(d)}`;}
function dataHojeUX(d=new Date()){
  try{
    const x=new Date(d);
    const dia=x.toLocaleDateString('pt-BR',{weekday:'long'});
    const curta=x.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});
    return `Hoje, ${dia}, ${curta}`;
  }catch(e){
    return `Hoje, ${dataCurtaBR(d)}`;
  }
}
function dataDiaSemana(sem,diaIdx){
  const base=sem?.inicio?new Date(sem.inicio):new Date();
  base.setHours(0,0,0,0);
  base.setDate(base.getDate()+((+diaIdx||0)+6)%7);
  return base;
}
function inicioDiaLocal(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);return x;}
function treinoDiaFuturo(sem,diaIdx){return dataDiaSemana(sem,diaIdx)>inicioDiaLocal();}
function dataCriacaoSemana(sem){
  const raw=sem?.criadoEm||sem?.createdAt||sem?.planoCriadoEm||'';
  if(!raw) return null;
  const d=new Date(raw);
  return Number.isNaN(d.getTime())?null:d;
}
function diaAntesCriacaoSemana(sem,diaIdx){
  const criado=dataCriacaoSemana(sem);
  if(!criado) return false;
  return dataDiaSemana(sem,diaIdx)<inicioDiaLocal(criado);
}
function semanaTemDiasAntesCriacao(sem){
  const criado=dataCriacaoSemana(sem);
  if(!criado) return false;
  return inicioDiaLocal(criado)>inicioDiaLocal(sem?.inicio||criado);
}
function dataHoraCurtaBR(d=new Date()){
  return new Date(d).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
}
function treinosAnterioresSemRegistroSemana(sem=getSem()){
  if(!sem?.aberta||!ST.plano) return [];
  const hoje=new Date().getDay();
  return Object.entries(ST.plano.dias||{}).map(([d,dia])=>({d:+d,dia}))
    .filter(({d,dia})=>d<hoje&&dia&&dia.tipo!=='descanso'&&dia.tipo!=='atividade'&&!diaAntesCriacaoSemana(sem,d))
    .filter(({d})=>!['feito','perdido'].includes(sem.registros?.[d]?.tipo));
}
function visualDiaSemana(dia,reg,atual=false){
  if(reg?.tipo==='feito'){
    const status=statusGeralCheckinCalifit(reg.statusGeral||reg.treino?.statusGeral,reg.treino?.exercicios||[]);
    if(status==='nao') return{ico:iconeCalifit('alerta'),classe:' wp'};
    if(status==='parcial') return{ico:iconeCalifit('checkin'),classe:' wpar'};
    return{ico:iconeCalifit('checkin'),classe:' wf'};
  }
  if(reg?.tipo==='perdido') return{ico:iconeCalifit('alerta'),classe:' wp'};
  if(reg?.tipo==='descanso') return{ico:iconeCalifit(reg.atividadeLeve?iconeAtividadeComplementarSemana(reg):'zz'),classe:' wf'};
  if(reg?.tipo==='atividade'){
    const st=statusAtividadeAgregado(reg,atividadesPlanejadasDia(dia));
    if(st==='nao') return{ico:iconeCalifit('alerta'),classe:' wp'};
    if(st==='parcial') return{ico:iconeCalifit(iconeAtividadeComplementarSemana(reg)),classe:' wpar'};
    return{ico:iconeCalifit(iconeAtividadeComplementarSemana(reg)),classe:st==='sim'?' wf':''};
  }
  if(dia?.tipo==='descanso') return{ico:iconeCalifit('zz'),classe:' wd2'};
  if(dia?.tipo==='atividade') return{ico:iconeCalifit(iconeAtividadeComplementarSemana(dia)),classe:atual?' wh':''};
  if(atual) return{ico:iconeCalifit('meta'),classe:' wh'};
  return{ico:iconeCalifit('hoje'),classe:''};
}
function iconeAtividadeComplementarSemana(item={}){
  const itens=arr(item.atividades).length?arr(item.atividades):[item];
  const tipoItem=a=>{
    const txt=normTxt([a.atividade,a.descansoTipo,a.nome,a.tipoAtividade,a.k,a.tipo,a.obs,a.observacao].filter(Boolean).join(' '));
    if(/musculacao|forca|peso|halter|barra|academia/.test(txt)) return 'barbell';
    if(/corrida|running|esteira/.test(txt)) return 'run';
    if(/caminhada.*(intensa|forte|rapida)|intensa.*caminhada/.test(txt)) return 'walkFast';
    if(/caminhada|passos|andar/.test(txt)) return 'walk';
    if(/ciclismo|bike|bicicleta|pedal/.test(txt)) return 'bike';
    if(/natacao|nadar|piscina|swim/.test(txt)) return 'swim';
    if(/pilates/.test(txt)) return 'pilates';
    if(/yoga|meditacao/.test(txt)) return 'yoga';
    if(/mobilidade|alongamento|flexibilidade/.test(txt)) return 'flow';
    if(/funcional|hiit|circuito|metabolico/.test(txt)) return 'atividade';
    return 'atividade';
  };
  const prioridade=['barbell','run','walkFast','walk','bike','swim','pilates','yoga','flow','atividade'];
  const encontrados=itens.map(tipoItem);
  return prioridade.find(p=>encontrados.includes(p))||'atividade';
}
const REGIOES_ATIVIDADE_CALIFIT=[
  ['pernas','Pernas'],['quadril','Quadril/glúteos'],['joelho','Joelhos'],['panturrilha','Panturrilhas'],
  ['core','Core/abdômen'],['lombar','Lombar'],['costas','Costas'],['ombro','Ombros'],['peitoral','Peitoral/braços'],['corpo_todo','Corpo todo']
];
function normalizarImpactoAtividadeCalifit(valores=[]){
  const mapa={
    perna:'pernas',pernas:'pernas',inferior:'pernas',quadriceps:'pernas',posterior:'pernas',gluteo:'quadril',gluteos:'quadril',quadril:'quadril',
    joelho:'joelho',joelhos:'joelho',panturrilha:'panturrilha',panturrilhas:'panturrilha',core:'core',abdomen:'core',abdominal:'core',
    lombar:'lombar',costas:'costas',puxar:'costas',ombro:'ombro',ombros:'ombro',peitoral:'peitoral',bracos:'peitoral',braco:'peitoral',
    superior:'peitoral','corpo todo':'corpo_todo',corpo_todo:'corpo_todo',fullbody:'corpo_todo'
  };
  const permitidas=new Set(REGIOES_ATIVIDADE_CALIFIT.map(([v])=>v));
  return [...new Set(arr(valores).flatMap(v=>String(v||'').split(/[,;/|]+/)).map(v=>mapa[normTxt(v)]||normTxt(v).replace(/\s+/g,'_')).filter(v=>permitidas.has(v)))];
}
function chaveAtividadeComplementar(a={}){
  return normTxt([a.k,a.nome,a.atividade,a.tipoAtividade].filter(Boolean)[0]||'');
}
function idAtividadePlanejadaCalifit(a={},idx=0){
  return String(a.planejadaId||a.atividadePlanejadaId||a.idAtividade||`${chaveAtividadeComplementar(a)||'atividade'}#${idx}`);
}
function atividadesPlanejadasDia(dia={}){
  const itens=arr(dia?.atividades).length?arr(dia.atividades):(dia?.atividade?[{nome:dia.atividade,k:dia.atividade,duracaoMin:dia.duracaoMin||0,intensidade:dia.intensidade||'',impacto:dia.impacto||[],prioridade:dia.prioridade||''}]:[]);
  return itens.map((a,idx)=>({...a,planejadaId:idAtividadePlanejadaCalifit(a,idx),impacto:normalizarImpactoAtividadeCalifit(a.impacto)}));
}
function normalizarRecuperacaoAtividadeCalifit(v=''){
  const n=normTxt(v);
  if(/ruim|muito cans|dolor|esgot|exaust/.test(n)) return 'ruim';
  if(/media|média|cansad|moderad/.test(n)) return 'media';
  if(/boa|bem|leve|recuperad|normal/.test(n)) return 'boa';
  return '';
}
function labelRecuperacaoAtividadeCalifit(v=''){
  return ({boa:'corpo bem',media:'cansaço moderado',ruim:'muito cansado ou dolorido'})[normalizarRecuperacaoAtividadeCalifit(v)]||'';
}
function normalizarAtividadeRegistradaCalifit(a={},planejada={},idx=0){
  const base={...planejada,...a};
  const planejadaId=String(a.planejadaId||a.atividadePlanejadaId||idAtividadePlanejadaCalifit(planejada,idx));
  const status=statusAtividadeNormalizado(a.status||a.statusAtividade||'');
  const registroId=String(a.registroId||`${planejadaId}|registro`);
  return{
    ...base,registroId,planejadaId,atividadePlanejadaId:planejadaId,origem:'registro',planejada:true,
    k:a.k||planejada.k||a.nome||planejada.nome||'',nome:nomeAtividadeComplementar(a.nome?a:planejada),status,
    duracaoMin:status==='nao'?0:Math.max(0,+a.duracaoMin||0),
    intensidade:status==='nao'?'':intensidadeComplementarNormalizada(a.intensidade||''),
    recuperacao:status==='nao'?'':normalizarRecuperacaoAtividadeCalifit(a.recuperacao||a.sensacaoPos||a.sensacaoCorpo||''),
    impacto:normalizarImpactoAtividadeCalifit(arr(a.impacto).length?a.impacto:planejada.impacto),
    prioridade:a.prioridade||planejada.prioridade||'complementar',obs:String(a.obs||a.observacao||'').trim()
  };
}
function atividadesRegistradasDia(reg={}){
  const brutas=arr(reg?.atividades).length?arr(reg.atividades):(reg?.atividade?[{nome:reg.atividade,k:reg.atividade,status:reg.statusAtividade||'sim',duracaoMin:reg.duracaoMin||0,intensidade:reg.intensidade||'',recuperacao:reg.recuperacao||reg.sensacao||'',impacto:reg.impacto||[],obs:reg.obs||''}]:[]);
  const vistos=new Map();
  brutas.forEach((a,idx)=>{
    const normal=normalizarAtividadeRegistradaCalifit(a,{},idx);
    const chave=normal.registroId||normal.planejadaId||`${chaveAtividadeComplementar(normal)}#${idx}`;
    vistos.set(chave,normal);
  });
  return [...vistos.values()];
}
function atividadeRegistradaCorrespondente(registradas=[],planejada={},idx=0){
  const regs=arr(registradas);
  const pid=idAtividadePlanejadaCalifit(planejada,idx);
  const porId=regs.find(r=>String(r.planejadaId||r.atividadePlanejadaId||'')===pid);
  if(porId) return porId;
  const chave=chaveAtividadeComplementar(planejada);
  const iguais=chave?regs.filter(r=>chaveAtividadeComplementar(r)===chave):[];
  if(iguais.length) return iguais[Math.min(idx,iguais.length-1)]||{};
  return regs[idx]||{};
}
function montarRegistroAtividadesComplementaresCalifit(atividades=[],base={},diaIdx=0,dataPlanejada=''){
  const normalizadas=arr(atividades).map((a,i)=>normalizarAtividadeRegistradaCalifit(a,{},i)).filter(a=>a.status);
  if(!normalizadas.length) return null;
  const realizadas=normalizadas.filter(a=>['sim','parcial'].includes(a.status));
  const statusAgregado=statusAtividadeAgregadoAtividades(normalizadas);
  const recuperacoes=realizadas.map(a=>normalizarRecuperacaoAtividadeCalifit(a.recuperacao)).filter(Boolean);
  const recuperacao=recuperacoes.includes('ruim')?'ruim':recuperacoes.includes('media')?'media':recuperacoes.includes('boa')?'boa':'';
  const intensidade=realizadas.some(a=>a.intensidade==='intensa')?'intensa':realizadas.some(a=>a.intensidade==='moderada')?'moderada':realizadas.some(a=>a.intensidade==='leve')?'leve':'';
  const agora=new Date().toISOString();
  return{
    ...base,tipo:'atividade',data:base.data||agora,atualizadoEm:agora,diaIdx:+diaIdx,
    dataPlanejada:dataPlanejada||base.dataPlanejada||'',atividades:normalizadas,
    atividade:normalizadas.map(a=>a.nome).filter(Boolean).join(' + '),statusAtividade:statusAgregado,feita:!!realizadas.length,
    duracaoMin:realizadas.reduce((s,a)=>s+(+a.duracaoMin||0),0),intensidade,recuperacao,sensacao:recuperacao,
    impacto:[...new Set(realizadas.flatMap(a=>normalizarImpactoAtividadeCalifit(a.impacto)))],
    obs:normalizadas.map(a=>[a.nome,labelStatusAtividade(a.status),a.duracaoMin?`${a.duracaoMin}min`:'',labelIntensidadeComplementar(a.intensidade),labelRecuperacaoAtividadeCalifit(a.recuperacao),a.obs].filter(Boolean).join(' · ')).join(' | '),
    obsGeral:String(base.obsGeral||'').trim()
  };
}
function atualizarAtividadeComplementarNoRegistroCalifit(regAtual={},planejadas=[],idx=0,patch={},diaIdx=0,dataPlanejada=''){
  const plan=arr(planejadas).map((a,i)=>({...a,planejadaId:idAtividadePlanejadaCalifit(a,i)}));
  const atual=atividadesRegistradasDia(regAtual);
  const alvoPlan=plan[idx]||patch||{};
  const pid=idAtividadePlanejadaCalifit(alvoPlan,idx);
  const existente=atividadeRegistradaCorrespondente(atual,alvoPlan,idx)||{};
  const novo=normalizarAtividadeRegistradaCalifit({...existente,...patch,planejadaId:pid},alvoPlan,idx);
  const semAlvo=atual.filter(a=>String(a.planejadaId||a.atividadePlanejadaId||'')!==pid);
  return montarRegistroAtividadesComplementaresCalifit([...semAlvo,novo],{...regAtual,obsGeral:patch.obsGeral??regAtual.obsGeral},diaIdx,dataPlanejada);
}
function removerAtividadeComplementarDoRegistroCalifit(regAtual={},planejadas=[],idx=0,diaIdx=0,dataPlanejada=''){
  const alvo=arr(planejadas)[idx]||{};
  const pid=idAtividadePlanejadaCalifit(alvo,idx);
  const restantes=atividadesRegistradasDia(regAtual).filter(a=>String(a.planejadaId||a.atividadePlanejadaId||'')!==pid);
  return montarRegistroAtividadesComplementaresCalifit(restantes,regAtual,diaIdx,dataPlanejada);
}
function normalizarRegistroAtividadesComplementaresCalifit(reg={},planejadas=[],diaIdx=0){
  if(!reg||reg.tipo!=='atividade') return reg;
  const regs=atividadesRegistradasDia(reg).map((a,i)=>normalizarAtividadeRegistradaCalifit(a,arr(planejadas)[i]||{},i));
  return montarRegistroAtividadesComplementaresCalifit(regs,reg,diaIdx,reg.dataPlanejada)||reg;
}
function filtrarRegistroAtividadesParaPlanejadasCalifit(reg={},planejadas=[],diaIdx=0,dataPlanejada=''){
  if(!reg||reg.tipo!=='atividade') return null;
  const plan=arr(planejadas).map((a,i)=>({...a,planejadaId:idAtividadePlanejadaCalifit(a,i)}));
  const regs=atividadesRegistradasDia(reg);
  const usados=new Set();
  const preservadas=[];
  plan.forEach((planejada,i)=>{
    const pid=idAtividadePlanejadaCalifit(planejada,i);
    const chave=chaveAtividadeComplementar(planejada);
    let idx=regs.findIndex((r,j)=>!usados.has(j)&&String(r.planejadaId||r.atividadePlanejadaId||'')===pid);
    if(idx<0&&chave) idx=regs.findIndex((r,j)=>!usados.has(j)&&chaveAtividadeComplementar(r)===chave);
    if(idx<0) return;
    const antiga=regs[idx];
    const status=statusAtividadeNormalizado(antiga.status||antiga.statusAtividade||'');
    if(!status) return;
    usados.add(idx);
    preservadas.push(normalizarAtividadeRegistradaCalifit({
      ...antiga,status,registroId:`${pid}|registro`,planejadaId:pid,atividadePlanejadaId:pid
    },planejada,i));
  });
  return montarRegistroAtividadesComplementaresCalifit(
    preservadas,{...reg,atividades:undefined,atividade:'',statusAtividade:'',feita:false},diaIdx,dataPlanejada||reg.dataPlanejada||''
  );
}
function preservarRegistrosAtividadeNaRegeneracaoCalifit(registrosAntigos={},planoNovo={},semanaNova={}){
  if(!semanaNova||!planoNovo?.dias) return 0;
  semanaNova.registros=semanaNova.registros||{};
  let preservadas=0;
  Object.entries(planoNovo.dias).forEach(([dia,diaPlano])=>{
    if(diaPlano?.tipo!=='atividade') return;
    const anterior=registrosAntigos?.[dia];
    if(!anterior||anterior.tipo!=='atividade') return;
    const planejadas=atividadesPlanejadasDia(diaPlano);
    const dataPlanejada=typeof dataDiaSemana==='function'?dataDiaSemana(semanaNova,+dia).toISOString():(anterior.dataPlanejada||'');
    const restaurado=filtrarRegistroAtividadesParaPlanejadasCalifit(anterior,planejadas,+dia,dataPlanejada);
    if(restaurado){
      semanaNova.registros[dia]=restaurado;
      preservadas+=atividadesRegistradasDia(restaurado).length;
    }
  });
  return preservadas;
}
function atividadesRealizadasSemanaCalifit(semana={}){
  return Object.entries(semana?.registros||{}).flatMap(([dia,reg])=>{
    if(reg?.tipo!=='atividade') return [];
    return atividadesRegistradasDia(reg).filter(a=>['sim','parcial'].includes(statusAtividadeNormalizado(a.status))).map(a=>{
      const parcial=statusAtividadeNormalizado(a.status)==='parcial';
      return{...a,dias:[+dia],duracaoMin:parcial?Math.max(1,Math.round((+a.duracaoMin||0)*.7)):(+a.duracaoMin||0),origem:'realizada'};
    });
  });
}
function resumoCargaAtividadesSemanaCalifit(semana={}){
  const atividades=atividadesRealizadasSemanaCalifit(semana);
  const classificadas=atividades.map(a=>({...a,carga:classificarCargaAtividade(a)}));
  const relevantes=classificadas.filter(a=>a.carga.relevante||a.carga.nivel>=2);
  const recuperacaoRuim=atividades.some(a=>normalizarRecuperacaoAtividadeCalifit(a.recuperacao)==='ruim');
  const recuperacaoMedia=atividades.some(a=>normalizarRecuperacaoAtividadeCalifit(a.recuperacao)==='media');
  const cargaAlta=relevantes.some(a=>a.carga.nivel>=3)||relevantes.reduce((s,a)=>s+(+a.duracaoMin||0),0)>=120;
  const nomes=[...new Set(relevantes.map(a=>a.nome).filter(Boolean))];
  return{atividades,classificadas,relevantes,quantidade:atividades.length,cargaAlta,recuperacaoRuim,recuperacaoMedia,
    texto:relevantes.length?`Carga complementar realizada: ${fraseListaHumana(nomes)}${cargaAlta?' (alta)':''}. O volume foi revisto para preservar recuperação.`:''};
}
function aplicarAjustesAtividadesRegistradasPlanoCalifit(plano,semana={},perfil={}){
  const realizadas=atividadesRealizadasSemanaCalifit(semana);
  if(!plano?.dias||!realizadas.length) return cloneObj(plano);
  const perfilReal={...perfil,ativExtras:realizadas};
  const ajustado=aplicarAjustesAtividadesPlano(cloneObj(plano),perfilReal);
  Object.values(ajustado.dias||{}).forEach(d=>{if(d&&d.contextoAtividades?.length)d.contextoAtividadesRealizadas=[...d.contextoAtividades];});
  return ajustado;
}
function recalcularPlanoAtualPorAtividadesRegistradasCalifit(semana=getSem()){
  if(!semana||!ST.planoBaseSemTempo) return ST.plano;
  const base=cloneObj(ST.planoBaseSemAtividadesRealizadas||ST.planoBaseSemTempo);
  ST.planoBaseSemAtividadesRealizadas=cloneObj(base);
  ST.planoBaseSemTempo=aplicarAjustesAtividadesRegistradasPlanoCalifit(base,semana,ST.perfil);
  ST.plano=ajustarPlanoAoTempo(ajustarDescansosPlano(cloneObj(ST.planoBaseSemTempo)),ST.perfil);
  if(ST.plano){delete ST.plano._baseSemTempo;delete ST.plano._baseEstrutural;}
  aplicarAjusteTempoDiarioPersistidoCalifit();
  return ST.plano;
}
function limparTemporariosAtividadesComplementares(){
  Object.keys(ST.exec||{}).filter(k=>/^_a[odipr]?_/.test(k)).forEach(k=>delete ST.exec[k]);
}
function limparCamposAtividadePerfil(box,k,prefix='pp'){
  if(!box) return;
  if(prefix==='ob') box.querySelectorAll('[data-ad],[data-imp],[data-pri]').forEach(b=>b.classList.toggle('on',b.dataset.pri==='complementar'));
  else box.querySelectorAll(`[data-${prefix}-ad^="${k}-"],[data-${prefix}-imp^="${k}-"]`).forEach(b=>b.classList.remove('on'));
  const dur=$(prefix==='pp'?`pp-dur-${k}`:`ad-dur-${k}`);if(dur) dur.value='';
  const int=$(prefix==='pp'?`pp-int-${k}`:`ad-int-${k}`);if(int) int.value='moderada';
  const pri=$(prefix==='pp'?`pp-pri-${k}`:`ad-pri-${k}`);
  if(pri&&pri.tagName==='SELECT') pri.value='complementar';
}

function statusAtividadeNormalizado(v=''){
  const n=normTxt(v);
  if(/parcial|parte|incomplet/.test(n)) return 'parcial';
  if(/nao|não|skip|perdid|false|0/.test(n)) return 'nao';
  if(/sim|feito|feita|realiz|true|1/.test(n)) return 'sim';
  return '';
}
function labelStatusAtividade(v=''){
  return ({sim:'feita',parcial:'parcial',nao:'não feita',pendente:'pendente'})[statusAtividadeNormalizado(v)||v]||'pendente';
}
function statusAtividadeAgregado(reg={},planejadas=[]){
  if(!reg||reg.tipo!=='atividade') return 'pendente';
  const regs=atividadesRegistradasDia(reg);
  const plan=arr(planejadas);
  if(plan.length){
    const sts=plan.map((p,i)=>statusAtividadeNormalizado(atividadeRegistradaCorrespondente(regs,p,i)?.status||atividadeRegistradaCorrespondente(regs,p,i)?.statusAtividade||''));
    const preenchidos=sts.filter(Boolean);
    if(!preenchidos.length) return statusAtividadeNormalizado(reg.statusAtividade)||'pendente';
    if(preenchidos.length===plan.length&&preenchidos.every(v=>v==='sim')) return 'sim';
    if(preenchidos.length===plan.length&&preenchidos.every(v=>v==='nao')) return 'nao';
    return 'parcial';
  }
  const total=Math.max(regs.length,reg.atividade?1:0);
  if(!total) return statusAtividadeNormalizado(reg.statusAtividade)||'pendente';
  const sts=Array.from({length:total},(_,i)=>statusAtividadeNormalizado(regs[i]?.status||regs[i]?.statusAtividade||''));
  const preenchidos=sts.filter(Boolean);
  if(!preenchidos.length) return statusAtividadeNormalizado(reg.statusAtividade)||'pendente';
  if(preenchidos.length===total&&preenchidos.every(v=>v==='sim')) return 'sim';
  if(preenchidos.length===total&&preenchidos.every(v=>v==='nao')) return 'nao';
  return 'parcial';
}
function statusAtividadeAgregadoAtividades(atividades=[]){
  const sts=arr(atividades).map(a=>statusAtividadeNormalizado(a.status||a.statusAtividade||''));
  const preenchidos=sts.filter(Boolean);
  if(!sts.length||!preenchidos.length) return '';
  if(preenchidos.length===sts.length&&preenchidos.every(v=>v==='sim')) return 'sim';
  if(preenchidos.length===sts.length&&preenchidos.every(v=>v==='nao')) return 'nao';
  return 'parcial';
}
function primeiraAtividadePendenteIdx(dia={},reg={}){
  const planejadas=atividadesPlanejadasDia(dia);
  const regs=atividadesRegistradasDia(reg||{});
  const idx=planejadas.findIndex((_,i)=>!statusAtividadeNormalizado(regs[i]?.status||regs[i]?.statusAtividade||''));
  return idx>=0?idx:0;
}
function statusAtividadeDiaTexto(reg={},dia={}){
  const st=statusAtividadeAgregado(reg,atividadesPlanejadasDia(dia));
  return ({sim:'atividade registrada',parcial:'atividade parcial',nao:'atividade não realizada',pendente:'atividade pendente'})[st]||'atividade pendente';
}
function nomeAtividadeComplementar(a={}){return String(a.nome||a.atividade||a.k||a.tipoAtividade||'atividade').trim();}
function detalheAtividadeComplementar(a={}){
  return [a.duracaoMin?`${+a.duracaoMin} min`:'',a.intensidade||'',arr(a.impacto).length?`impacto: ${arr(a.impacto).join(', ')}`:'',a.prioridade||''].filter(Boolean).join(' · ');
}
function htmlCampoDorOutra(prefix,valor=''){
  return `<div id="${prefix}-dor-outra-wrap" style="display:none"><label class="fl" for="${prefix}-dor-outra">Descreva a dor ou limitação</label><textarea class="fi" id="${prefix}-dor-outra" rows="2" placeholder="Ex: desconforto na parte interna da coxa, dor perto da escápula...">${escHtml(valor||'')}</textarea><div class="form-help">Use este campo quando escolher “Outra”. O app só associa a uma região se a descrição deixar isso claro.</div></div>`;
}
function ligarCampoDorOutra(regiaoId,wrapId){
  const reg=$(regiaoId),wrap=$(wrapId);if(!reg||!wrap) return;
  const sync=()=>{wrap.style.display=reg.value==='outra'?'block':'none';};
  reg.addEventListener('change',sync);sync();
}
function placeholderAtividadeComplementar(nome=''){
  const t=normTxt(nome);
  if(/corrida|esteira/.test(t)) return 'Ex: corrida leve de 30 min, sem dor...';
  if(/pilates/.test(t)) return 'Ex: aula completa de Pilates, foco em mobilidade...';
  if(/yoga/.test(t)) return 'Ex: prática leve de Yoga, sem desconforto...';
  if(/natacao|natação/.test(t)) return 'Ex: natação leve por 40 min...';
  if(/musculacao|musculação/.test(t)) return 'Ex: treino leve de musculação, sem falha...';
  if(/ciclismo|bike|bicicleta/.test(t)) return 'Ex: pedal leve de 45 min...';
  if(/caminhada/.test(t)) return 'Ex: caminhada de 30 min em ritmo confortável...';
  return 'Ex: atividade leve/moderada, duração e sensação geral...';
}

function intensidadeComplementarNormalizada(v=''){
  const n=normTxt(v);
  if(/intens|forte|pesad|alta/.test(n)) return 'intensa';
  if(/moderad|media|média/.test(n)) return 'moderada';
  if(/leve|baixa|facil|fácil|confort/.test(n)) return 'leve';
  return '';
}
function labelIntensidadeComplementar(v=''){
  return ({leve:'leve',moderada:'moderada',intensa:'intensa'})[intensidadeComplementarNormalizada(v)]||'';
}
function resumoAtividadePlanejada(dia={}){
  const base=arr(dia.atividades)[0]||dia||{};
  const partes=[];
  const dur=duracaoAtividadeMin(base);
  const intens=labelIntensidadeComplementar(base.intensidade||base.sensacao||base.prioridade);
  if(dur) partes.push(`${dur} min planejados`);
  if(intens) partes.push(`intensidade ${intens}`);
  const impacto=arr(base.impacto).filter(Boolean).join(', ');
  if(impacto) partes.push(`impacto: ${impacto}`);
  return partes.join(' · ');
}

function modoIniciante(){return (ST.perfil?.nivel||'init')==='init';}
function rotuloRpeUsuario(){return modoIniciante()?'esforço percebido':'RPE';}
function labelRpeUsuario(){return modoIniciante()?'Esforço percebido':'RPE do treino (6–10)';}
function placeholderRpeUsuario(){return modoIniciante()?'opcional':'6–10';}
function ajudaRpeUsuario(){
  return modoIniciante()
    ?'Opcional. Use 6 se foi confortável, 8 se foi difícil controlado, 9–10 se foi muito pesado ou no limite.'
    :'6: leve, sobrariam 4+ reps · 7: confortável/moderado, sobrariam 3 · 8: difícil controlado, sobrariam 2 · 9: muito difícil, sobraria 1 · 10: máximo. Pode deixar em branco.';
}
function tooltipRpeUsuario(){
  return modoIniciante()
    ?'Esforço percebido é uma escala de 6 a 10 para dizer quão pesado o exercício pareceu.'
    :'RPE é a percepção de esforço de 6 a 10. 6 = confortável, 8 = difícil controlado, 9 = muito difícil, 10 = máximo.';
}
