function normalizarDorFormulario(dor='',dorRegiao=''){
  let d=String(dor||'').trim();
  let r=String(dorRegiao||'').trim();
  if((!d||d==='nao')&&!r) return{dor:d,dorRegiao:''};
  if(r&&(!d||d==='nao')) d='leve';
  if(!r&&d==='nao') return{dor:'nao',dorRegiao:''};
  if(!r&&!d) return{dor:'',dorRegiao:''};
  return{dor:d,dorRegiao:r};
}
function ligarDorRegiaoExclusiva(dorId,regiaoId){
  const dorEl=$(dorId),regEl=$(regiaoId);
  if(!dorEl||!regEl) return;
  dorEl.addEventListener('change',()=>{
    if(!dorEl.value||dorEl.value==='nao') regEl.value='';
  });
  regEl.addEventListener('change',()=>{
    if(regEl.value&&(!dorEl.value||dorEl.value==='nao')) dorEl.value='leve';
  });
}
