// APP
// ═══════════════════════════════════════════════════════════
function mostrarApp(){
  if(!ST.plano){
    const planoSeguro=gerarPlanoComProtecao(ST.perfil);
    if(!planoSeguro) return;
    instalarPlanoGerado(planoSeguro);
  }
  if(!getSem()) iniciaSemana();
  $('ob')?.classList.add('gone');
  const app=$('app');
  if(app){
    app.style.display='block';
    app.classList.add('app-shell-active');
  }
  document.documentElement?.classList?.add('califit-app-mode');
  document.body?.classList?.add('califit-app-mode');
  normalizarRolagemDocumentoCalifit();
  atualizarAcessibilidadeAbasCalifit(+document.querySelector('.nb.on')?.dataset?.tab||0);
  aplicarIconesCalifit(app||document);
  updHdr();
  // 164H: só a aba visível é construída no primeiro carregamento.
  // Semana, Corpo e Assistente continuam sendo renderizados ao primeiro acesso via goTab().
  rHoje();
  mostrarSplash();
}

// ═══════════════════════════════════════════════════════════
// SEMANAS
// ═══════════════════════════════════════════════════════════
function semanaComPreviaPendente(sem){
  return !!(sem&&ST.previaProximaSemana&&String(ST.previaProximaSemana.semanaOrigemId)===String(sem.id));
}
// 166E — virada automática e segura das semanas
function fimSemanaCalendarioTsCalifit(sem){
  const fim=new Date(sem?.fim||0);
  if(Number.isNaN(fim.getTime())) return 0;
  fim.setHours(23,59,59,999);
  return fim.getTime();
}
function semanaEncerradaCalendarioCalifit(sem,agora=new Date()){
  const t=fimSemanaCalendarioTsCalifit(sem);
  return !!(sem&&sem.aberta===true&&!semanaOcultaCalifit(sem)&&t&&new Date(agora).getTime()>t);
}
function semanaFilhaDaViradaCalifit(origemId){
  if(origemId==null) return null;
  return arr(ST.semanas).find(s=>!semanaOcultaCalifit(s)&&idSemanaIgualCalifit(s?.geradaPorFechamentoDe,origemId))||null;
}
function tokenViradaSemanaCalifit(sem,semanaNoBloco=1){
  return [String(sem?.id||''),String(sem?.fim||''),String(Math.max(1,+semanaNoBloco||1))].join('|');
}
function estadoViradaSemanaCalifit(sem=getSem(),agora=new Date()){
  const previa=semanaComPreviaPendente(sem)?ST.previaProximaSemana:null;
  return{
    semanaId:sem?.id||null,
    expirada:semanaEncerradaCalendarioCalifit(sem,agora),
    previaPendente:!!previa,
    previaAutomatica:!!previa?.geradaAutomaticamente,
    pausada:!!sem?.viradaAutomaticaPausada,
    reaberta:!!sem?.reabertaEm,
    aplicada:!!semanaFilhaDaViradaCalifit(sem?.id)
  };
}
function registrarPreviaViradaSemanaCalifit(sem,{automatica=false,forcar=false,motivo='',agora=new Date()}={}){
  if(!sem||!ST.plano) return{ok:false,status:'sem_semana'};
  const filha=semanaFilhaDaViradaCalifit(sem.id);
  if(filha) return{ok:true,status:'ja_aplicada',semana:filha,previa:null};
  if(automatica&&sem.viradaAutomaticaPausada) return{ok:false,status:'pausada'};
  const existente=semanaComPreviaPendente(sem)?ST.previaProximaSemana:null;
  if(existente&&!forcar) return{ok:true,status:'previa_existente',previa:existente};
  const previa=gerarPreviaProximaSemana(sem);
  if(!previa) return{ok:false,status:'falha_geracao'};
  const criadoEm=new Date(agora).toISOString();
  previa.criadaEmOriginal=existente?.criadaEmOriginal||existente?.criadaEm||previa.criadaEm||criadoEm;
  previa.criadaEm=criadoEm;
  previa.geradaAutomaticamente=!!automatica;
  previa.motivoGeracao=motivo||(automatica?'fim_do_periodo_da_semana':'fechamento_manual');
  previa.rotacaoToken=tokenViradaSemanaCalifit(sem,previa.semanaNoBloco||1);
  ST.previaProximaSemana=previa;
  sem.previaPendente=true;
  sem.aberta=true;
  sem.fechada=false;
  sem.viradaAutomaticaPausada=false;
  delete sem.viradaDescartadaEm;
  delete sem.reabertaEm;
  if(automatica) sem.previaAutomaticaGeradaEm=criadoEm;
  else delete sem.previaAutomaticaGeradaEm;
  ST.semanaAtual=sem.id;
  return{ok:true,status:automatica?'previa_automatica_criada':'previa_manual_criada',previa};
}
function prepararViradaAutomaticaSemanaCalifit({agora=new Date(),persistir=true}={}){
  normalizarEstadosSemanasCalifit();
  const sem=getSem();
  if(!ST.done||!ST.plano||!sem) return{ok:false,alterada:false,status:'indisponivel'};
  if(!semanaEncerradaCalendarioCalifit(sem,agora)) return{ok:true,alterada:false,status:'semana_em_andamento'};
  if(semanaFilhaDaViradaCalifit(sem.id)) return{ok:true,alterada:false,status:'ja_aplicada'};
  if(semanaComPreviaPendente(sem)) return{ok:true,alterada:false,status:'previa_existente',previa:ST.previaProximaSemana};
  if(sem.viradaAutomaticaPausada||sem.reabertaEm) return{ok:true,alterada:false,status:'pausada'};
  const resultado=registrarPreviaViradaSemanaCalifit(sem,{automatica:true,motivo:'fim_do_periodo_da_semana',agora});
  if(resultado.ok&&resultado.previa){
    ST.manutencao=Object.assign({},DEF().manutencao,ST.manutencao||{});
    ST.manutencao.ultimaViradaAutomaticaEm=new Date(agora).toISOString();
    if(persistir) salvar();
    return{...resultado,alterada:true};
  }
  return{...resultado,alterada:false};
}
function normalizarPreviaPendente(){
  const prev=ST.previaProximaSemana;if(!prev) return;
  const origem=(ST.semanas||[]).find(s=>String(s.id)===String(prev.semanaOrigemId));
  if(!origem) return;
  const outraAberta=(ST.semanas||[]).some(s=>s.aberta&&String(s.id)!==String(origem.id));
  if(!outraAberta){
    origem.aberta=true;
    origem.fechada=false;
    origem.previaPendente=true;
    ST.semanaAtual=origem.id;
  }
}
function idSemanaIgualCalifit(a,b){return a!=null&&b!=null&&String(a)===String(b);}
function inicioSemanaTsCalifit(sem){
  const t=new Date(sem?.inicio||sem?.createdAt||sem?.criadoEm||0).getTime();
  return Number.isFinite(t)?t:0;
}
function semanaOcultaCalifit(sem){return !!(sem?.rascunho||sem?.reabertaDepois);}
function checkinPertenceSemanaCalifit(checkin,sem){
  if(!checkin||!sem) return false;
  if(checkin.semanaId!=null) return idSemanaIgualCalifit(checkin.semanaId,sem.id);
  const t=new Date(checkin.data||0).getTime();
  const ini=new Date(sem.inicio||0).getTime();
  const fim=new Date(sem.fim||0).getTime();
  if(Number.isFinite(t)&&Number.isFinite(ini)&&Number.isFinite(fim)&&t>=ini&&t<=fim+86400000) return true;
  return checkin.semanaNum!=null&&Number(checkin.semanaNum)===Number(sem.num);
}
function semanaTemConteudoCalifit(sem){
  if(!sem) return false;
  const regs=Object.values(sem.registros||{});
  return regs.some(r=>r&&Object.keys(r).length>0)||(ST.checkins||[]).some(c=>checkinPertenceSemanaCalifit(c,sem));
}
function semanasReaisOrdenadasCalifit(desc=false){
  const lista=(ST.semanas||[]).filter(s=>s&&!semanaOcultaCalifit(s));
  lista.sort((a,b)=>inicioSemanaTsCalifit(a)-inicioSemanaTsCalifit(b)||String(a.id).localeCompare(String(b.id)));
  return desc?lista.reverse():lista;
}
function semanaMaisRecenteRealCalifit(){return semanasReaisOrdenadasCalifit(true)[0]||null;}
function normalizarNumeracaoSemanas(){
  const reais=semanasReaisOrdenadasCalifit(false);
  const mapa=new Map();
  reais.forEach((s,i)=>{s.num=i+1;mapa.set(String(s.id),s.num);});
  (ST.checkins||[]).forEach(c=>{
    if(c?.semanaId&&mapa.has(String(c.semanaId))) c.semanaNum=mapa.get(String(c.semanaId));
    else if(c&&!c.semanaId){
      const sem=reais.find(s=>checkinPertenceSemanaCalifit(c,s));
      if(sem){c.semanaId=sem.id;c.semanaNum=sem.num;}
    }
  });
}
function normalizarEstadosSemanasCalifit({limparRascunhosVazios=true}={}){
  ST.semanas=arr(ST.semanas).filter(s=>s&&typeof s==='object'&&!Array.isArray(s));
  ST.checkins=arr(ST.checkins);
  ST.semanas.forEach((s,i)=>{
    if(s.id==null) s.id=`sem-${inicioSemanaTsCalifit(s)||Date.now()}-${i}`;
    if(!s.registros||typeof s.registros!=='object'||Array.isArray(s.registros)) s.registros={};
    s.aberta=s.aberta===true;
    s.fechada=s.fechada===true;
    if(s.aberta) s.fechada=false;
  });
  if(limparRascunhosVazios){
    const idsRemover=new Set(ST.semanas.filter(s=>semanaOcultaCalifit(s)&&!semanaTemConteudoCalifit(s)).map(s=>String(s.id)));
    if(idsRemover.size){
      ST.semanas=ST.semanas.filter(s=>!idsRemover.has(String(s.id)));
      ST.checkins=ST.checkins.filter(c=>!c?.semanaId||!idsRemover.has(String(c.semanaId)));
    }
  }
  const origemPrev=ST.previaProximaSemana?.semanaOrigemId!=null
    ?ST.semanas.find(s=>idSemanaIgualCalifit(s.id,ST.previaProximaSemana.semanaOrigemId)&&!semanaOcultaCalifit(s))
    :null;
  const abertas=ST.semanas.filter(s=>s.aberta&&!semanaOcultaCalifit(s));
  let preferida=origemPrev||abertas.find(s=>idSemanaIgualCalifit(s.id,ST.semanaAtual))||abertas.sort((a,b)=>inicioSemanaTsCalifit(b)-inicioSemanaTsCalifit(a))[0]||null;
  if(preferida){
    ST.semanas.forEach(s=>{
      if(idSemanaIgualCalifit(s.id,preferida.id)) return;
      if(!s.aberta) return;
      s.aberta=false;
      if(semanaTemConteudoCalifit(s)){s.fechada=true;}
      else{s.fechada=false;s.rascunho=true;s.reabertaDepois=true;}
    });
    preferida.aberta=true;
    preferida.fechada=false;
    ST.semanaAtual=preferida.id;
  }else if(ST.semanaAtual!=null&&!ST.semanas.some(s=>idSemanaIgualCalifit(s.id,ST.semanaAtual))){
    ST.semanaAtual=null;
  }
  if(origemPrev){origemPrev.previaPendente=true;origemPrev.aberta=true;origemPrev.fechada=false;ST.semanaAtual=origemPrev.id;}
  normalizarNumeracaoSemanas();
  return preferida||origemPrev||null;
}
function getSem(){
  const atual=(ST.semanas||[]).find(s=>s.aberta&&!semanaOcultaCalifit(s)&&idSemanaIgualCalifit(s.id,ST.semanaAtual));
  if(atual) return atual;
  return (ST.semanas||[]).filter(s=>s.aberta&&!semanaOcultaCalifit(s)).sort((a,b)=>inicioSemanaTsCalifit(b)-inicioSemanaTsCalifit(a))[0]||null;
}
function iniciaSemana(){
  normalizarEstadosSemanasCalifit();
  if(getSem()) return;
  const h=new Date(),seg=new Date(h);
  seg.setDate(h.getDate()-((h.getDay()+6)%7));seg.setHours(0,0,0,0);
  const sab=new Date(seg);sab.setDate(seg.getDate()+6);
  const criadoEm=new Date().toISOString();
  const nova={id:Date.now(),num:1,inicio:seg.toISOString(),fim:sab.toISOString(),aberta:true,registros:{},resumoIA:'',semanaNoBloco:1,criadoEm,createdAt:criadoEm,planoCriadoEm:criadoEm};
  ST.semanas.push(nova);
  normalizarNumeracaoSemanas();
  ST.semanaAtual=nova.id;
  salvar();
}
function calcStreak(){
  let s=0;const h=new Date();h.setHours(0,0,0,0);const c=new Date(h);
  for(let i=0;i<30;i++){
    const dt=c.toDateString();
    if(ST.semanas.some(sem=>Object.values(sem.registros||{}).some(r=>new Date(r.data).toDateString()===dt&&r.tipo==='feito'))){s++;}else if(i>0)break;
    c.setDate(c.getDate()-1);
  }
  return s;
}
function fmtSem(a,b){return `${new Date(a).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}–${new Date(b).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}`;}
function semanaTemRegistroReal(sem){
  if(!sem) return false;
  const regs=Object.values(sem.registros||{});
  return regs.some(r=>r?.tipo==='feito'||r?.tipo==='perdido'||r?.treino||r?.obs)||(ST.checkins||[]).some(c=>String(c.semanaId)===String(sem.id));
}
function semanaAnteriorVisivel(sem){
  if(!sem||sem.aberta||sem.reabertaDepois||sem.rascunho) return false;
  if(sem.fechada!==true) return false;
  const ativa=getSem();
  if(ativa&&Number(sem.num)<Number(ativa.num)) return true;
  const fim=sem.fim?new Date(sem.fim):null;
  if(fim&&fim>new Date()) return false;
  return true;
}

// ═══════════════════════════════════════════════════════════
// HOJE
// ═══════════════════════════════════════════════════════════
function numMeta(v){
  const n=String(v||'').match(/\d+/);
  return n?+n[0]:0;
}
function rpeLog(log){
  const rpe=Number(log?.rpe);
  if(dificuldadePorRpe(rpe)) return rpe;
  return rpePorDificuldade(log?.diff);
}
function temDorLog(log){
  return analisarDorRegistro(log).temDor;
}
function dorObservadaLog(log){
  const info=analisarDorRegistro(log);
  if(!info.temDor) return null;
  return info.regioes.length?info.regioes.join(', '):'dor/incômodo';
}
function tecnicaRuimLog(log){
  const t=normTxt([log?.tecnica,log?.obs,log?.observacoes].filter(Boolean).join(' '));
  return log?.tecnica==='ruim'||/tecnica ruim|forma ruim|compensei|roubei|perdi tecnica/.test(t);
}
function seriesFeitasLog(log){
  if(Array.isArray(log?.series)&&log.series.length) return log.series.filter(s=>String(s?.reps||'').trim()).length;
  return +log?.series||0;
}
function repsFeitasLog(log){
  if(Array.isArray(log?.series)&&log.series.length){
    const vals=log.series.map(s=>numMeta(s?.reps)).filter(Boolean);
    return vals.length?Math.min(...vals):0;
  }
  return numMeta(log?.reps);
}
function completouMeta(ex,log){
  if(log?.feito!=='sim') return false;
  const sFeitas=seriesFeitasLog(log), sMeta=+ex?.s||0;
  const rFeitas=repsFeitasLog(log), rMeta=numMeta(ex?.r);
  if(!sFeitas&&!rFeitas) return true;
  return (!sMeta||sFeitas>=sMeta)&&(!rMeta||rFeitas>=rMeta);
}
function padraoExercicioCodigo(ex){
  return EXD[nomeTecnicoExercicio(ex)]?.pad||'';
}
function padroesCitadosNoTexto(txt){
  const n=normTxt(txt);
  const citados=new Set();
  if(/agach|squat|pistol|bulgar|avan[cç]o|step/.test(n)) citados.add('agachar');
  if(/rdl|romeno|terra|hinge|dobradica|dobradi[cç]a|posterior|swing|ponte/.test(n)) citados.add('dobrarQ');
  if(/remada|australiana|argola|trx/.test(n)) citados.add('puxarH');
  if(/barra|pull.?up|puxada vertical|scapular/.test(n)) citados.add('puxarV');
  if(/flex|paralela|dip|empurr/.test(n)) citados.add('empurrar');
  if(/prancha|dead bug|bird dog|hollow|core|abdominal/.test(n)) citados.add('core');
  if(/face pull|external rotation|rotacao externa/.test(n)) citados.add('ombro');
  if(/mobilidade|along/.test(n)) citados.add('mob');
  return [...citados];
}
function comentarioContraditorioPadrao(nome,logs){
  const pad=padraoExercicioCodigo(nome);
  if(!pad) return null;
  const txt=(logs||[]).map(l=>[l?.obs,l?.observacoes,l?.comentario,l?.comentarios].filter(Boolean).join(' ')).join(' ');
  const citados=padroesCitadosNoTexto(txt).filter(Boolean);
  const diferentes=citados.filter(p=>p!==pad);
  if(!diferentes.length) return null;
  const label=p=>({puxarV:'puxar vertical',puxarH:'puxar horizontal',empurrar:'empurrar',agachar:'agachar',dobrarQ:'dobradiça de quadril',core:'core',ombro:'ombro/manguito',mob:'mobilidade'}[p]||p);
  return{padraoReal:label(pad),padroesCitados:diferentes.map(label)};
}
function sugestaoDorLeveExercicio(nome,dorObs){
  const n=normTxt(nome);
  const reg=String(dorObs||'').split(',').map(x=>x.trim()).filter(Boolean);
  const dorFmt=reg.length?formatarRegioesDor(reg):'sem região especificada';
  const dorTxt=reg.length?`Dor ${dorFmt} registrada durante ${nomeExercicioTexto(nome,true)}.`:`Dor registrada durante ${nomeExercicioTexto(nome,true)}.`;
  if(/prancha lateral/.test(n)) return `Manter a prancha lateral sem progressão. Como houve dor ${dorFmt}, repita apenas se estiver confortável; se a dor reaparecer, reduza o tempo ou troque por uma variação mais leve.`;
  if(/ponte unilateral/.test(n)) return `Manter a ponte unilateral sem progressão. Como houve dor ${dorFmt}, execute com amplitude confortável e interrompa se a dor reaparecer.`;
  if(/flex/.test(n)) return `${dorTxt} Manter sem progressão; use inclinação mais alta ou reduza amplitude se houver desconforto.`;
  if(/remada/.test(n)) return `${dorTxt} Manter sem progressão e reduzir amplitude ou volume se a dor reaparecer.`;
  return `Manter ${nomeExercicioTexto(nome,true)} sem progressão. Como houve dor ${dorFmt}, repita apenas se estiver confortável; se a dor reaparecer, reduza volume, amplitude ou use uma variação mais leve.`;
}
function sugestaoNaoFezPorDor(nome,dorObs,parcial=false){
  const n=normTxt(nome);
  const reg=String(dorObs||'').split(',').map(x=>x.trim()).filter(Boolean);
  const dorFmt=reg.length?formatarRegioesDor(reg):'sem região especificada';
  if(parcial) return `${nome} foi feito parcialmente com dor ${dorFmt}. Reduza volume ou amplitude e não progrida no próximo treino.`;
  if(/prancha/.test(n)) return `${nome} não realizada por dor ${dorFmt}. Não progredir. No próximo treino, use uma variação mais leve, como Dead Bug ou prancha com menor tempo, apenas se estiver sem dor.`;
  if(/flex/.test(n)) return `${nome} não realizada por dor ${dorFmt}. Não progredir. No próximo treino, use inclinação mais alta, reduza amplitude ou substitua temporariamente por variação sem dor.`;
  return `${nome} não realizado por dor ${dorFmt}. Não progredir. No próximo treino, use uma variação mais leve, reduza amplitude/volume ou substitua temporariamente por opção sem dor.`;
}
function checkinMinimoTreino(registroTreino={}){
  const origem=registroTreino?.checkinMinimo||registroTreino?.treino?.checkinMinimo||registroTreino?.feedbackMinimo||{};
  const exs=arr(registroTreino?.exercicios||registroTreino?.treino?.exercicios);
  const logs=exs.map(e=>e?.log||e).filter(Boolean);
  const dor=origem.dor||registroTreino.dorGeral||'';
  const dificuldade=origem.dificuldade||registroTreino.dificuldadeGeral||'';
  const esforco=origem.esforco||registroTreino.esforcoGeral||'';
  const diffs=logs.map(l=>normTxt(l.diff||'')).filter(Boolean);
  const rpes=logs.map(rpeLog).filter(Boolean);
  const dores=logs.map(l=>dorRegistroEfetiva(l)).filter(v=>v&&!dorNegativa(v));
  const dorDerivada=dores.length?'sim':logs.some(l=>normTxt(l.dor)==='nao')?'nao':'';
  const difDerivada=diffs.some(d=>['pesado','muito'].includes(d))?'dificil':diffs.length&&diffs.every(d=>d==='leve')?'facil':diffs.length?'adequado':'';
  const rpeMax=rpes.length?Math.max(...rpes):0;
  const esforcoDerivado=esforco||(rpeMax>=8?'alto':rpeMax>=5?'moderado':rpeMax?'leve':'');
  return{dor:dor||dorDerivada,dificuldade:dificuldade||difDerivada,esforco:esforcoDerivado};
}
function checkinMinimoCompleto(registroTreino){
  const c=checkinMinimoTreino(registroTreino);
  return !!(c.dor&&c.dificuldade&&c.esforco);
}
function motivoCheckinMinimoIncompleto(registroTreino){
  const c=checkinMinimoTreino(registroTreino);
  const faltam=[];
  if(!c.dor) faltam.push('dor');
  if(!c.dificuldade) faltam.push('dificuldade geral');
  if(!c.esforco) faltam.push('esforço geral');
  return faltam.length?`Feedback incompleto: informe ${fraseListaHumana(faltam)}.`:'Feedback completo.';
}
function treinoContaParaProgressao(registroTreino){
  if(!registroTreino||registroTreino.tipo==='descanso'||registroTreino.tipo==='atividade') return false;
  const status=statusGeralCheckinCalifit(registroTreino.statusGeral||registroTreino.treino?.statusGeral,registroTreino.treino?.exercicios||[]);
  if(status!=='sim') return false;
  if(registroTreino.progressaoIgnorada||registroTreino.treino?.progressaoIgnorada) return false;
  return checkinMinimoCompleto(registroTreino);
}
function statusProgressaoPorCheckin(registroTreino){
  const status=statusGeralCheckinCalifit(registroTreino?.statusGeral||registroTreino?.treino?.statusGeral,registroTreino?.treino?.exercicios||[]);
  if(status==='nao') return 'Sem progressão · Treino não realizado';
  if(status==='parcial') return 'Sem progressão · Treino parcial';
  return treinoContaParaProgressao(registroTreino)?'Feedback completo':'Sem progressão · Feedback incompleto';
}
function qualidadeFeedbackTreino(registroTreino={}){
  const checkin=checkinMinimoTreino(registroTreino);
  const completo=checkinMinimoCompleto(registroTreino);
  const exs=arr(registroTreino?.exercicios||registroTreino?.treino?.exercicios);
  const logs=exs.map(e=>e?.log||e).filter(Boolean);
  const dores=logs.map(analisarDorRegistro).filter(d=>d.temDor);
  const dorTxt=normTxt(checkin.dor||'');
  const dorRelevante=/moderada|forte|aguda|irradiad|pior/.test(dorTxt)||dores.some(d=>d.nivel==='moderada'||d.alertaProfissional);
  const dorLeve=/leve|sim/.test(dorTxt)||dores.some(d=>d.nivel==='leve');
  const dificuldade=normTxt(checkin.dificuldade||'');
  const esforco=normTxt(checkin.esforco||'');
  const diffLogs=logs.map(regraDificuldadeLog).filter(Boolean);
  const rpes=logs.map(rpeLog).filter(Boolean);
  const rpeMax=rpes.length?Math.max(...rpes):0;
  const pesado=dificuldade==='dificil'||['alto','pesado','muito_pesado','maximo'].includes(esforco)||rpeMax>=9||diffLogs.some(d=>['manter','reduzir_ou_regredir'].includes(d.acao));
  const execucoes=logs.filter(l=>l.feito).length;
  const concluidos=logs.filter(l=>l.feito==='sim').length;
  const parciais=logs.filter(l=>l.feito==='parcial').length;
  const naoFez=logs.filter(l=>l.feito==='nao').length;
  const acimaSemFeedback=logs.some((l,i)=>registroAcimaDoPlanejado(exs[i]||{},l).acima)&&!completo;
  const observacao=normTxt(logs.map(l=>[l.obs,l.observacoes,l.continuar].filter(Boolean).join(' ')).join(' '));
  const piora=/pior|piorou|agravou|insegur|formig|travou/.test(observacao);
  const ignorada=registroTreino.progressaoIgnorada||registroTreino.treino?.progressaoIgnorada;
  const aquecimentoConcluido=!!(registroTreino.aquecimentoConcluido||registroTreino.treino?.aquecimentoConcluido);
  const detalhados=logs.filter(l=>l.feito&&(
    arr(l.series).length||l.reps||l.rpe||l.dor||l.tecnica||l.obs||l.observacoes
  )).length;
  const detalhesSuficientes=detalhados>=Math.max(1,Math.ceil(Math.max(logs.length,1)*.6));
  return{checkin,completo,dorLeve,dorRelevante,pesado,execucoes,concluidos,parciais,naoFez,acimaSemFeedback,piora,ignorada,aquecimentoConcluido,detalhados,detalhesSuficientes,totalExercicios:logs.length};
}
function avaliarConfiancaFeedbackCalifit(registroTreino={},perfil=ST?.perfil||{}){
  const q=qualidadeFeedbackTreino(registroTreino);
  const positivos=[],ausentes=[],riscos=[];
  if(q.detalhados)positivos.push(`${q.detalhados} exercício${q.detalhados===1?'':'s'} com registro detalhado`);
  if(q.aquecimentoConcluido)positivos.push('aquecimento concluído');
  if(q.completo)positivos.push('check-in geral completo');
  if(q.execucoes)positivos.push('status dos exercícios registrado');
  if(!q.completo){
    if(!q.checkin.dor)ausentes.push('dor geral');
    if(!q.checkin.dificuldade)ausentes.push('dificuldade global');
    if(!q.checkin.esforco)ausentes.push('esforço global');
    ausentes.push('check-in geral completo');
  }
  if(q.dorRelevante||q.piora)riscos.push('dor ou piora relevante');
  if(cirurgiaTemLimitacaoAtiva(perfil))riscos.push('cirurgia/recuperação ativa');
  if(q.parciais||q.naoFez)riscos.push('execução parcial ou não realizada');
  if(q.pesado)riscos.push('esforço alto ou dificuldade elevada');
  const bloqueada=!!(q.ignorada||q.dorRelevante||q.piora||cirurgiaTemLimitacaoAtiva(perfil));
  let nivel='baixa';
  if(!bloqueada&&!q.parciais&&!q.naoFez){
    if(q.completo&&q.detalhesSuficientes)nivel='alta';
    else if(q.detalhesSuficientes)nivel='média';
    else if(q.completo&&q.execucoes)nivel='média';
  }
  const explicacao=nivel==='alta'
    ?'Os registros por exercício e o check-in geral estão completos e consistentes.'
    :nivel==='média'&&q.detalhesSuficientes&&!q.completo
      ?'Os exercícios foram registrados, mas falta o check-in geral da sessão.'
      :bloqueada
        ?'Há informação de risco; as recomendações permanecem conservadoras.'
        :'Ainda faltam registros detalhados e um check-in geral suficiente.';
  return{nivel,bloqueada,positivos:[...new Set(positivos)],ausentes:[...new Set(ausentes)],riscos:[...new Set(riscos)],explicacao,qualidade:q};
}
function htmlConfiancaFeedbackCalifit(registroTreino={}){
  const c=avaliarConfiancaFeedbackCalifit(registroTreino);
  const lista=(titulo,itens)=>itens.length?`<div class="confidence-factor"><strong>${titulo}</strong><ul>${itens.map(x=>`<li>${escHtml(x)}</li>`).join('')}</ul></div>`:'';
  return `<div class="confidence-explanation confidence-${escHtml(c.nivel)}"><div><strong>Confiança ${escHtml(c.nivel)}:</strong> ${escHtml(c.explicacao)}</div><details><summary>Por que esta confiança?</summary><div class="confidence-factors">${lista('Dados disponíveis',c.positivos)}${lista('Dados ausentes',c.ausentes)}${lista('Fatores de cautela',c.riscos)}</div></details></div>`;
}
function scoreConfiancaFeedback(registroTreino){
  const q=qualidadeFeedbackTreino(registroTreino);
  if(q.ignorada||q.dorRelevante||q.piora) return 0;
  let score=q.completo?55:15;
  if(!q.dorLeve) score+=15; else score-=10;
  if(['facil','adequado'].includes(normTxt(q.checkin.dificuldade))) score+=10;
  if(normTxt(q.checkin.esforco)==='moderado'||normTxt(q.checkin.esforco)==='leve') score+=10;
  if(q.execucoes&&q.concluidos>=Math.max(1,Math.ceil(q.execucoes*0.7))) score+=10;
  if(q.parciais) score-=10;
  if(q.naoFez) score-=20;
  if(q.pesado) score-=20;
  if(q.acimaSemFeedback) score-=20;
  return Math.max(0,Math.min(100,score));
}
function classificarConfiancaFeedback(registroTreino){
  const avaliacao=avaliarConfiancaFeedbackCalifit(registroTreino);
  const q=avaliacao.qualidade;
  if(avaliacao.bloqueada) return 'bloqueada';
  // Um exercício Parcial ou Não fiz pode ter feedback detalhado, mas não confirma
  // tolerância suficiente para liberar progressão automática.
  if(q.parciais||q.naoFez) return 'baixa';
  return avaliacao.nivel;
}
function resumoConfiancaSemana(treinosSemana=[]){
  const treinos=arr(treinosSemana).filter(r=>r?.tipo==='feito'&&r.treino);
  const avaliacoes=treinos.map(r=>avaliarConfiancaFeedbackCalifit(r));
  const classes=avaliacoes.map(a=>a.bloqueada?'bloqueada':a.nivel);
  const contagem=classes.reduce((acc,c)=>{acc[c]=(acc[c]||0)+1;return acc;},{});
  const completos=treinos.filter(checkinMinimoCompleto).length;
  const qualidades=treinos.map(qualidadeFeedbackTreino);
  const execucaoIncompleta=qualidades.some(q=>q.parciais||q.naoFez);
  const bloqueados=contagem.bloqueada||0;
  const baixas=contagem.baixa||0;
  const altas=contagem.alta||0;
  const medias=contagem['média']||0;
  const classe=bloqueados?'bloqueada':(!treinos.length?'baixa':(altas===treinos.length?'alta':(medias||avaliacoes.some(a=>a.qualidade.detalhesSuficientes)?'média':'baixa')));
  const texto=classe==='alta'
    ?'Confiança do feedback: alta. Pode haver progressão leve se não houver dor.'
    :classe==='média'
      ?'Confiança do feedback: média. Mantive volume e variações atuais, com progressão mínima quando segura.'
      :classe==='bloqueada'
        ?'Dor informada. Mantive a progressão conservadora por segurança.'
        :execucaoIncompleta
          ?'Confiança do feedback: baixa. Execução parcial ou não realizada: sem progressão automática.'
          :'Confiança do feedback: baixa. Progressão conservadora por feedback incompleto.';
  return{classe,contagem,total:treinos.length,completos,texto,fatores:avaliacoes};
}
function confiancaPreviaSemana(semana){
  const treinos=Object.values(semana?.registros||{}).filter(r=>r?.tipo==='feito'&&r.treino);
  return resumoConfiancaSemana(treinos);
}
function motivosAjustePreviaSemana(semana,contexto={}){
  const registros=Object.values(semana?.registros||{});
  const treinos=registros.filter(r=>r?.tipo==='feito'&&r.treino);
  const perdidos=registros.filter(r=>r?.tipo==='perdido');
  const completos=treinos.filter(treinoContaParaProgressao);
  const incompletos=treinos.filter(r=>!treinoContaParaProgressao(r));
  const checkin=ultimoCheckinDaSemana(semana)||null;
  const preferencia=checkin?.respostas?.preferencia||'';
  const recuperacao=resumoRecuperacaoSemana(semana);
  const sinais=agregarSinaisRegistrosDaSemana(semana);
  const qualidades=treinos.map(qualidadeFeedbackTreino);
  const saudeAtiva=cirurgiaTemLimitacaoAtiva(ST.perfil);
  const cargasPendentes=equipamentosCarregadosSemCarga(ST.perfil);
  const estrategiaRetorno=estrategiaRetornoGradual(ST.perfil,avaliarProntidaoInicial(ST.perfil));
  const planejados=(ST.perfil.diasTreino||[]).length||3;
  const dorRelevante=sinais.temDor||recuperacao.temDor||qualidades.some(q=>q.dorRelevante||q.piora);
  const dorModeradaForte=sinais.nivel==='moderada'||sinais.nivel==='forte'||recuperacao.nivel==='moderada'||recuperacao.nivel==='forte'||qualidades.some(q=>q.dorRelevante);
  const acimaSemFeedback=qualidades.some(q=>q.acimaSemFeedback);
  const pesado=qualidades.some(q=>q.pesado);
  const retornoConsolidado=completos.length>=2&&treinos.length>=planejados&&!dorRelevante&&!sinais.tecnicaRuim&&!sinais.pesado&&!sinais.parcialOuNao;
  const retornoPendente=!!estrategiaRetorno.ativa&&!retornoConsolidado;
  const motivos=[];
  if(!treinos.length) motivos.push('Sem treinos concluídos: mantive o plano sem progressão.');
  else if(!completos.length) motivos.push('Treinos registrados, mas sem feedback mínimo. Mantive a progressão conservadora.');
  else if(incompletos.length) motivos.push('Usei apenas treinos com feedback completo para ajustar a semana.');
  if(perdidos.length) motivos.push('Treino perdido registrado: mantive o plano sem progressão automática nesta semana.');
  if(dorModeradaForte) motivos.push('Dor informada: não aumentei volume.');
  else if(dorRelevante) motivos.push('Dor leve ou desconforto informado: mantive cautela.');
  if(acimaSemFeedback) motivos.push('Registro acima do planejado sem feedback completo: mantive progressão cautelosa.');
  if(sinais.parcialOuNao) motivos.push('Execução Parcial ou Não fiz registrada: suspendi a progressão automática.');
  if(pesado) motivos.push(`${rotuloRpeUsuario()} alto ou exercício pesado: não avancei agressivamente.`);
  if(retornoPendente) motivos.push('Retorno gradual ainda não consolidado: mantive volume e variações atuais.');
  if(saudeAtiva) motivos.push('Recuperação ou cirurgia ativa: mantive cautela e evitei progressão agressiva.');
  if(cargasPendentes.length) motivos.push(`Carga pendente em ${fraseListaHumana(cargasPendentes)}: não autorizei aumento de carga externa.`);
  if(preferencia==='aumentar'&&contexto.ajuste!=='progressao_leve') motivos.push('Preferência por aumentar volume não aplicada porque o feedback da semana exige cautela.');
  if(preferencia==='manter') motivos.push('Preferência por manter volume registrada: mantive volume e variações atuais.');
  if(preferencia==='reduzir') motivos.push('Preferência por reduzir volume considerada na prévia.');
  if(recuperacao.texto) motivos.push(recuperacao.texto);
  return{motivos,treinos,perdidos,completos,incompletos,checkin,preferencia,recuperacao,sinais,qualidades,dorRelevante,dorModeradaForte,acimaSemFeedback,pesado,retornoPendente,retornoConsolidado,saudeAtiva,cargasPendentes};
}
function direcaoAlteracaoPreviaCalifit(alteracao={}){
  const antes=String(alteracao.antes||'').trim();
  const depois=String(alteracao.depois||'').trim();
  const motivo=normTxt(alteracao.motivo||'');
  if(!antes||!depois||normTxt(antes)===normTxt(depois)) return 'manter';
  const nums=v=>(String(v).match(/\d+(?:[.,]\d+)?/g)||[]).map(n=>+n.replace(',','.'));
  const a=nums(antes), d=nums(depois);
  if(/descanso/.test(normTxt(antes+' '+depois))&&a.length&&d.length){
    if(d[0]<a[0]) return 'aumentar';
    if(d[0]>a[0]) return 'reduzir';
  }
  const prescA=antes.match(/(\d+)\s*x\s*(\d+)(?:\s*[–-]\s*(\d+))?/i);
  const prescD=depois.match(/(\d+)\s*x\s*(\d+)(?:\s*[–-]\s*(\d+))?/i);
  if(prescA&&prescD){
    const sa=+prescA[1], sd=+prescD[1];
    if(sd<sa) return 'reduzir';
    if(sd>sa) return 'aumentar';
    const ra=+(prescA[3]||prescA[2]), rd=+(prescD[3]||prescD[2]);
    if(rd<ra) return 'reduzir';
    if(rd>ra) return 'aumentar';
  }
  if(a.length&&d.length){
    if(d[0]<a[0]) return /progress|facil|fácil/.test(motivo)?'aumentar':'reduzir';
    if(d[0]>a[0]) return /reduz|regred|dor|dificil|difícil|cautela/.test(motivo)?'reduzir':'aumentar';
  }
  if(/reduz|regred|dor|dificil|difícil|cautela/.test(motivo)&&!/progress|facil|fácil/.test(motivo)) return 'reduzir';
  if(/progress|facil|fácil|aument/.test(motivo)) return 'aumentar';
  return 'manter';
}
function ajustesPrePopuladosPrevia(semana,previa={}){
  const confianca=confiancaPreviaSemana(semana);
  const base=motivosAjustePreviaSemana(semana,{ajuste:''});
  const algumPermite=base.completos.some(r=>progressaoPermitidaPorFeedback(r,{dor:base.dorRelevante,cautela:base.pesado}));
  const intensidade=base.completos.map(r=>intensidadeProgressaoPorFeedback(r,{dor:base.dorRelevante,cautela:base.pesado}));
  const direcoes=arr(previa.alteracoesAplicadas||previa.alteracoes).map(direcaoAlteracaoPreviaCalifit);
  const temReducao=direcoes.includes('reduzir');
  const temAumento=direcoes.includes('aumentar');
  let ajuste='mantido';
  let status='Mantido por cautela';
  if(base.dorModeradaForte){
    ajuste='reduzido';
    status='Reduzido por dor';
  }else if(!base.treinos.length){
    ajuste='mantido';
    status='Mantido por ausência de treinos concluídos';
  }else if(!base.completos.length){
    ajuste='mantido';
    status='Mantido por feedback incompleto';
  }else if(base.perdidos.length){
    ajuste='mantido';
    status='Mantido por treino perdido';
  }else if(base.retornoPendente){
    ajuste='mantido';
    status='Mantido por retorno gradual';
  }else if(base.saudeAtiva){
    ajuste='bloqueado';
    status='Ajuste bloqueado por segurança';
  }else if(base.preferencia==='reduzir'||temReducao){
    ajuste='reduzido';
    status=base.preferencia==='reduzir'
      ?'Reduzido por preferência do usuário'
      :(base.pesado?'Reduzido por esforço alto':'Reduzido por cautela');
  }else if(base.sinais.parcialOuNao){
    ajuste='mantido';
    status='Mantido por execução parcial';
  }else if(base.pesado){
    ajuste='mantido';
    status='Mantido por esforço alto';
  }else if(base.cargasPendentes.length){
    ajuste='mantido';
    status='Mantido por cautela';
  }else if(confianca.classe==='alta'&&algumPermite&&intensidade.includes('leve')&&!base.dorRelevante&&!base.pesado&&(temAumento||base.preferencia==='aumentar')){
    ajuste='progressao_leve';
    status='Progressão leve sugerida';
  }else if(confianca.classe==='bloqueada'){
    ajuste='bloqueado';
    status='Ajuste bloqueado por segurança';
  }else if(base.incompletos.length){
    ajuste='mantido';
    status='Mantido por feedback incompleto';
  }else if(base.preferencia==='manter'){
    ajuste='mantido';
    status='Mantido por preferência do usuário';
  }
  const motivos=motivosAjustePreviaSemana(semana,{ajuste}).motivos;
  return{ajuste,status,motivos,confianca,preferencia:base.preferencia};
}
function resumoDecisaoPreviaSemana(semana,planoAtual,contexto={}){
  const previa=contexto.previa||{};
  const decisao=ajustesPrePopuladosPrevia(semana,previa);
  const motivos=[...new Set(decisao.motivos.filter(Boolean))];
  if(!motivos.length) motivos.push(decisao.confianca.texto||'Plano mantido com progressão leve apenas se houver boa tolerância.');
  const confiancaTexto=decisao.ajuste==='progressao_leve'
    ?decisao.confianca.texto
    :`Confiança do feedback: ${decisao.confianca.classe}. A decisão final foi ${decisao.status.toLowerCase()}.`;
  return{
    titulo:'Por que a prévia ficou assim',
    confianca:decisao.confianca.classe,
    confiancaTexto,
    ajuste:decisao.status,
    motivos,
    preferencia:decisao.preferencia||'',
    aviso:decisao.ajuste==='progressao_leve'
      ?'Progressão leve sugerida: não aumentei carga e volume ao mesmo tempo.'
      :decisao.ajuste==='reduzido'
        ?'Dor, recuperação ou preferência pedem cautela nesta semana.'
        :'Mantive volume e variações atuais quando os dados não sustentam avanço seguro.'
  };
}
function normalizarAlteracoesPreviaCalifit(alteracoes=[]){
  const vistos=new Set();
  return arr(alteracoes).filter(a=>a&&typeof a==='object').filter(a=>{
    const chave=[a.tipo,a.dia,a.exercicioOriginal,a.exercicioNovo,a.exercicio,a.antes,a.depois,a.motivo]
      .map(v=>normTxt(v||'')).join('|');
    if(vistos.has(chave)) return false;
    vistos.add(chave);return true;
  });
}
function finalizarPreviaProximaSemana(previa,semana){
  previa=previa||{};
  previa.alteracoesAplicadas=normalizarAlteracoesPreviaCalifit(previa.alteracoesAplicadas||previa.alteracoes||[]);
  previa.alteracoes=previa.alteracoesAplicadas;
  const cargaComplementar=resumoCargaAtividadesSemanaCalifit(semana);
  if(previa.planoBaseSemTempo&&cargaComplementar.relevantes.length){
    previa.planoBaseSemTempo=aplicarAjustesAtividadesRegistradasPlanoCalifit(previa.planoBaseSemTempo,semana,ST.perfil);
    previa.plano=ajustarPlanoAoTempo(ajustarDescansosPlano(cloneObj(previa.planoBaseSemTempo)),ST.perfil);
    previa.cargaComplementarRealizada=cargaComplementar;
    previa.resumoAjustes=arr(previa.resumoAjustes);
    if(cargaComplementar.texto&&!previa.resumoAjustes.some(t=>normTxt(t)===normTxt(cargaComplementar.texto))) previa.resumoAjustes.push(cargaComplementar.texto);
  }
  if(previa.plano) previa.plano=deduplicarPlano(previa.plano);
  if(previa.planoBaseSemTempo) previa.planoBaseSemTempo=deduplicarPlano(previa.planoBaseSemTempo);
  const decisao=resumoDecisaoPreviaSemana(semana,previa?.plano,{previa});
  previa.decisaoPrevia=decisao;
  previa.resumoAjustes=arr(previa.resumoAjustes).filter((t,i,a)=>t&&a.findIndex(x=>normTxt(x)===normTxt(t))===i);
  [decisao.confiancaTexto,decisao.ajuste,...decisao.motivos].forEach(t=>{
    if(t&&!previa.resumoAjustes.some(x=>normTxt(x)===normTxt(t))) previa.resumoAjustes.push(t);
  });
  return previa;
}
function recalcularPreviaPendenteCalifit(semana,motivo='dados da semana atualizados'){
  if(!semana) return null;
  const anterior=ST.previaProximaSemana;
  const origemId=anterior?.semanaOrigemId;
  const pendente=!!semana.previaPendente||(origemId!=null&&String(origemId)===String(semana.id));
  if(!pendente) return null;
  const previa=gerarPreviaProximaSemana(semana);
  if(!previa) return null;
  previa.atualizadaEm=new Date().toISOString();
  previa.motivoAtualizacao=motivo;
  previa.criadaEmOriginal=anterior?.criadaEmOriginal||anterior?.criadaEm||previa.criadaEm;
  previa.geradaAutomaticamente=!!anterior?.geradaAutomaticamente;
  previa.motivoGeracao=anterior?.motivoGeracao||previa.motivoGeracao||'fechamento_manual';
  previa.rotacaoToken=anterior?.rotacaoToken||tokenViradaSemanaCalifit(semana,previa.semanaNoBloco||1);
  ST.previaProximaSemana=previa;
  semana.previaPendente=true;
  return previa;
}
function progressaoPermitidaPorFeedback(registroTreino,contexto={}){
  const c=classificarConfiancaFeedback(registroTreino);
  if(c==='bloqueada'||c==='baixa') return false;
  if(contexto.dor||contexto.cautela) return false;
  return true;
}
function intensidadeProgressaoPorFeedback(registroTreino,contexto={}){
  if(!progressaoPermitidaPorFeedback(registroTreino,contexto)) return classificarConfiancaFeedback(registroTreino)==='bloqueada'?'bloqueada':'manter';
  return classificarConfiancaFeedback(registroTreino)==='alta'?'leve':'mínima';
}
function coletarHistoricoExecucoes(exercicio){
  const nomesAlvo=new Set([exercicio?.n,exercicio?.nome,nomeTecnicoExercicio(exercicio)].filter(Boolean).map(normTxt));
  return ST.semanas.flatMap(s=>Object.values(s.registros||{}))
    .filter(r=>r.tipo==='feito'&&r.treino&&treinoContaParaProgressao(r))
    .sort((a,b)=>new Date(a.data)-new Date(b.data))
    .flatMap(r=>(r.treino.exercicios||[]).filter(e=>{
      const nomesRegistro=[e.nome,e.n,e.exercicioId,e.nomeOriginal].filter(Boolean).map(normTxt);
      return nomesRegistro.some(n=>nomesAlvo.has(n));
    }).map(e=>({...e,treinoData:r.data})));
}
function exerciciosRegistradosDoTreino(treino={},diaIdx=null){
  const blocos=[
    ['exercicios','ex'],['principal','ex'],['aquecimento','aq'],['aq','aq'],
    ['core','core'],['ombro','ombro'],['manguito','ombro'],['acessorios','acessorios']
  ];
  const arr=[];
  blocos.forEach(([campo,bloco])=>{
    if(!Array.isArray(treino[campo])) return;
    treino[campo].forEach((ex,indice)=>{
      if(!ex) return;
      const dia=Number.isInteger(+ex.diaIdx)?+ex.diaIdx:(Number.isInteger(+diaIdx)?+diaIdx:null);
      const blocoRegistro=ex.bloco||(campo==='exercicios'?'':bloco);
      const indiceRegistro=Number.isInteger(+ex.indice)?+ex.indice:(campo==='exercicios'?null:indice);
      const ocorrenciaKey=ex.ocorrenciaKey||(dia!=null&&blocoRegistro
        ?identidadeOcorrenciaExercicio(dia,blocoRegistro,indiceRegistro,ex)
        :'');
      arr.push({...ex,diaIdx:dia,bloco:blocoRegistro,indice:indiceRegistro,ocorrenciaKey});
    });
  });
  const vistos=new Set();
  return arr.filter(ex=>{
    const nome=ex?.nome||ex?.n;
    const k=ex.ocorrenciaKey||[ex.diaIdx,ex.bloco,ex.indice,nome,ex?.prescricao,ex?.r,JSON.stringify(ex?.log||{})].join('|');
    if(!nome||vistos.has(k)) return false;
    vistos.add(k);return true;
  });
}
function coletarSinaisSemana(semana=null,estado=ST){
  const st=estado||ST;
  const limite=Date.now()-7*24*60*60*1000;
  const semanas=semana?[semana]:(st.semanas||[]);
  const registros=semanas.flatMap(sem=>Object.entries(sem?.registros||{}).map(([diaIdx,r])=>({sem,diaIdx:+diaIdx,reg:r})))
    .filter(x=>x.reg?.tipo==='feito'&&x.reg.treino&& (semana||new Date(x.reg.data||x.reg.treino.data||0).getTime()>=limite));
  const treinosDetalhados=registros.filter(x=>x.reg.treino?.dadosDetalhados||treinoTemDadosDetalhados(x.reg.treino)).length;
  const treinosSimples=Math.max(0,registros.length-treinosDetalhados);
  const mapaDor=new Map();
  let parcialOuNao=0, pesado=0, tecnicaRuim=0;
  registros.forEach(({diaIdx,reg})=>{
    exerciciosRegistradosDoTreino(reg.treino,diaIdx).forEach(ex=>{
      const log=ex.log||ex;
      const info=analisarDorRegistro(log);
      const nome=ex.nome||ex.n||'Exercício';
      const pad=padraoExercicioCodigo(ex)||'padrão não identificado';
      const feito=log?.feito||ex?.feito||'';
      const dif=regraDificuldadeLog(log);
      const difPesada=(+log?.rpe||0)>=9||dif?.acao==='manter'||dif?.acao==='reduzir_ou_regredir';
      const tecRuim=tecnicaRuimLog(log);
      const statusComDor=(feito==='nao'||feito==='parcial')&&info.temDor;
      if(info.temDor||statusComDor||difPesada||tecRuim){
        const ocorrenciaKey=ex.ocorrenciaKey||'';
        const diaRegistro=Number.isInteger(+ex.diaIdx)?+ex.diaIdx:diaIdx;
        const key=ocorrenciaKey
          ?`ocorrencia|${ocorrenciaKey}`
          :`legado|${diaRegistro}|${normTxt(nome)}|${pad}`;
        const atual=mapaDor.get(key)||{
          exercicio:nome,padrao:pad,regioes:new Set(),intensidades:new Set(),dias:new Set(),
          frequencia:0,naoPorDor:false,parcialPorDor:false,dificil:false,tecnicaRuim:false,
          ocorrenciaKey,diaIdx:diaRegistro,bloco:ex.bloco||'',indice:Number.isInteger(+ex.indice)?+ex.indice:null,
          exercicioId:ex.exercicioId||'',nomeOriginal:ex.nomeOriginal||'',equipamentoUsado:ex.equipamentoUsado||''
        };
        info.regioes.forEach(r=>atual.regioes.add(r));
        if(info.nivel&&info.nivel!=='nenhuma') atual.intensidades.add(info.nivel);
        atual.dias.add(diaRegistro);
        if(info.temDor){atual.frequencia++;}
        if(feito==='nao'&&info.temDor) atual.naoPorDor=true;
        if(feito==='parcial'&&info.temDor) atual.parcialPorDor=true;
        if(difPesada) atual.dificil=true;
        if(tecRuim) atual.tecnicaRuim=true;
        mapaDor.set(key,atual);
      }
      // Parcial/Não fiz sempre bloqueia progressão automática, mesmo sem dor.
      // A dor continua sendo tratada separadamente para adaptações de segurança.
      if(feito==='nao'||feito==='parcial') parcialOuNao++;
      if(difPesada) pesado++;
      if(tecRuim) tecnicaRuim++;
    });
  });
  const dores=[...mapaDor.values()].map(x=>({
    exercicio:x.exercicio,padrao:x.padrao,regioes:[...x.regioes],intensidades:[...x.intensidades],
    frequencia:x.frequencia,dias:[...x.dias].sort((a,b)=>a-b),naoPorDor:x.naoPorDor,parcialPorDor:x.parcialPorDor,dificil:x.dificil,tecnicaRuim:x.tecnicaRuim,
    ocorrenciaKey:x.ocorrenciaKey||'',diaIdx:x.diaIdx,bloco:x.bloco||'',indice:x.indice,
    exercicioId:x.exercicioId||'',nomeOriginal:x.nomeOriginal||'',equipamentoUsado:x.equipamentoUsado||''
  }));
  const regioes=[...new Set(dores.flatMap(d=>d.regioes))];
  const niveis=dores.flatMap(d=>d.intensidades);
  const nivel=niveis.includes('forte')?'forte':niveis.includes('moderada')?'moderada':dores.length?'leve':'nenhuma';
  const resumo=dores.length
    ?`Houve relato de dor/desconforto em ${dores.map(i=>`${i.exercicio}${i.regioes.length?' ('+i.regioes.join(', ')+')':''}${i.frequencia>1?' · '+i.frequencia+'x':''}`).join('; ')}. Evite progressão nesse padrão esta semana e priorize variação sem dor.`
    :'Sem dores relatadas nos registros da semana.';
  return{
    dores,itens:dores,resumo,regioes,nivel,temDor:dores.some(d=>d.regioes.length||d.naoPorDor||d.parcialPorDor),parcialOuNao,pesado,tecnicaRuim,treinosConcluidos:registros.length,treinosDetalhados,treinosSimples,poucosDadosExecucao:registros.length>0&&treinosDetalhados<2,
    resumoDores:dores.length?`Foram encontradas dores nos registros de treino: ${fraseListaHumana(regioes.length?regioes:dores.map(d=>d.exercicio))}.`:''
  };
}
function agregarDoresRegistrosSemana(estado=ST){return coletarSinaisSemana(null,estado);}
function agregarSinaisRegistrosDaSemana(sem){return coletarSinaisSemana(sem,ST);}
function resumoRecuperacaoSemana(semana){
  const registros=Object.values(semana?.registros||{}).filter(r=>r?.tipo==='descanso');
  const atividades=registros.map(r=>String(r.descansoTipo||'descanso total').trim()).filter(Boolean);
  const atividadesLeves=atividades.filter(v=>/caminhada leve|mobilidade|alongamento|bike leve/i.test(v));
  const duracaoTotal=registros.reduce((s,r)=>s+(+r.duracaoMin||0),0);
  const sensacoes=registros.map(r=>r.sensacao).filter(Boolean);
  const observacoes=registros.map(r=>String(r.obs||'').trim()).filter(Boolean);
  const cargaComplementar=resumoCargaAtividadesSemanaCalifit(semana);
  const observacoesAtividades=cargaComplementar.atividades.map(a=>String(a.obs||'').trim()).filter(Boolean);
  const dores=[...observacoes,...observacoesAtividades].map(o=>analisarDorTexto(o)).filter(d=>d.temDor);
  const regioes=[...new Set(dores.flatMap(d=>d.regioes||[]))];
  const nivel=dores.some(d=>d.nivel==='forte')?'forte':dores.some(d=>d.nivel==='moderada')?'moderada':dores.length?'leve':'nenhuma';
  let sensacao=sensacoes.includes('ruim')?'ruim':sensacoes.includes('media')?'media':sensacoes.includes('boa')?'boa':'';
  if(cargaComplementar.recuperacaoRuim) sensacao='ruim';
  else if(cargaComplementar.recuperacaoMedia&&sensacao!=='ruim') sensacao='media';
  let texto='';
  if(registros.length){
    const atividade=fraseListaHumana([...new Set(atividadesLeves.length?atividadesLeves:atividades)]);
    texto=`Recuperação ativa registrada${atividade?`: ${atividade}`:''}${duracaoTotal?`, ${duracaoTotal} min`:''}${sensacao?`, sensação ${qualidadeLabel(sensacao)}`:''}.`;
  }
  if(cargaComplementar.texto) texto=[texto,cargaComplementar.texto].filter(Boolean).join(' ');
  if(dores.length) texto=`Recuperação/atividade registrada com dor ${formatarRegioesDor(regioes)}. Progressões sensíveis foram suspensas.`;
  return{
    quantidade:registros.length,
    atividadesLeves:[...new Set(atividadesLeves)],
    duracaoTotal,
    sensacao,
    observacoes:[...observacoes,...observacoesAtividades],
    temDor:dores.length>0,
    regioes,
    nivel,
    cargaComplementarAlta:cargaComplementar.cargaAlta,
    atividadesComplementares:cargaComplementar.atividades,
    sinalPositivo:registros.length>0&&!dores.length&&sensacao==='boa'&&duracaoTotal<=40&&!cargaComplementar.cargaAlta,
    bloqueiaAumento:dores.length>0||sensacao==='ruim'||cargaComplementar.cargaAlta,
    texto
  };
}
function podeAumentarVolumeSemana({dorInfo={},sinaisSemana={},recuperacaoDescanso={},checkin={},treinosDetalhados=0}={}){
  const r=checkin?.respostas||checkin||{};
  if(dorInfo.temDor||sinaisSemana.temDor||recuperacaoDescanso.temDor) return{permitido:false,motivo:'dor registrada na semana'};
  if(r.recuperacao==='ruim'||r.sonoEnergia==='ruim'||recuperacaoDescanso.sensacao==='ruim') return{permitido:false,motivo:'recuperação, sono ou energia ruins'};
  if(recuperacaoDescanso.cargaComplementarAlta) return{permitido:false,motivo:'carga complementar alta já realizada na semana'};
  if(r.recuperacao!=='boa'||r.sonoEnergia!=='boa') return{permitido:false,motivo:'recuperação e sono/energia não foram confirmados como bons'};
  if(sinaisSemana.tecnicaRuim||sinaisSemana.pesado) return{permitido:false,motivo:'técnica ruim ou esforço alto registrado'};
  if(sinaisSemana.parcialOuNao) return{permitido:false,motivo:'execução Parcial ou Não fiz registrada'};
  if(treinosDetalhados<1) return{permitido:false,motivo:'dados detalhados insuficientes'};
  const facil=valorVazioUsuario(r.exercicioFacil)?'':String(r.exercicioFacil||'').trim();
  const boaTolerancia=!!facil||(sinaisSemana.treinosDetalhados>=2&&!sinaisSemana.pesado&&!sinaisSemana.tecnicaRuim);
  if(!boaTolerancia) return{permitido:false,motivo:'sem evidência concreta de boa tolerância'};
  return{permitido:true,motivo:'boa tolerância registrada sem sinais de segurança ou recuperação'};
}
function decisaoAjusteVolumeSemana({dorInfo={},sinaisSemana={},recuperacaoDescanso={},checkin={},treinosDetalhados=0}={}){
  const r=checkin?.respostas||checkin||{};
  if(dorInfo.temDor||sinaisSemana.temDor||recuperacaoDescanso.temDor) return{acao:'reduzir',permitido:true,motivo:'dor ou sinal de segurança registrado',seguranca:true};
  if(sinaisSemana.parcialOuNao||sinaisSemana.pesado||sinaisSemana.tecnicaRuim) return{acao:'reduzir',permitido:true,motivo:'execução parcial, esforço alto ou técnica ruim',seguranca:true};
  if(r.recuperacao==='ruim'||r.sonoEnergia==='ruim'||recuperacaoDescanso.sensacao==='ruim') return{acao:'reduzir',permitido:true,motivo:'recuperação, sono ou energia ruins',seguranca:true};
  if(r.preferencia==='reduzir') return{acao:'reduzir',permitido:true,motivo:'preferência do usuário por reduzir volume',seguranca:false};
  if(recuperacaoDescanso.cargaComplementarAlta) return{acao:'manter',permitido:true,motivo:'carga complementar alta já realizada na semana',seguranca:false};
  if(r.preferencia==='aumentar'){
    const aumento=podeAumentarVolumeSemana({dorInfo,sinaisSemana,recuperacaoDescanso,checkin,treinosDetalhados});
    return{acao:aumento.permitido?'aumentar':'manter',permitido:aumento.permitido,motivo:aumento.motivo,seguranca:false};
  }
  if(treinosDetalhados<1) return{acao:'manter',permitido:true,motivo:'dados detalhados insuficientes',seguranca:false};
  return{acao:'manter',permitido:true,motivo:'sem indicação segura para alterar volume',seguranca:false};
}
function podeProgredirCarga(exercicio,historicoExecucoes=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return{permitido:false,motivo:'resistência qualitativa, sem progressão numérica de carga'};
  const nome=nomeTecnicoExercicio(exercicio)||'Exercício';
  const ultimos=(historicoExecucoes||[]).filter(h=>cargaRegistradaExercicio(exercicio,h?.log||h)).slice(-2);
  if(ultimos.length<2) return{permitido:false,motivo:'são necessários dois registros detalhados com carga usada'};
  const cargas=ultimos.map(item=>cargaRegistradaExercicio(exercicio,item?.log||item));
  if(Math.abs(cargas[0]-cargas[1])>=0.001) return{permitido:false,atual:cargas[1],motivo:'a carga atual ainda não foi consolidada em dois registros consecutivos'};
  for(const item of ultimos){
    const log=item?.log||item;
    if(temDorLog(log)) return{permitido:false,motivo:'dor registrada'};
    if(tecnicaRuimLog(log)||normTxt(log.tecnica)!=='boa') return{permitido:false,motivo:'técnica não confirmada como boa'};
    if(log.feito!=='sim'||!completouMeta(exercicio,log)) return{permitido:false,motivo:'execução incompleta'};
    const rpe=rpeLog(log);
    if(!rpe||rpe<6||rpe>8) return{permitido:false,motivo:'RPE ausente ou fora da faixa de 6 a 8'};
  }
  const atual=cargas[1];
  const proxima=proximaCargaRealDisponivel(nome,atual,ST.perfil);
  return proxima?{permitido:true,atual,proxima}:{permitido:false,atual,motivo:'não há próxima carga realmente configurável'};
}
function aumentarRepeticoesPrescricao(valor,delta=1){
  const txt=String(valor||'').trim();
  if(!txt||/min|seg|\bs\b/i.test(txt)) return '';
  const m=txt.match(/^(\d+)\s*[–-]\s*(\d+)(.*)$/);
  if(m) return `${+m[1]+delta}–${+m[2]+delta}${m[3]||''}`;
  const n=txt.match(/^(\d+)(.*)$/);
  return n?`${+n[1]+delta}${n[2]||''}`:'';
}
function aumentarTempoPrescricao(valor,delta=5){
  const txt=String(valor||'').trim();
  const m=txt.match(/^(\d+)\s*s(.*)$/i);
  if(m) return `${+m[1]+delta}s${m[2]||''}`;
  return '';
}
function progressaoDeterministicaUnica(ex,contexto={}){
  const atual={...ex};
  const meta=metaExercicio(ex)||{};
  const nome=nomeTecnicoExercicio(ex)||ex?.n||'Exercício';
  const prescAntes=`${ex.s}x${ex.r}`;
  const tempo=aumentarTempoPrescricao(ex.r,5);
  if(tempo){
    const novo={...atual,r:tempo,nota:[atual.nota,'progressão de tempo/isometria em uma única variável'].filter(Boolean).join(' · ')};
    return{ex:novo,variavel:'tempo',antes:prescAntes,depois:`${novo.s}x${novo.r}`,descricao:'tempo de sustentação ampliado de forma conservadora'};
  }
  const tecnicaPossivel=!exercicioUsaCargaNumerica(ex)&&(meta.agressividade!=='alta')&&(ex.p||EXD[nome]?.prog)&&!/descida controlada 3s|pausa tecnica 1s|pausa técnica 1s/i.test(atual.nota||'');
  if(tecnicaPossivel){
    const orientacao=/remada|flex|agach|avan|step|barra/i.test(normTxt(nome))?'descida controlada de 3s':'pausa técnica de 1s no ponto de maior controle';
    const novo={...atual,nota:[atual.nota,`progressão técnica: ${orientacao}`].filter(Boolean).join(' · '),progressaoAplicada:'tecnica'};
    return{ex:novo,variavel:'técnica',antes:'Execução atual',depois:orientacao,descricao:'controle técnico ampliado antes de aumentar volume ou dificuldade'};
  }
  if((+ex.ds||0)>=75&&(+ex.ds||0)<=120){
    const novo={...atual,ds:Math.max(60,(+ex.ds||0)-10),nota:[atual.nota,'progressão de densidade: descanso reduzido em 10s'].filter(Boolean).join(' · ')};
    return{ex:novo,variavel:'descanso',antes:`${ex.ds}s de descanso`,depois:`${novo.ds}s de descanso`,descricao:'densidade ampliada sem alterar exercício, séries ou repetições'};
  }
  const reps=aumentarRepeticoesPrescricao(ex.r,1);
  if(reps){
    const novo={...atual,r:reps,nota:[atual.nota,'progressão leve de repetições, sem buscar falha'].filter(Boolean).join(' · ')};
    return{ex:novo,variavel:'repetições',antes:prescAntes,depois:`${novo.s}x${novo.r}`,descricao:'repetições ampliadas em uma única variável'};
  }
  const cap={init:3,inter:4,avanc:5}[contexto.nivel||ST.perfil?.nivel||'init']||4;
  if((+ex.s||1)<cap){
    const novo={...atual,s:(+ex.s||1)+1,nota:[atual.nota,'progressão leve de séries, sem buscar falha'].filter(Boolean).join(' · ')};
    return{ex:novo,variavel:'séries',antes:prescAntes,depois:`${novo.s}x${novo.r}`,descricao:'uma série acrescentada sem alterar as demais variáveis'};
  }
  return{ex:{...atual,nota:[atual.nota,'manter prescrição e consolidar técnica antes do próximo degrau'].filter(Boolean).join(' · ')},variavel:'manter',antes:prescAntes,depois:prescAntes,descricao:'prescrição mantida para consolidar execução'};
}

function avaliarProgressao(exercicio,historicoExecucoes,perfil){
  const nomeExibido=exercicio?.n||exercicio?.nome||'Exercício';
  const nome=nomeTecnicoExercicio(exercicio)||nomeExibido;
  const hist=(historicoExecucoes||[]).slice(-3);
  const retornoInicial=estrategiaRetornoGradual(perfil,avaliarProntidaoInicial(perfil||{}));
  const evitar=(perfil?.exerciciosEvitar||[]).map(normTxt);
  const cirurgia=normalizarSaudePerfil(perfil||{}).cirurgia;
  if(cirurgiaTemLimitacaoAtiva(perfil||{})&&cirurgia.liberacao==='nao_liberado'){
    return{status:'manter',motivo:'Não liberado para treino.',sugestao:'Não realizar progressão. Siga a orientação da equipe profissional.'};
  }
  if(cirurgiaTemLimitacaoAtiva(perfil||{})&&cirurgia.liberacao!=='total'&&(exercicioRelacionadoCirurgia(exercicio,cirurgia.regiao)||exercicioBloqueadoPorTextoCirurgia(exercicio,perfil))){
    return{status:'manter',motivo:'Limitação cirúrgica ativa relacionada a este padrão.',sugestao:'Não progredir enquanto a limitação estiver ativa; respeite as restrições e a orientação profissional.'};
  }
  if(evitar.some(e=>e&&(normTxt(nome).includes(e)||normTxt(nomeExibido).includes(e)))) return{status:'trocar',motivo:'Exercício está na lista de exercícios a evitar.',sugestao:'Trocar por uma variação segura do mesmo padrão de movimento.'};
  const flagsPerfil=flagsSegurancaPerfil(perfil||{});
  const regioesSensíveis=[];
  if(flagsPerfil.dorPe||flagsPerfil.fascitePlantar) regioesSensíveis.push('pe');
  if(flagsPerfil.dorTornozelo) regioesSensíveis.push('tornozelo');
  if(regioesSensíveis.length&&exercicioRelacionadoRegioes(nome,regioesSensíveis)){
    return{status:'manter',motivo:'Há dor no pé, fascite plantar ou dor no tornozelo associada a este padrão.',sugestao:`Não progredir ${nomeExibido} enquanto houver dor. Use baixo impacto, amplitude confortável ou uma variação sem dor.`};
  }
  const logs=hist.map(h=>h.log||h);
  const dores=logs.map(analisarDorRegistro).filter(d=>d.temDor);
  const dorMaisRecente=logs.length?analisarDorRegistro(logs[logs.length-1]):{temDor:false};
  const dorObs=logs.map(dorObservadaLog).find(Boolean);
  const dor=dorMaisRecente.temDor||dores.length>=1;
  const dorRec=logs.filter(temDorLog).length>=2;
  const tecnicaRuim=logs.some(tecnicaRuimLog);
  const rpes=logs.map(rpeLog).filter(Boolean);
  const rpeMax=rpes.length?Math.max(...rpes):0;
  const rpeMed=rpes.length?rpes.reduce((a,b)=>a+b,0)/rpes.length:0;
  const completos=logs.filter(l=>completouMeta(exercicio,l)).length;
  const falhas=logs.filter(l=>l.feito==='nao'||l.feito==='parcial'||!completouMeta(exercicio,l)).length;
  const obsTxt=normTxt(logs.map(l=>[l.obs,l.observacoes,l.continuar].filter(Boolean).join(' ')).join(' '));
  const diffs=logs.map(regraDificuldadeLog).filter(Boolean);
  const diffMuito=diffs.some(d=>d.acao==='reduzir_ou_regredir');
  const diffPesado=diffs.some(d=>d.acao==='manter');
  const dorModerada=dores.some(d=>d.nivel==='moderada');
  const contradicao=comentarioContraditorioPadrao(nome,logs);
  const naoComDor=logs.some(l=>l?.feito==='nao'&&temDorLog(l));
  const parcialComDor=logs.some(l=>l?.feito==='parcial'&&temDorLog(l));
  const naoFez=logs.some(l=>l?.feito==='nao');
  const parcial=logs.some(l=>l?.feito==='parcial');
  const acimaPlanejado=logs.some(l=>l?.acimaPlanejado?.acima||registroAcimaDoPlanejado(exercicio,l).acima);
  const retornoConsolidado=logs.filter(l=>l?.feito==='sim'&&completouMeta(exercicio,l)&&!temDorLog(l)&&!tecnicaRuimLog(l)&&rpeLog(l)&&rpeLog(l)<=8).length>=2;
  if(retornoInicial.ativa&&!retornoConsolidado){
    return{status:'manter',motivo:`Retorno gradual ainda em consolidação (${retornoInicial.motivos.join(', ')}).`,sugestao:`Manter ${nomeExibido} com técnica controlada. Progredir somente após duas sessões completas, sem dor, técnica boa e ${rotuloRpeUsuario()} até 8.`};
  }
  if(dores.some(d=>d.alertaProfissional)) return{status:'trocar',motivo:'Foi relatada dor forte/aguda, irradiada ou piorando neste exercício.',sugestao:'Interromper a progressão deste padrão e buscar avaliação profissional antes de insistir.'};
  if(naoComDor) return{status:'regredir',motivo:'Exercício não realizado por dor.',sugestao:sugestaoNaoFezPorDor(nomeExibido,dorObs,false)};
  if(parcialComDor) return{status:'reduzir_volume',motivo:'Execução parcial com dor.',sugestao:sugestaoNaoFezPorDor(nomeExibido,dorObs,true)};
  if(dorModerada) return{status:'regredir',motivo:'Houve dor moderada associada ao exercício.',sugestao:`Reduzir volume, reduzir amplitude ou usar uma variação sem dor de ${nomeExibido}. Não progredir enquanto houver dor.`};
  if(dorRec) return{status:'regredir',motivo:'Dor leve recorrente registrada.',sugestao:`Usar uma variação mais fácil de ${nomeExibido} ou reduzir amplitude/volume até executar sem dor.`};
  if(dorObs||dorMaisRecente.temDor) return{status:'manter',motivo:'Dor leve ou incômodo registrado neste exercício.',sugestao:sugestaoDorLeveExercicio(nomeExibido,dorObs)};
  if(naoFez) return{status:'reduzir_volume',motivo:'Exercício marcado como Não fiz.',sugestao:`Não progredir ${nomeExibido}. Repita com menor volume ou use uma variação mais fácil.`};
  if(parcial) return{status:'reduzir_volume',motivo:'Exercício realizado parcialmente.',sugestao:`Não progredir ${nomeExibido}. Reduza uma série ou repita a prescrição até completar.`};
  if(tecnicaRuim) return{status:'regredir',motivo:'Técnica ruim registrada.',sugestao:`Regredir ${nomeExibido}, reduzir amplitude ou manter uma variação mais fácil até consolidar a execução.`};
  if(diffMuito||rpeMax>=10) return{status:'reduzir_volume',motivo:'Esforço muito pesado registrado.',sugestao:'Reduzir 10–20% do volume ou regredir a variação na próxima sessão.'};
  if(diffPesado||rpeMax>=9) return{status:'reduzir_volume',motivo:'Esforço pesado registrado.',sugestao:`Não aumente ${nomeExibido}. Reduza apenas uma variável na próxima sessão — de preferência uma série — e mantenha carga, repetições e variação até o esforço ficar controlado.`};
  if(falhas>=1) return{status:'reduzir_volume',motivo:'Meta incompleta registrada.',sugestao:`Não progredir ${nomeExibido}; reduza uma série ou repita a prescrição até completar.`};
  if(contradicao) return{status:'revisar',motivo:`O comentário menciona ${fraseListaHumana(contradicao.padroesCitados)}, mas o exercício registrado foi ${nomeExibido} (${contradicao.padraoReal}).`,sugestao:'Como são padrões diferentes, revise manualmente antes de alterar a progressão.'};
  if(logs.length&&!logs.some(logTemDadosDetalhados)) return{status:'manter',motivo:'Poucos dados de execução para aumento automático.',sugestao:`Registre séries, repetições, ${rotuloRpeUsuario()}, técnica e dor antes de progredir este exercício.`};
  if(hist.length<2) return{status:'manter',motivo:'Histórico insuficiente para progredir com segurança.',sugestao:`Manter ${nomeExibido} com a prescrição atual e registrar mais 1 ou 2 sessões.`};
  if(acimaPlanejado&&(perfilTemCautelaParaReserva(perfil)||!rpes.length)){
    return{status:'manter',motivo:'Registro acima do planejado tratado com cautela.',sugestao:`Manter ${nomeExibido} com a prescrição atual. O app considera como boa tolerância, mas não recomenda buscar falha nem transformar o excesso em nova meta automática.`};
  }
  if(completos>=2&&rpes.length>=2&&rpeMax<=8&&!dor&&!tecnicaRuim) return{status:'progredir',motivo:'Meta concluída em sessões seguidas com esforço explicitamente registrado, controlado e sem dor.',sugestao:`Progredir levemente ${nomeExibido}, mudando apenas uma variável: +1–2 repetições, +1 série leve, menor descanso, mais amplitude, alavanca um pouco mais difícil, mais tempo/isometria ou pequena carga externa.`};
  if(completos>=1&&(!rpeMed||rpeMed<=8)&&!dor) return{status:'manter',motivo:'Exercício concluído, mas ainda sem base suficiente para aumento automático.',sugestao:`Manter ${nomeExibido} com a prescrição atual e confirmar mais uma sessão sem dor.`};
  return{status:'manter',motivo:'Dados ainda não indicam progressão ou regressão clara.',sugestao:`Manter ${nomeExibido} e registrar a próxima sessão com status, dificuldade, dor e técnica.`};
}

function lEx(n,k,v){
  if(!ST.exec[n]) ST.exec[n]={};
  if(k==='diff') ST.exec[n]=sincronizarDificuldadeRpe({...ST.exec[n],diff:v},'diff');
  else if(k==='rpe') ST.exec[n]=sincronizarDificuldadeRpe({...ST.exec[n],rpe:v},'rpe');
  else ST.exec[n][k]=v;
  salvar();
}

function prescricaoEx(ex){return `${ex?.s||''}x${ex?.r||''}`.replace(/^x|x$/g,'')||'';}
