// 164L — Biblioteca e Skill Tree carregadas somente quando necessárias.
let _moduloExplorarPromiseCalifit=null;

function carregarScriptLocalCalifit(src,id){
  const existente=document.getElementById(id);
  if(existente){
    if(existente.dataset.pronto==='1') return Promise.resolve(existente);
    return new Promise((resolve,reject)=>{
      existente.addEventListener('load',()=>resolve(existente),{once:true});
      existente.addEventListener('error',reject,{once:true});
    });
  }
  return new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.id=id;
    script.src=src;
    script.async=true;
    script.addEventListener('load',()=>{
      script.dataset.pronto='1';
      resolve(script);
    },{once:true});
    script.addEventListener('error',()=>reject(new Error(`Falha ao carregar ${src}`)),{once:true});
    document.body.appendChild(script);
  });
}

function carregarModuloExplorarCalifit(){
  if(window.__CALIFIT_EXPLORE_MODULE__) return Promise.resolve(window.__CALIFIT_EXPLORE_MODULE__);
  if(_moduloExplorarPromiseCalifit) return _moduloExplorarPromiseCalifit;
  _moduloExplorarPromiseCalifit=carregarScriptLocalCalifit('./califit-explore.js','califit-explore-module')
    .then(()=>{
      if(!window.__CALIFIT_EXPLORE_MODULE__) throw new Error('Módulo Explorar não inicializado.');
      return window.__CALIFIT_EXPLORE_MODULE__;
    })
    .catch(erro=>{
      _moduloExplorarPromiseCalifit=null;
      console.error('Falha ao carregar Biblioteca/Skill Tree',erro);
      showToast('Não foi possível abrir Biblioteca ou Skill Tree agora.',4200);
      throw erro;
    });
  return _moduloExplorarPromiseCalifit;
}

function chamarExplorarSincronoCalifit(nome,args=[]){
  const fn=window.__CALIFIT_EXPLORE_MODULE__?.[nome];
  if(typeof fn!=='function') throw new Error(`Módulo Explorar ainda não carregado: ${nome}`);
  return fn(...args);
}

