function listarSkillTreeCalifit(...args){return chamarExplorarSincronoCalifit('listarSkillTreeCalifit',args);}
function detalheSkillTreeNoCalifit(...args){return chamarExplorarSincronoCalifit('detalheSkillTreeNoCalifit',args);}
