async function abrirBibliotecaExercicios(...args){
  const modulo=await carregarModuloExplorarCalifit();
  return modulo.abrirBibliotecaExercicios(...args);
}
async function abrirDetalheSkillTreeCalifit(...args){
  const modulo=await carregarModuloExplorarCalifit();
  return modulo.abrirDetalheSkillTreeCalifit(...args);
}
async function abrirSkillTreeCalifit(...args){
  const modulo=await carregarModuloExplorarCalifit();
  return modulo.abrirSkillTreeCalifit(...args);
}
function responderSkillTreeTreinadorCalifit(...args){
  const fn=window.__CALIFIT_EXPLORE_MODULE__?.responderSkillTreeTreinadorCalifit;
  if(typeof fn==='function') return fn(...args);
  carregarModuloExplorarCalifit().catch(()=>{});
  return 'A Skill Tree está sendo preparada. Tente novamente em alguns instantes; seu plano não será alterado.';
}

