function auditarIntegridadeLocalCalifit(estado=ST){
  const st=estado&&typeof estado==='object'?estado:{};
  const semanas=arr(st.semanas);
  const ids=semanas.map(s=>String(s?.id||'')).filter(Boolean);
  const idsDuplicados=ids.filter((id,i)=>ids.indexOf(id)!==i);
  const abertas=semanas.filter(s=>s?.aberta&&!s?.fechada);
  const checkinsOrfaos=arr(st.checkins).filter(c=>{
    if(!c?.semanaId) return false;
    return !semanas.some(s=>String(s?.id)===String(c.semanaId));
  });
  const cobertura=validarCoberturaMetadadosExercicios();
  const backupEstrutural=backupValido(st);
  const problemas=[];
  if(idsDuplicados.length) problemas.push(`${idsDuplicados.length} identificador(es) de semana duplicado(s)`);
  if(abertas.length>1) problemas.push(`${abertas.length} semanas abertas ao mesmo tempo`);
  if(checkinsOrfaos.length) problemas.push(`${checkinsOrfaos.length} check-in(s) sem semana correspondente`);
  if(!cobertura.ok) problemas.push(`${cobertura.faltantes.length} exercício(s) sem metadados`);
  if(!backupEstrutural) problemas.push('estado atual não passou na validação estrutural de backup');
  return{
    ok:problemas.length===0,
    problemas,
    semanas:semanas.length,
    semanasAbertas:abertas.length,
    checkins:arr(st.checkins).length,
    checkinsOrfaos:checkinsOrfaos.length,
    cobertura,
    backupEstrutural,
    usoBytes:estimarUsoLocalStorage(),
    statusBackup:statusBackupLocalCalifit(),
    rotacao:resumoRotacaoSemanasCalifit(st)
  };
}
function formatarBytesCalifit(bytes){
  const n=Math.max(0,+bytes||0);
  if(n<1024) return `${n} B`;
  if(n<1024*1024) return `${(n/1024).toFixed(1)} KB`;
  return `${(n/1024/1024).toFixed(2)} MB`;
}
function abrirDiagnosticoLocalCalifit(){
  const a=auditarIntegridadeLocalCalifit();
  const status=a.ok?'Tudo certo':'Revisão necessária';
  const classe=a.ok?'ig':'io';
  const faltantes=a.cobertura.faltantes.slice(0,8);
  const ultimo=a.statusBackup.ultimoBackupEm?new Date(a.statusBackup.ultimoBackupEm).toLocaleString('pt-BR'):'ainda não registrado';
  const ultimaRotacao=a.rotacao.ultimaRotacaoSemanasEm?new Date(a.rotacao.ultimaRotacaoSemanasEm).toLocaleString('pt-BR'):'ainda não necessária';
  mOpen('m2',`<div id="diagnostico-local-califit">
    <div class="mt2">${tituloIcone('seguranca','Diagnóstico local')}</div>
    <div class="ms">Verificação somente neste dispositivo. Nenhum dado é enviado.</div>
    <div class="info ${classe}"><strong>${escHtml(status)}</strong><br>${a.ok?'Estado, semanas, check-ins, metadados e backup estão consistentes.':escHtml(a.problemas.join(' · '))}</div>
    <div class="trainer-grid" style="margin-bottom:12px">
      <div class="trainer-stat"><span>Semanas</span><strong>${a.semanas}</strong></div>
      <div class="trainer-stat"><span>Check-ins</span><strong>${a.checkins}</strong></div>
      <div class="trainer-stat"><span>Metadados</span><strong>${a.cobertura.total-a.cobertura.faltantes.length}/${a.cobertura.total}</strong></div>
      <div class="trainer-stat"><span>Armazenamento</span><strong>${escHtml(formatarBytesCalifit(a.usoBytes))}</strong></div>
      <div class="trainer-stat"><span>Arquivadas</span><strong>${a.rotacao.arquivadas}</strong></div>
    </div>
    <div class="info ib"><strong>Backup</strong><br>Último registro: ${escHtml(ultimo)}.<br>Frequência configurada: ${a.statusBackup.frequenciaDias} dias.</div>
    <div class="info ig"><strong>Rotação automática</strong><br>Mantém as ${a.rotacao.limitePadrao} semanas fechadas mais recentes completas e compacta as anteriores sem apagar treinos, atividades ou check-ins.<br>Última rotação: ${escHtml(ultimaRotacao)}${a.rotacao.bytesLiberadosRotacao?` · ${escHtml(formatarBytesCalifit(a.rotacao.bytesLiberadosRotacao))} liberados ao todo`:''}.</div>
    ${faltantes.length?`<div class="info io"><strong>Exercícios sem metadados:</strong><br>${escHtml(faltantes.join(', '))}${a.cobertura.faltantes.length>faltantes.length?'…':''}</div>`:''}
    <button class="btn btn-s" id="diagnostico-arquivar" type="button">Arquivar semanas antigas agora</button>
    <button class="btn btn-s" id="diagnostico-fechar" type="button">Fechar</button>
  </div>`);
  $('diagnostico-arquivar')?.addEventListener('click',()=>{
    const r=rotacionarSemanasAntigasCalifit({estado:ST,forcar:true});
    salvar();
    if(r.arquivadas) showToast(`${r.arquivadas} semana${r.arquivadas===1?' antiga foi arquivada':'s antigas foram arquivadas'} sem apagar registros.`);
    else showToast('Nenhuma semana antiga precisa ser arquivada agora.');
    mClose('m2');
  });
  $('diagnostico-fechar')?.addEventListener('click',()=>mClose('m2'));
}

function nomeArquivoBackup(){
  const d=new Date();
  const p=n=>String(n).padStart(2,'0');
  return `califit-backup-${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}.json`;
}

function exportarDados(){
  try{
    const prefs=obterPreferenciasLembretesCalifit();
    prefs.ultimoBackupEm=new Date().toISOString();
    ST.lembretes=normalizarPreferenciasLembretesCalifit(prefs);
    salvar();
    const blob=new Blob([JSON.stringify(ST,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;a.download=nomeArquivoBackup();
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
    rHoje();
    showToast('Backup exportado e lembrete atualizado.');
  }catch(e){
    showToast('Não foi possível exportar os dados.');
  }
}

function campoNumeroBackupValido(valor,validador){
  if(valor==null||valor===''||Number(valor)===0) return true;
  return !!validador(valor,{opcional:true}).valido;
}
function marcasBackupValidas(marcas){
  if(marcas==null) return true;
  if(typeof marcas!=='object'||Array.isArray(marcas)) return false;
  return Object.values(marcas).every(v=>v==null||v===''||(Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100000));
}
function backupValido(dados){
  if(!(dados&&typeof dados==='object'&&!Array.isArray(dados))) return false;
  const p=dados.perfil;
  if(!(p&&typeof p==='object'&&!Array.isArray(p))) return false;
  if(!Object.prototype.hasOwnProperty.call(dados,'done')||typeof dados.done!=='boolean') return false;
  if(('semanas' in dados)&&!Array.isArray(dados.semanas)) return false;
  if(('checkins' in dados)&&!Array.isArray(dados.checkins)) return false;
  if(('bio' in dados)&&!Array.isArray(dados.bio)) return false;
  if(('pesoDiario' in dados)&&!Array.isArray(dados.pesoDiario)) return false;
  const numeros=[
    [p.idade,validarIdade],[p.peso,validarPesoKg],[p.altura,validarAlturaCm],
    [p.gordura,validarGorduraCorporal],[p.massaMuscular,validarMassaMuscular],
    [p.metaPeso,validarPesoKg],[p.metaGordura,validarGorduraCorporal]
  ];
  if(numeros.some(([v,fn])=>!campoNumeroBackupValido(v,fn))) return false;
  if(!marcasBackupValidas(p.marcas)) return false;
  if(arr(dados.pesoDiario).some(r=>!r||typeof r!=='object'||Array.isArray(r)||!campoNumeroBackupValido(r.peso,validarPesoKg))) return false;
  if(arr(dados.bio).some(r=>{
    if(!r||typeof r!=='object'||Array.isArray(r)) return true;
    return !campoNumeroBackupValido(r.peso,validarPesoKg)||
      !campoNumeroBackupValido(r.gordura,validarGorduraCorporal)||
      !campoNumeroBackupValido(r.massaMuscular,validarMassaMuscular)||
      !campoNumeroBackupValido(r.aguaCorp,validarAguaCorporal)||
      !campoNumeroBackupValido(r.gordVisceral,validarGorduraVisceral)||
      !campoNumeroBackupValido(r.tmb,validarTmb);
  })) return false;
  return true;
}

function aplicarBackupImportado(dados,mensagem='Dados importados com sucesso.'){
  ST=migrarEstadoSalvo(dados);
  salvar();
  load();
  salvar();
  if(ST.done){$('ob')?.classList.add('gone');updHdr();rHoje();rSemana();rCorpo();rTreinador();}
  showToast(mensagem);
}
function importarArquivoBackup(input,{confirmar=true,mensagem='Dados importados com sucesso.'}={}){
  if(_acoesCriticas.has('importar-backup')){showToast('Importação já em andamento.');return;}
  const file=input?.files?.[0];
  if(!file) return;
  _acoesCriticas.add('importar-backup');
  const liberar=()=>_acoesCriticas.delete('importar-backup');
  const reader=new FileReader();
  reader.onload=()=>{
    let dados=null;
    try{dados=JSON.parse(reader.result);}catch(err){}
    if(!backupValido(dados)){
      showToast('Arquivo de backup inválido.');
      input.value='';
      liberar();
      return;
    }
    const aplicar=()=>{try{aplicarBackupImportado(dados,mensagem);}finally{liberar();}};
    if(confirmar) showConfirm('Importar dados','Isso substituirá os dados atuais do app. Deseja continuar?',aplicar,'Importar',{onCancel:liberar});
    else aplicar();
    input.value='';
  };
  reader.onerror=()=>{showToast('Arquivo de backup inválido.');input.value='';liberar();};
  reader.readAsText(file,'UTF-8');
}
function importarDadosSelecionados(e){
  const input=e.target;
  importarArquivoBackup(input);
}

