// 163P1.2 — normalização central de linguagem informal do Assistente.
// O texto original continua no chat; somente uma cópia é expandida para classificação e comandos.
function normalizarLinguagemInformalAssistenteCalifit(texto=''){
  const original=String(texto||'');
  let normalizado=normTxt(original).replace(/[’']/g,"'").replace(/\s+/g,' ').trim();
  const mapa=[
    ['vcs','voces'],['vc','voce'],['mto','muito'],['mt','muito'],['tbm','tambem'],['tmb','tambem'],['tb','tambem'],
    ['hj','hoje'],['qdo','quando'],['qnd','quando'],['dps','depois'],['agr','agora'],['pq','por que'],
    ['oq','o que'],['ql','qual'],['q','que'],['cm','como'],['td','tudo'],
    ['pfv','por favor'],['pls','por favor'],['cmg','comigo'],['vlw','valeu'],['blz','beleza'],
    ['naum','nao'],['nn','nao'],['n','nao'],['to','estou'],['ta','esta'],['tava','estava']
  ];
  const expansoes=[];
  mapa.forEach(([abreviacao,expansao])=>{
    const rx=new RegExp(`\\b${abreviacao}\\b`,'g');
    if(rx.test(normalizado)){
      normalizado=normalizado.replace(rx,expansao);
      expansoes.push({abreviacao,expansao});
    }
  });
  normalizado=normalizado.replace(/\s+/g,' ').trim();
  return{original,normalizado,expansoes};
}

// 163P1.3.3 — PRECISÃO CONVERSACIONAL DO ASSISTENTE
function confirmacaoInformalPuraAssistenteCalifit(texto=''){
  let msg=normalizarLinguagemInformalAssistenteCalifit(texto).normalizado
    .replace(/\bmuito\s+obrigad([oa])\b/g,'obrigad$1')
    .replace(/[!?.;,:\-]+/g,' ')
    .replace(/\s+/g,' ')
    .trim();
  if(!msg) return false;
  const palavras=msg.split(' ');
  const conectores=new Set(['e','entao','sim']);
  const confirmacoes=new Set(['ok','okay','beleza','show','perfeito','entendi','certo','valeu','obrigado','obrigada','combinado','fechado']);
  const conteudo=palavras.filter(p=>!conectores.has(p));
  return conteudo.length>0&&palavras.every(p=>conectores.has(p)||confirmacoes.has(p))&&conteudo.every(p=>confirmacoes.has(p));
}
function detectarMudancaNivelExperienciaAssistenteCalifit(texto=''){
  const msg=normalizarLinguagemInformalAssistenteCalifit(texto).normalizado;
  const nivelExercicio=/\b(nivel|dificuldade)\b.{0,18}\b(do|desse|deste|no|nesse|neste)?\s*(exercicio|movimento|variacao)\b|\b(exercicio|movimento|variacao)\b.{0,18}\b(nivel|dificuldade)\b/.test(msg);
  if(nivelExercicio) return{detectado:false,direcao:'',nivelExercicio:true};
  const detectado=/\b(trocar|mudar|alterar|subir|descer|baixar|avancar|evoluir)\b.{0,35}\b(nivel|iniciante|intermediario|avancado)\b|\b(nivel|iniciante|intermediario|avancado)\b.{0,35}\b(correto|certa|adequado|mudar|trocar|subir|descer|baixar|agora)\b|\b(sou|virei|estou)\b.{0,18}\b(iniciante|intermediario|avancado)\b|\bqual\b.{0,18}\bmeu nivel\b/.test(msg);
  const direcao=/\b(descer|baixar|voltar)\b|\bvirar iniciante\b/.test(msg)?'descer':/\b(subir|avancar|evoluir)\b|\b(virar|sou|estou)\b.{0,12}\b(intermediario|avancado)\b/.test(msg)?'subir':'avaliar';
  return{detectado,direcao,nivelExercicio:false};
}
function detectarDiasConsecutivosAssistenteCalifit(texto=''){
  const msg=normalizarLinguagemInformalAssistenteCalifit(texto).normalizado;
  return /\b(dois|2|tres|3)\s+dias?\s+(seguidos?|consecutivos?)\b|\b(dias? seguidos?|dias? consecutivos?)\b|\bsem descanso\b|\btreinar todo dia\b|\btreino todo dia\b|\btodos os dias\b|\bemendar treinos?\b|\btreinei ontem\b.{0,32}\b(hoje|tambem)\b|\btreinei hoje\b.{0,32}\bontem\b|\bontem e hoje\b|\bhoje e amanha\b/.test(msg);
}
function contextoTrocaExercicioAssistenteCalifit(texto=''){
  const msg=normalizarLinguagemInformalAssistenteCalifit(texto).normalizado;
  const exercicioEspecifico=/\b(exercicio|movimento|variacao|flexao|prancha|agachamento|remada|barra|dead bug|bird dog|hollow|ponte|rdl|swing|l-sit|pistol|paralelas|dips|afundo|avanco|step-up|supino|rosca)\b/.test(msg);
  const pedidoDireto=/\b(substituir|alternativa|outra variacao|nao quero continuar)\b/.test(msg);
  const trocaComContexto=/\b(trocar|mudar)\b/.test(msg)&&exercicioEspecifico;
  return{detectado:pedidoDireto||trocaComContexto,exercicioEspecifico};
}

