function instalarHooksTesteCalifit(){
  const instalar=window.__CALIFIT_TEST_MODULE__?.instalarHooksTesteCalifit;
  if(typeof instalar==='function') return instalar();
  return undefined;
}

// ═══════════════════════════════════════════════════════════
// 163J — EQUIPAMENTOS ESPECÍFICOS
// Tipos de elástico + cargas fixas/ajustáveis sem campos redundantes.
// Mantém compatibilidade com perfis antigos e não altera o schema.
// ═══════════════════════════════════════════════════════════
const TIPOS_ELASTICO_CALIFIT={
  super_band:'Super band / faixa longa fechada',
  extensor:'Extensor com pegadores',
  mini_band:'Mini band',
  hip_band:'Hip band',
  faixa_aberta:'Faixa aberta / TheraBand',
  generico:'Não sei o tipo'
};
function tiposElasticoPerfil(perfil=ST.perfil){
  const cfg=perfil?.cargasEquipamentos?.['Elásticos/faixas de resistência']||{};
  const aliases={
    superband:'super_band','super band':'super_band',faixa_longa:'super_band','faixa longa':'super_band',
    extensor:'extensor','extensor com pegadores':'extensor',tubo:'extensor',
    miniband:'mini_band','mini band':'mini_band',
    hipband:'hip_band','hip band':'hip_band',
    theraband:'faixa_aberta','thera band':'faixa_aberta','faixa aberta':'faixa_aberta',
    generico:'generico','nao sei':'generico','não sei':'generico'
  };
  // Sem fallback automático: uma nova seleção de elástico precisa ser confirmada.
  // A migração converte perfis antigos para “generico” de forma explícita.
  return [...new Set(arr(cfg.tipos).map(v=>aliases[normTxt(v)]||String(v||'').trim()).filter(v=>TIPOS_ELASTICO_CALIFIT[v]))];
}
function labelsTiposElastico(perfil=ST.perfil){
  return tiposElasticoPerfil(perfil).map(v=>TIPOS_ELASTICO_CALIFIT[v]||v);
}
function valoresConfiguraveisCarga(config={}){
  const c=normalizarConfigCarga(config);
  if(c.pesos.length) return c.pesos;
  if(c.tipo==='ajustavel'&&c.min>0&&c.max>=c.min){
    if(c.incremento>0){
      const valores=[];
      for(let v=c.min;v<=c.max+1e-9&&valores.length<100;v+=c.incremento) valores.push(+v.toFixed(3));
      return valores;
    }
    return c.max>c.min?[c.min,c.max]:[c.min];
  }
  if(c.tipo!=='ajustavel'&&c.peso>0) return [c.peso];
  return [];
}
function quantidadeCargasInformadas(cargas={}){
  return Object.entries(cargas||{}).reduce((total,[equip,v])=>{
    const c=normalizarConfigCarga(v,equip);
    const valores=valoresConfiguraveisCarga(c).length;
    const niveis=arr(c.niveis).filter(Boolean).length;
    const tipos=arr(c.tipos).filter(Boolean).length;
    return total+valores+niveis+tipos;
  },0);
}
function configuracaoColeteUiCalifit(config={}){
  const c=normalizarConfigCarga(config,'Colete com peso');
  if(c.tipo==='ajustavel') return{...c,tipoUi:'ajustavel'};
  if(c.pesos.length>1){
    const diffs=c.pesos.slice(1).map((v,i)=>+(v-c.pesos[i]).toFixed(3)).filter(v=>v>0);
    const inc=diffs.length&&diffs.every(v=>Math.abs(v-diffs[0])<1e-6)?diffs[0]:0;
    return{...c,tipoUi:'ajustavel',min:c.pesos[0],max:c.pesos.at(-1),incremento:c.incremento||inc};
  }
  return{...c,tipoUi:'fixo',peso:c.peso||c.pesos[0]||0};
}
function sincronizarModoEquipamentoCargaCalifit(container,prefix,idCurto){
  const select=$(`${prefix}-carga-tipo-${idCurto}`);
  if(!container||!select) return;
  const modo=select.value;
  container.querySelectorAll(`[data-carga-equip="${idCurto}"][data-carga-modo]`).forEach(p=>{
    p.hidden=p.dataset.cargaModo!==modo;
  });
}
function renderCamposCargas(container,prefix,perfil=ST.perfil){
  if(!container) return;
  container.classList.add('cargas-form');
  const eq=new Set(normalizarEquipamentos(perfil.equipamentos));
  const c=perfil.cargasEquipamentos||{};
  const linhas=[];
  const clsLabel=prefix==='ob'?'ob-l':'fl',clsInput=prefix==='ob'?'oi':'fi',clsSelect=prefix==='ob'?'os':'fi',clsGroup=prefix==='ob'?'ob-group':'carga-equip-card';
  const ajudaEquip={
    'Mochila lastrada':'Mochila com peso dentro, usada como carga improvisada. A estabilidade pode variar.',
    'Colete com peso':'Colete próprio para treino, com carga distribuída no tronco.',
    'Cinto de carga':'Cinto usado para pendurar anilhas em barras e paralelas. Só entra no plano com base técnica e estrutura compatível.',
    'Pesos de tornozelo':'Informe o peso de cada tornozeleira, não a soma do par.'
  };
  const ajuda=k=>ajudaEquip[k]?`<div class="form-help">${ajudaEquip[k]}</div>`:'';
  const slug=k=>k.replace(/\W+/g,'-').toLowerCase();
  const decisaoSemPeso=k=>{
    const cfg=c[k]||{};
    return `<label class="carga-pendente carga-pendente-opcao"><input type="checkbox" id="${prefix}-carga-ignorar-${slug(k)}" ${cfg.ignorarSemPeso?'checked':''}><span>Não sei o peso / não usar este equipamento agora. Ele permanece no perfil, mas não entra no plano até a carga ser informada.</span></label>`;
  };
  const campoLista=(k,label,placeholder='Ex: 8; 12; 16')=>{if(eq.has(k))linhas.push(`<div><label class="${clsLabel}">${label}</label><input class="${clsInput}" id="${prefix}-carga-${slug(k)}" value="${escHtml(arr(c[k]?.pesos).join('; '))}" placeholder="${placeholder}">${ajuda(k)}${decisaoSemPeso(k)}</div>`);};
  const campoUnico=(k,label,placeholder)=>{if(eq.has(k))linhas.push(`<div><label class="${clsLabel}">${label}</label><input class="${clsInput}" id="${prefix}-carga-${slug(k)}" inputmode="decimal" value="${c[k]?.peso||arr(c[k]?.pesos)[0]||''}" placeholder="${placeholder}">${ajuda(k)}${decisaoSemPeso(k)}</div>`);};

  campoLista('Kettlebell','Kettlebell: pesos disponíveis (kg)');
  if(eq.has('Halteres')){
    const cfg=normalizarConfigCarga(c.Halteres||{},'Halteres');
    const tipo=cfg.tipo==='ajustavel'?'ajustavel':'fixos';
    linhas.push(`<div class="${clsGroup}" data-carga-card="halteres">
      <label class="${clsLabel}">Halteres</label>
      <div class="carga-form-note">Escolha um formato. Pesos fixos usam somente a lista real; halteres ajustáveis usam somente faixa e incremento.</div>
      <select class="${clsSelect}" id="${prefix}-carga-tipo-halteres">
        <option value="fixos"${tipo==='fixos'?' selected':''}>Pesos fixos</option>
        <option value="ajustavel"${tipo==='ajustavel'?' selected':''}>Halter ajustável</option>
      </select>
      <div class="carga-mode-panel" data-carga-equip="halteres" data-carga-modo="fixos">
        <label class="${clsLabel}">Quais pesos você possui? (kg por halter)</label>
        <input class="${clsInput}" id="${prefix}-carga-halteres" value="${escHtml(cfg.pesos.join('; '))}" placeholder="Ex: 2; 4; 6; 8; 10">
      </div>
      <div class="carga-mode-panel" data-carga-equip="halteres" data-carga-modo="ajustavel">
        <div class="r2"><div><label class="${clsLabel}">Mínima (kg)</label><input class="${clsInput}" id="${prefix}-carga-min-halteres" type="number" min="0" step="0.1" value="${cfg.min||''}"></div><div><label class="${clsLabel}">Máxima (kg)</label><input class="${clsInput}" id="${prefix}-carga-max-halteres" type="number" min="0" step="0.1" value="${cfg.max||''}"></div></div>
        <label class="${clsLabel}">Incremento configurável (kg)</label><input class="${clsInput}" id="${prefix}-carga-inc-halteres" type="number" min="0" step="0.1" value="${cfg.incremento||''}" placeholder="Ex: 1 ou 2">
      </div>
      ${decisaoSemPeso('Halteres')}
    </div>`);
  }
  campoLista('Medicine Ball','Medicine Ball: pesos disponíveis (kg)');
  campoUnico('Mochila lastrada','Mochila lastrada: carga disponível (kg)','Ex: 10,5');
  campoLista('Pesos de tornozelo','Pesos de tornozelo: peso por tornozeleira (kg)','Ex: 0,5; 1; 2');
  campoLista('Cinto de carga','Cinto de carga: pesos disponíveis (kg)','Ex: 5; 10; 15');
  if(eq.has('Colete com peso')){
    const cfg=configuracaoColeteUiCalifit(c['Colete com peso']||{});
    linhas.push(`<div class="${clsGroup}" data-carga-card="colete-com-peso">
      <label class="${clsLabel}">Colete com peso</label>${ajuda('Colete com peso')}
      <select class="${clsSelect}" id="${prefix}-carga-tipo-colete-com-peso">
        <option value="fixo"${cfg.tipoUi==='fixo'?' selected':''}>Carga fixa</option>
        <option value="ajustavel"${cfg.tipoUi==='ajustavel'?' selected':''}>Colete ajustável</option>
      </select>
      <div class="carga-mode-panel" data-carga-equip="colete-com-peso" data-carga-modo="fixo">
        <label class="${clsLabel}">Peso total do colete (kg)</label><input class="${clsInput}" id="${prefix}-carga-colete-com-peso" inputmode="decimal" value="${cfg.peso||''}" placeholder="Ex: 8">
      </div>
      <div class="carga-mode-panel" data-carga-equip="colete-com-peso" data-carga-modo="ajustavel">
        <div class="r2"><div><label class="${clsLabel}">Mínima (kg)</label><input class="${clsInput}" id="${prefix}-carga-min-colete-com-peso" type="number" min="0" step="0.1" value="${cfg.min||''}"></div><div><label class="${clsLabel}">Máxima (kg)</label><input class="${clsInput}" id="${prefix}-carga-max-colete-com-peso" type="number" min="0" step="0.1" value="${cfg.max||''}"></div></div>
        <label class="${clsLabel}">Incremento configurável (kg)</label><input class="${clsInput}" id="${prefix}-carga-inc-colete-com-peso" type="number" min="0" step="0.1" value="${cfg.incremento||''}" placeholder="Opcional">
      </div>
      ${decisaoSemPeso('Colete com peso')}
    </div>`);
  }
  if(eq.has('Elásticos/faixas de resistência')){
    const cfg=c['Elásticos/faixas de resistência']||{};
    const tiposAtuais=tiposElasticoPerfil(perfil);
    const niveisAtuais=niveisElasticoPerfil(perfil);
    linhas.push(`<div class="${clsGroup}">
      <label class="${clsLabel}">Tipos de elástico disponíveis</label>
      <div class="equip-option-grid" id="${prefix}-elastico-tipos">${Object.entries(TIPOS_ELASTICO_CALIFIT).map(([v,l])=>`<button type="button" class="${prefix==='ob'?'oc':'chip'}${tiposAtuais.includes(v)?' on':''}" data-elastico-tipo="${v}">${l}</button>`).join('')}</div>
      <div class="form-help elastic-type-help">Escolha pelo menos um tipo ou marque “Não sei o tipo”. O tipo muda quais exercícios são possíveis; mini band, por exemplo, não substitui uma faixa longa em remadas ou assistência na barra.</div>
      <label class="${clsLabel}">Resistências disponíveis</label>
      <div class="equip-option-grid" id="${prefix}-elasticos">${['leve','medio','forte'].map(v=>`<button type="button" class="${prefix==='ob'?'oc':'chip'}${niveisAtuais.includes(v==='medio'?'médio':v)?' on':''}" data-elastico="${v}">${v==='medio'?'Média':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>
      <div class="form-help">As cores variam entre fabricantes. A resistência é opcional; deixe sem marcar se não souber.</div>
    </div>`);
  }
  const titulo=prefix==='pp'?'<div class="mini-label">Pesos, formatos e resistências disponíveis</div>':'';
  const aviso=avisoEquipamentosCargaPendenteHtml(perfil);
  const avisoOb=prefix==='ob'&&linhas.length?'<div class="ob-info" style="margin-bottom:10px">Informe somente o formato que você realmente possui. Campos que não correspondem ao equipamento ficam ocultos.</div>':'';
  container.innerHTML=titulo+aviso+avisoOb+(linhas.length?linhas.join(''):'<div class="ms">Selecione um equipamento com carga ou resistência para detalhar.</div>');
  container.querySelectorAll('[data-elastico],[data-elastico-tipo]').forEach(b=>b.addEventListener('click',()=>{
    b.classList.toggle('on');
    if(b.dataset.elasticoTipo&&b.dataset.elasticoTipo!=='generico'&&b.classList.contains('on')) container.querySelector('[data-elastico-tipo="generico"]')?.classList.remove('on');
    if(b.dataset.elasticoTipo==='generico'&&b.classList.contains('on')) container.querySelectorAll('[data-elastico-tipo]:not([data-elastico-tipo="generico"])').forEach(x=>x.classList.remove('on'));
    if(prefix==='ob') atualizarResumosDivulgacaoOnboarding();
  }));
  ['halteres','colete-com-peso'].forEach(id=>{
    const select=$(`${prefix}-carga-tipo-${id}`);
    if(!select) return;
    const card=container.querySelector(`[data-carga-card="${id}"]`);
    const sync=()=>sincronizarModoEquipamentoCargaCalifit(card,prefix,id);
    select.addEventListener('change',()=>{sync();if(prefix==='ob') atualizarResumosDivulgacaoOnboarding();});
    sync();
  });
  if(prefix==='ob') container.querySelectorAll('input,select').forEach(el=>{
    el.addEventListener('input',atualizarResumosDivulgacaoOnboarding);
    el.addEventListener('change',atualizarResumosDivulgacaoOnboarding);
  });
}
function coletarCargasFormulario(prefix,perfil=ST.perfil){
  const out={...(perfil.cargasEquipamentos||{})};
  const slug=k=>k.replace(/\W+/g,'-').toLowerCase();
  const ignorar=(k,temCarga=false)=>!temCarga&&!!$(`${prefix}-carga-ignorar-${slug(k)}`)?.checked;
  const ids={'Kettlebell':'kettlebell','Medicine Ball':'medicine-ball','Mochila lastrada':'mochila-lastrada','Pesos de tornozelo':'pesos-de-tornozelo','Cinto de carga':'cinto-de-carga'};
  Object.entries(ids).forEach(([k,id])=>{
    const el=$(`${prefix}-carga-${id}`);if(!el)return;
    if(k==='Mochila lastrada'){
      const r=parseCargaUnica(el.value,k),peso=r.valido?(r.valor||0):0;
      out[k]={peso,ignorarSemPeso:ignorar(k,!!peso)};
    }else{
      const r=parseListaCargas(el.value,k),pesos=r.valido?r.valores:[];
      out[k]={pesos,ignorarSemPeso:ignorar(k,pesos.length>0)};
    }
  });
  const tipoH=$(`${prefix}-carga-tipo-halteres`)?.value;
  if(tipoH){
    if(tipoH==='ajustavel'){
      const min=parseCargaUnica($(`${prefix}-carga-min-halteres`)?.value,'Halteres').valor||0;
      const max=parseCargaUnica($(`${prefix}-carga-max-halteres`)?.value,'Halteres').valor||0;
      const incremento=parseIncrementoCarga($(`${prefix}-carga-inc-halteres`)?.value).valor||0;
      out.Halteres={tipo:'ajustavel',pesos:[],peso:0,min,max,incremento,ignorarSemPeso:ignorar('Halteres',!!min&&!!max)};
    }else{
      const pesos=parseListaCargas($(`${prefix}-carga-halteres`)?.value||'','Halteres').valores||[];
      out.Halteres={tipo:'lista',pesos,peso:0,min:0,max:0,incremento:0,ignorarSemPeso:ignorar('Halteres',pesos.length>0)};
    }
  }
  const tipoC=$(`${prefix}-carga-tipo-colete-com-peso`)?.value;
  if(tipoC){
    if(tipoC==='ajustavel'){
      const min=parseCargaUnica($(`${prefix}-carga-min-colete-com-peso`)?.value,'Colete com peso').valor||0;
      const max=parseCargaUnica($(`${prefix}-carga-max-colete-com-peso`)?.value,'Colete com peso').valor||0;
      const incremento=parseIncrementoCarga($(`${prefix}-carga-inc-colete-com-peso`)?.value).valor||0;
      out['Colete com peso']={tipo:'ajustavel',pesos:[],peso:0,min,max,incremento,ignorarSemPeso:ignorar('Colete com peso',!!min&&!!max)};
    }else{
      const peso=parseCargaUnica($(`${prefix}-carga-colete-com-peso`)?.value||'','Colete com peso').valor||0;
      out['Colete com peso']={tipo:'fixo',pesos:[],peso,min:0,max:0,incremento:0,ignorarSemPeso:ignorar('Colete com peso',!!peso)};
    }
  }
  if($(`${prefix}-elasticos`)){
    const niveis=[...document.querySelectorAll(`#${prefix}-elasticos [data-elastico].on`)].map(b=>b.dataset.elastico);
    const tipos=[...document.querySelectorAll(`#${prefix}-elastico-tipos [data-elastico-tipo].on`)].map(b=>b.dataset.elasticoTipo);
    out['Elásticos/faixas de resistência']={...(out['Elásticos/faixas de resistência']||{}),niveis,tipos};
  }
  return out;
}
function validarCargasFormulario(prefix){
  const simples={'Kettlebell':'kettlebell','Medicine Ball':'medicine-ball','Pesos de tornozelo':'pesos-de-tornozelo','Cinto de carga':'cinto-de-carga'};
  for(const [equip,id] of Object.entries(simples)){
    const el=$(`${prefix}-carga-${id}`);if(!el) continue;
    const r=parseListaCargas(el.value,equip);if(!r.valido){showToast(r.mensagem);el.focus?.();return false;}
  }
  const mochila=$(`${prefix}-carga-mochila-lastrada`);
  if(mochila){const r=parseCargaUnica(mochila.value,'Mochila lastrada');if(!r.valido){showToast(r.mensagem);mochila.focus?.();return false;}}
  const validarAjustavel=(equip,id)=>{
    for(const campo of ['min','max']){
      const el=$(`${prefix}-carga-${campo}-${id}`);if(!el) continue;
      const r=parseCargaUnica(el.value,equip);if(!r.valido){showToast(r.mensagem);el.focus?.();return false;}
    }
    const min=parseCargaUnica($(`${prefix}-carga-min-${id}`)?.value,equip).valor||0;
    const max=parseCargaUnica($(`${prefix}-carga-max-${id}`)?.value,equip).valor||0;
    if(min&&max&&max<min){showToast(`A carga máxima de ${equip} deve ser maior ou igual à mínima.`);$(`${prefix}-carga-max-${id}`)?.focus?.();return false;}
    const inc=$(`${prefix}-carga-inc-${id}`);if(inc){const r=parseIncrementoCarga(inc.value);if(!r.valido){showToast(r.mensagem);inc.focus?.();return false;}}
    return true;
  };
  if($(`${prefix}-carga-tipo-halteres`)?.value==='ajustavel'){
    if(!validarAjustavel('Halteres','halteres')) return false;
  }else if($(`${prefix}-carga-halteres`)){
    const el=$(`${prefix}-carga-halteres`),r=parseListaCargas(el.value,'Halteres');if(!r.valido){showToast(r.mensagem);el.focus?.();return false;}
  }
  if($(`${prefix}-carga-tipo-colete-com-peso`)?.value==='ajustavel'){
    if(!validarAjustavel('Colete com peso','colete-com-peso')) return false;
  }else if($(`${prefix}-carga-colete-com-peso`)){
    const el=$(`${prefix}-carga-colete-com-peso`),r=parseCargaUnica(el.value,'Colete com peso');if(!r.valido){showToast(r.mensagem);el.focus?.();return false;}
  }
  return true;
}
function linhasResistenciaElastico(exercicio,perfil=ST.perfil){
  if(!usaElasticoExercicio(exercicio)) return [];
  const tipos=labelsTiposElastico(perfil),niveis=niveisElasticoPerfil(perfil);
  const linhas=[];
  if(tipos.length) linhas.push({label:'Tipos disponíveis',texto:fraseListaHumana(tipos)});
  linhas.push(niveis.length?{label:'Resistências disponíveis',texto:fraseListaHumana(niveis)}:{label:'Resistência não cadastrada',texto:`Use resistência leve/moderada e ajuste pelo ${rotuloRpeUsuario()}.`});
  linhas.push({label:'Resistência sugerida',texto:sugerirResistenciaElastico(exercicio,perfil)});
  if(niveis.length===1&&normTxt(niveis[0])==='forte'&&(perfil?.nivel==='init'||flagsSegurancaPerfil(perfil).dorOmbro||flagsSegurancaPerfil(perfil).dorCervical||flagsSegurancaPerfil(perfil).dorPunho)) linhas.push({label:'Atenção',texto:`A resistência disponível pode ser alta para este contexto. Use somente se mantiver técnica e ${rotuloRpeUsuario()} adequado.`});
  return linhas;
}


// ═══════════════════════════════════════════════════════════
// 163J1 — EQUIPAMENTOS INTEGRADOS AO MOTOR
// Validação obrigatória de tipo de elástico, compatibilidade por exercício
// e uso estrito das cargas realmente disponíveis na referência/progressão.
// ═══════════════════════════════════════════════════════════
const TIPOS_LONGOS_ELASTICO_163J1=['super_band','extensor','faixa_aberta'];
const TIPOS_QUADRIL_ELASTICO_163J1=['mini_band','hip_band','faixa_aberta'];
function tiposElasticoCompativeisExercicio163J1(exercicio){
  const n=normTxt(nomeTecnicoExercicio(exercicio)||exercicio?.n||exercicio||'');
  if(/barra assistida|pull-?up assist|chin-?up assist/.test(n)) return['super_band'];
  if(/caminhada lateral|monster walk|abducao|abdução|clam|ponte.*elastico|ponte.*elástico|agachamento.*elastico|agachamento.*elástico/.test(n)) return[...TIPOS_QUADRIL_ELASTICO_163J1];
  if(/shoulder pass through|passagem de ombro|pull.?apart/.test(n)) return['super_band','faixa_aberta'];
  if(/external rotation|rotacao externa|rotação externa|face pull|remada.*elastico|remada.*elástico|pallof|rosca.*elastico|triceps.*elastico|tríceps.*elástico|supino.*elastico|desenvolvimento.*elastico/.test(n)) return[...TIPOS_LONGOS_ELASTICO_163J1];
  if(/elastico|elástico|theraband|faixa/.test(n)) return[...TIPOS_LONGOS_ELASTICO_163J1];
  return[];
}
function exercicioExigeElastico163J1(exercicio,requisitos=null){
  const req=requisitos||{};
  if(arr(req.usados).some(v=>normalizarEquipamentoNome(v)==='Elásticos/faixas de resistência')) return true;
  const meta=metaExercicio(exercicio)||{};
  if(arr(meta.equipamentosNecessarios||meta.equipamentos||meta.exige).some(v=>/elastico|elástico|faixa/.test(normTxt(v)))) return true;
  return tiposElasticoCompativeisExercicio163J1(exercicio).length>0;
}
function avaliarCompatibilidadeElastico163J1(exercicio,perfil=ST.perfil){
  const selecionado=normalizarEquipamentos(perfil?.equipamentos).includes('Elásticos/faixas de resistência');
  const disponiveis=tiposElasticoPerfil(perfil);
  const aceitos=tiposElasticoCompativeisExercicio163J1(exercicio);
  if(!selecionado) return{disponivel:false,aceitos,disponiveis,compativeis:[],motivo:'Elásticos não selecionados no perfil.'};
  if(!disponiveis.length) return{disponivel:false,aceitos,disponiveis,compativeis:[],motivo:'Tipo de elástico ainda não definido.'};
  if(disponiveis.includes('generico')) return{disponivel:true,aceitos,disponiveis,compativeis:['generico'],generico:true,motivo:'Tipo não especificado; confirmar compatibilidade antes de executar.'};
  if(!aceitos.length) return{disponivel:true,aceitos,disponiveis,compativeis:disponiveis};
  const compativeis=disponiveis.filter(v=>aceitos.includes(v));
  return{disponivel:compativeis.length>0,aceitos,disponiveis,compativeis,motivo:compativeis.length?'':`Este exercício exige ${fraseListaHumana(aceitos.map(v=>TIPOS_ELASTICO_CALIFIT[v]))}.`};
}
function temTipoElasticoCompativel163J1(exercicio,perfil=ST.perfil){
  return avaliarCompatibilidadeElastico163J1(exercicio,perfil).disponivel;
}
function equipamentosSelecionadosFormulario163J1(prefix){
  if(prefix==='ob') return normalizarEquipamentos(getObVals('ob-eqs'));
  if(prefix==='pp') return normalizarEquipamentos([...document.querySelectorAll('[data-pp-eq].on')].map(b=>b.getAttribute('data-pp-eq')));
  return normalizarEquipamentos(ST.perfil?.equipamentos);
}
function validarTiposElasticoFormulario163J1(prefix){
  const selecionados=equipamentosSelecionadosFormulario163J1(prefix);
  if(!selecionados.includes('Elásticos/faixas de resistência')) return true;
  const grid=$(`${prefix}-elastico-tipos`);
  const tipos=grid?[...grid.querySelectorAll('[data-elastico-tipo].on')].map(b=>b.dataset.elasticoTipo):[];
  grid?.classList.toggle('equip-config-error',!tipos.length);
  grid?.parentElement?.querySelector?.('.equip-config-error-msg')?.remove?.();
  if(tipos.length) return true;
  if(grid){
    const msg=document.createElement('div');
    msg.className='equip-config-error-msg';
    msg.textContent='Escolha o tipo de elástico ou marque “Não sei o tipo”.';
    grid.insertAdjacentElement?.('afterend',msg);
  }
  if(prefix==='ob') definirBlocoDetalhes($('ob-cargas-btn'),$('ob-cargas-panel'),true);
  else grid?.closest?.('details')?.setAttribute?.('open','');
  showToast('Escolha o tipo de elástico ou marque “Não sei o tipo” antes de salvar.',5000);
  grid?.querySelector?.('[data-elastico-tipo]')?.focus?.();
  grid?.scrollIntoView?.({behavior:'smooth',block:'center'});
  return false;
}
const validarCargasFormularioBase163J1=validarCargasFormulario;
validarCargasFormulario=function(prefix){
  return validarCargasFormularioBase163J1(prefix)&&validarTiposElasticoFormulario163J1(prefix);
};
const coletarCargasFormularioBase163J1=coletarCargasFormulario;
coletarCargasFormulario=function(prefix,perfil=ST.perfil){
  const out=coletarCargasFormularioBase163J1(prefix,perfil);
  const cfg=out['Elásticos/faixas de resistência'];
  if(cfg) cfg.tiposConfirmados=arr(cfg.tipos).length>0;
  return out;
};

// Integra a compatibilidade ao mesmo ponto usado pelo gerador, substituições e Skill Tree.
const requisitosEquipamentoExercicioBase163J1=requisitosEquipamentoExercicio;
requisitosEquipamentoExercicio=function(exercicio,perfil={}){
  const base=requisitosEquipamentoExercicioBase163J1(exercicio,perfil);
  if(!exercicioExigeElastico163J1(exercicio,base)) return base;
  const compat=avaliarCompatibilidadeElastico163J1(exercicio,perfil);
  return{...base,disponivel:base.disponivel&&compat.disponivel,tiposElasticoAceitos:compat.aceitos,tiposElasticoCompativeis:compat.compativeis,motivoElastico:compat.motivo};
};

// A última carga registrada só é reutilizada se ainda estiver disponível.
// Caso contrário, a referência volta para a carga configurada mais próxima e segura.
const sugerirCargaInicialExercicioBase163J1=sugerirCargaInicialExercicio;
sugerirCargaInicialExercicio=function(exercicio,perfil=ST.perfil,historico=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return null;
  const valores=cargasDisponiveisExercicio(nomeTecnicoExercicio(exercicio)||exercicio?.n||exercicio,perfil);
  const logs=arr(historico).map(h=>h?.log||h);
  const usadas=logs.map(l=>cargaRegistradaExercicio(exercicio,l)).filter(v=>v>0);
  if(usadas.length&&valores.length){
    const ultima=usadas.at(-1);
    const exata=valores.find(v=>Math.abs(v-ultima)<0.001);
    if(exata) return{valor:exata,tipo:'usada',texto:`Carga usada mais recente: ${fmtKg(exata)}`};
    const inferiores=valores.filter(v=>v<ultima);
    const ajustada=inferiores.at(-1)||valores[0];
    return{valor:ajustada,tipo:'ajustada',texto:`A carga anterior (${fmtKg(ultima)}) não está disponível agora. Referência ajustada para ${fmtKg(ajustada)}.`};
  }
  return sugerirCargaInicialExercicioBase163J1(exercicio,perfil,historico);
};
function resumoIntegracaoEquipamento163J1(exercicio,perfil=ST.perfil){
  const req=requisitosEquipamentoExercicio(exercicio,perfil);
  const elastico=exercicioExigeElastico163J1(exercicio,req)?avaliarCompatibilidadeElastico163J1(exercicio,perfil):null;
  const cargas=exercicioUsaCargaNumerica(exercicio)?cargasDisponiveisExercicio(nomeTecnicoExercicio(exercicio)||exercicio,perfil):[];
  return{disponivel:req.disponivel,equipamentos:req.usados||[],elastico,cargas};
}


// ═══════════════════════════════════════════════════════════
// 163J2 — VALIDAÇÃO VISUAL + MINI BAND NO PLANO
// Destaca em vermelho todo campo de equipamento que bloqueia o salvamento,
// permite desmarcar equipamento sem exigir antes sua configuração e usa
// mini/hip band como ativação útil em sessões de pernas/posterior.
// ═══════════════════════════════════════════════════════════
function limparErrosValidacao163J2(raiz){
  raiz?.querySelectorAll?.('.validation-error-target').forEach(el=>el.classList.remove('validation-error-target'));
  raiz?.querySelectorAll?.('.validation-error-msg[data-validation-163j2]').forEach(el=>el.remove());
  raiz?.querySelectorAll?.('.equip-config-error').forEach(el=>el.classList.remove('equip-config-error'));
  raiz?.querySelectorAll?.('.equip-config-error-msg').forEach(el=>el.remove());
}
function marcarErroValidacao163J2(el,mensagem){
  if(!el) return;
  el.classList.add('validation-error-target');
  const ancora=el.closest?.('.carga-mode-panel,.carga-equip-card,.ob-group')||el.parentElement||el;
  if(!(el.parentElement||ancora).querySelector?.('.validation-error-msg[data-validation-163j2]')){
    const msg=document.createElement('div');
    msg.className='validation-error-msg';
    msg.dataset.validation163j2=mensagem;
    msg.textContent=mensagem;
    (el.parentElement||ancora).appendChild(msg);
  }
}
function finalizarErroValidacao163J2(prefix,erros=[]){
  if(!erros.length) return true;
  const primeiro=erros[0];
  if(prefix==='ob') definirBlocoDetalhes($('ob-cargas-btn'),$('ob-cargas-panel'),true);
  else primeiro.el?.closest?.('details')?.setAttribute?.('open','');
  showToast(erros.length>1?'Revise os campos destacados em vermelho antes de salvar.':primeiro.msg,5000);
  primeiro.el?.focus?.();
  primeiro.el?.scrollIntoView?.({behavior:'smooth',block:'center'});
  return false;
}
validarCargasFormulario=function(prefix){
  const raiz=$(`${prefix}-cargas`);
  limparErrosValidacao163J2(raiz);
  const erros=[];
  const add=(el,msg)=>{marcarErroValidacao163J2(el,msg);erros.push({el,msg});};
  const ignorado=equip=>!!$(`${prefix}-carga-ignorar-${equip.replace(/\W+/g,'-').toLowerCase()}`)?.checked;
  const listaSimples={'Kettlebell':'kettlebell','Medicine Ball':'medicine-ball','Pesos de tornozelo':'pesos-de-tornozelo'};
  for(const [equip,id] of Object.entries(listaSimples)){
    const el=$(`${prefix}-carga-${id}`); if(!el) continue;
    const r=parseListaCargas(el.value,equip);
    if(!r.valido) add(el,r.mensagem);
    else if(!r.valores.length&&!ignorado(equip)) add(el,`Informe os pesos disponíveis de ${equip} ou marque “não sei o peso / não usar agora”.`);
  }
  const mochila=$(`${prefix}-carga-mochila-lastrada`);
  if(mochila){
    const r=parseCargaUnica(mochila.value,'Mochila lastrada');
    if(!r.valido) add(mochila,r.mensagem);
    else if(!(r.valor>0)&&!ignorado('Mochila lastrada')) add(mochila,'Informe a carga da mochila ou marque “não sei o peso / não usar agora”.');
  }
  const validarAjustavel=(equip,id)=>{
    const minEl=$(`${prefix}-carga-min-${id}`),maxEl=$(`${prefix}-carga-max-${id}`),incEl=$(`${prefix}-carga-inc-${id}`);
    const minR=parseCargaUnica(minEl?.value,equip),maxR=parseCargaUnica(maxEl?.value,equip);
    if(!minR.valido) add(minEl,minR.mensagem);
    if(!maxR.valido) add(maxEl,maxR.mensagem);
    if(minR.valido&&maxR.valido&&!ignorado(equip)){
      if(!(minR.valor>0)) add(minEl,`Informe a carga mínima de ${equip}.`);
      if(!(maxR.valor>0)) add(maxEl,`Informe a carga máxima de ${equip}.`);
      if(minR.valor>0&&maxR.valor>0&&maxR.valor<minR.valor) add(maxEl,`A carga máxima de ${equip} deve ser maior ou igual à mínima.`);
    }
    if(incEl){const r=parseIncrementoCarga(incEl.value);if(!r.valido)add(incEl,r.mensagem);}
  };
  if($(`${prefix}-carga-tipo-halteres`)){
    if($(`${prefix}-carga-tipo-halteres`).value==='ajustavel') validarAjustavel('Halteres','halteres');
    else{
      const el=$(`${prefix}-carga-halteres`),r=parseListaCargas(el?.value||'','Halteres');
      if(!r.valido) add(el,r.mensagem);
      else if(!r.valores.length&&!ignorado('Halteres')) add(el,'Informe os pesos dos halteres ou marque “não sei o peso / não usar agora”.');
    }
  }
  if($(`${prefix}-carga-tipo-colete-com-peso`)){
    if($(`${prefix}-carga-tipo-colete-com-peso`).value==='ajustavel') validarAjustavel('Colete com peso','colete-com-peso');
    else{
      const el=$(`${prefix}-carga-colete-com-peso`),r=parseCargaUnica(el?.value||'','Colete com peso');
      if(!r.valido) add(el,r.mensagem);
      else if(!(r.valor>0)&&!ignorado('Colete com peso')) add(el,'Informe o peso do colete ou marque “não sei o peso / não usar agora”.');
    }
  }
  const selecionados=equipamentosSelecionadosFormulario163J1(prefix);
  if(selecionados.includes('Elásticos/faixas de resistência')){
    const grid=$(`${prefix}-elastico-tipos`);
    const tipos=grid?[...grid.querySelectorAll('[data-elastico-tipo].on')].map(b=>b.dataset.elasticoTipo):[];
    if(!tipos.length){
      grid?.classList.add('equip-config-error');
      if(grid){const msg=document.createElement('div');msg.className='equip-config-error-msg';msg.textContent='Escolha o tipo de elástico ou marque “Não sei o tipo”.';grid.insertAdjacentElement('afterend',msg);}
      erros.push({el:grid?.querySelector?.('[data-elastico-tipo]')||grid,msg:'Escolha o tipo de elástico ou marque “Não sei o tipo”.'});
    }
  }
  return finalizarErroValidacao163J2(prefix,erros);
};

// 163J2.1 — validação visual dos campos essenciais fora do bloco de cargas
function limparCampoObrigatorioCalifit(el){
  if(!el) return;
  el.classList?.remove?.('validation-error-target');
  const id=el.id||el.getAttribute?.('data-ob-seg')||el.getAttribute?.('data-required-key')||'';
  const parent=el.parentElement;
  if(parent){
    [...parent.querySelectorAll?.('.validation-required-msg[data-required-for]')||[]].forEach(msg=>{
      if(!id||msg.dataset.requiredFor===id) msg.remove();
    });
  }
}
function marcarCampoObrigatorioCalifit(el,mensagem){
  if(!el) return false;
  limparCampoObrigatorioCalifit(el);
  el.classList.add('validation-error-target');
  const id=el.id||el.getAttribute?.('data-ob-seg')||el.getAttribute?.('data-required-key')||`required-${Date.now()}`;
  if(!el.id&&!el.getAttribute?.('data-ob-seg')) el.setAttribute?.('data-required-key',id);
  const msg=document.createElement('div');
  msg.className='validation-required-msg';
  msg.dataset.requiredFor=id;
  msg.textContent=mensagem;
  el.insertAdjacentElement?.('afterend',msg);
  return false;
}
function erroObrigatorioOnboardingCalifit(el,mensagem,{abrir=null}={}){
  marcarCampoObrigatorioCalifit(el,mensagem);
  abrir?.();
  showToast(mensagem,5000);
  const foco=el?.querySelector?.('button,input,select,textarea')||el;
  foco?.focus?.();
  el?.scrollIntoView?.({behavior:'smooth',block:'center'});
  return false;
}
function limparObrigatorioAoInteragirCalifit(){
  document.addEventListener('click',e=>{
    const seletores=['#ob-obj-principal','#ob-eqs','#ob-dor-escolha','#ob-lims','#ob-dias','[data-ob-seg="ob-nivel"]','[data-ob-seg="ob-freq-recente"]','#pp-dias','#pp-eqs'];
    for(const seletor of seletores){
      const alvo=e.target?.closest?.(seletor);
      if(alvo){limparCampoObrigatorioCalifit(alvo);break;}
    }
  });
  document.addEventListener('change',e=>{
    if(['ob-freq-recente','ob-nivel','pp-freq-recente','pp-obj-pri'].includes(e.target?.id||'')) limparCampoObrigatorioCalifit(e.target);
  });
}
if(typeof document!=='undefined') limparObrigatorioAoInteragirCalifit();

Object.assign(EXD,{
  'Caminhada lateral com mini band' :{pad:'agachar',m:'Glúteo médio, quadril e estabilizadores do joelho',d:'Coloque a mini band acima dos joelhos ou nos tornozelos. Mantenha leve flexão de quadril e joelhos e dê passos laterais curtos sem deixar os joelhos caírem para dentro.',prog:'Passos curtos → mais passos → resistência maior'},
  'Ponte de Glúteo com mini band':{pad:'dobrarQ',m:'Glúteos, posterior de coxa e abdutores',d:'Coloque a mini band acima dos joelhos. Suba o quadril, mantenha os joelhos alinhados e faça leve pressão para fora sem arquear a lombar.',prog:'Pausa no topo → mais repetições → resistência maior'},
  'Abdução de quadril com mini band':{pad:'agachar',m:'Glúteo médio e estabilizadores do quadril',d:'Com a mini band acima dos joelhos ou tornozelos, afaste uma perna com controle sem inclinar o tronco. Faça os dois lados.',prog:'Com apoio → sem apoio → resistência maior'}
});
Object.assign(META_EXERCICIOS,{
  'Caminhada lateral com mini band':{regioesPrimarias:['quadril'],regioesSecundarias:['joelho'],padroes:['agachar','unilateral'],riscos:[],exige:['elastico'],nivelMinimo:'init',agressividade:'baixa',alternativas:['Abdução de quadril com mini band','Ponte de Glúteo']},
  'Ponte de Glúteo com mini band':{regioesPrimarias:['quadril'],regioesSecundarias:['posterior_coxa','joelho'],padroes:['hinge'],riscos:[],exige:['elastico'],nivelMinimo:'init',agressividade:'baixa',alternativas:['Ponte de Glúteo']},
  'Abdução de quadril com mini band':{regioesPrimarias:['quadril'],regioesSecundarias:['joelho'],padroes:['agachar','unilateral'],riscos:[],exige:['elastico'],nivelMinimo:'init',agressividade:'baixa',alternativas:['Caminhada lateral com mini band','Ponte de Glúteo']}
});
['Caminhada lateral com mini band','Ponte de Glúteo com mini band','Abdução de quadril com mini band'].forEach(n=>{if(!INVENTARIO_EXERCICIOS.includes(n))INVENTARIO_EXERCICIOS.push(n);});
const tiposElasticoCompativeisExercicioBase163J2=tiposElasticoCompativeisExercicio163J1;
tiposElasticoCompativeisExercicio163J1=function(exercicio){
  const n=normTxt(nomeTecnicoExercicio(exercicio)||exercicio?.n||exercicio||'');
  if(/mini band|hip band/.test(n)&&/ponte|caminhada|abducao|abdução|agachamento/.test(n)) return[...TIPOS_QUADRIL_ELASTICO_163J1];
  return tiposElasticoCompativeisExercicioBase163J2(exercicio);
};
const usaElasticoExercicioBase163J2=usaElasticoExercicio;
usaElasticoExercicio=function(exercicio){
  const n=normTxt(nomeTecnicoExercicio(exercicio)||exercicio?.n||exercicio||'');
  return usaElasticoExercicioBase163J2(exercicio)||/mini band|hip band/.test(n);
};
function integrarMiniBandPlano163J2(plano,perfil=ST.perfil){
  if(!plano?.dias) return plano;
  const tipos=tiposElasticoPerfil(perfil);
  if(!tipos.some(t=>t==='mini_band'||t==='hip_band')) return plano;
  const flags=flagsSegurancaPerfil(perfil);
  if(flags.dorQuadril||intensidadeLimitacao(perfil,['quadril','joelho'])==='forte') return plano;
  const aplicarEmDias=alvoPlano=>{
    if(!alvoPlano?.dias) return;
    const dias=Object.entries(alvoPlano.dias).sort((a,b)=>+a[0]-+b[0]);
    const alvo=dias.find(([,dia])=>{
      if(!dia||['descanso','atividade'].includes(dia.tipo)) return false;
      const principais=arr(dia.ex);
      return /perna|agachar|posterior|full body|corpo inteiro/.test(normTxt(dia.nome||''))||principais.some(ex=>['agachar','dobrarQ'].includes(padraoExercicioCodigo(ex)));
    });
    if(!alvo) return;
    const [,dia]=alvo;
    dia.aq=arr(dia.aq);
    if(!dia.aq.some(ex=>normTxt(ex.n)==='caminhada lateral com mini band')){
      dia.aq.push({n:'Caminhada lateral com mini band',s:1,r:'8–10 passos cada lado',ds:0,nota:'Ativação leve; joelhos alinhados e passos curtos'});
      dia.aq=deduplicarExerciciosTreino({aq:dia.aq}).aq;
    }
  };
  aplicarEmDias(plano);
  aplicarEmDias(plano._baseEstrutural);
  aplicarEmDias(plano._baseSemTempo);
  return plano;
}
const gerarPlanoBase163J2=gerarPlano;
gerarPlano=function(perfil){
  return integrarMiniBandPlano163J2(gerarPlanoBase163J2(perfil),perfil);
};


// ═══════════════════════════════════════════════════════════
// 163K — PRESCRIÇÃO E PROGRESSÃO DE CARGAS
// Usa somente cargas/resistências configuradas, exige consolidação em duas
// sessões e altera uma variável por vez.
// ═══════════════════════════════════════════════════════════
const ORDEM_RESISTENCIA_163K=['leve','médio','forte'];
function normalizarResistenciaElastico163K(valor){
  const n=normTxt(valor||'');
  if(!n) return '';
  if(/leve|light/.test(n)) return 'leve';
  if(/media|medio|moderada|medium/.test(n)) return 'médio';
  if(/forte|pesada|heavy/.test(n)) return 'forte';
  return '';
}
function resistenciaElasticoRegistrada163K(log={}){
  return normalizarResistenciaElastico163K(log?.resistenciaElastico??log?.resistenciaUsada??'');
}
function resistenciasElasticoDisponiveis163K(perfil=ST.perfil){
  return ORDEM_RESISTENCIA_163K.filter(v=>niveisElasticoPerfil(perfil).map(normalizarResistenciaElastico163K).includes(v));
}
function resistenciaAnteriorDisponivel163K(atual,perfil=ST.perfil){
  const disponiveis=resistenciasElasticoDisponiveis163K(perfil),idx=disponiveis.indexOf(normalizarResistenciaElastico163K(atual));
  return idx>0?disponiveis[idx-1]:'';
}
function ultimaResistenciaElasticoRegistrada163K(exercicio,historico=[]){
  return arr(historico).map(h=>resistenciaElasticoRegistrada163K(h?.log||h)).filter(Boolean).at(-1)||'';
}
const sugerirResistenciaElasticoBase163K=sugerirResistenciaElastico;
sugerirResistenciaElastico=function(exercicio,perfil=ST.perfil){
  if(!usaElasticoExercicio(exercicio)) return '';
  const disponiveis=resistenciasElasticoDisponiveis163K(perfil);
  if(!disponiveis.length) return sugerirResistenciaElasticoBase163K(exercicio,perfil);
  const desejada=normalizarResistenciaElastico163K(sugerirResistenciaElasticoBase163K(exercicio,perfil));
  if(disponiveis.includes(desejada)) return desejada;
  const alvo=Math.max(0,ORDEM_RESISTENCIA_163K.indexOf(desejada));
  const conservadoras=disponiveis.filter(v=>ORDEM_RESISTENCIA_163K.indexOf(v)<=alvo);
  return conservadoras.at(-1)||disponiveis[0];
};
function htmlCampoResistenciaUsada163K(exercicio,atual='',id='rd-resistencia-elastico'){
  if(!usaElasticoExercicio(exercicio)) return '';
  const disponiveis=resistenciasElasticoDisponiveis163K(ST.perfil);
  const valores=disponiveis.length?disponiveis:ORDEM_RESISTENCIA_163K;
  const selecionada=normalizarResistenciaElastico163K(atual);
  const opcoes=['<option value="">não informada</option>',...valores.map(v=>`<option value="${v}"${selecionada===v?' selected':''}>${v}</option>`)].join('');
  return `<div class="form-field"><label class="form-label" for="${id}">Resistência usada</label><select class="fi form-control" id="${id}">${opcoes}</select><div class="form-help">Registre a resistência real da faixa. O app não converte elástico em kg.</div></div>`;
}
function cargaAnteriorDisponivel163K(exercicio,cargaAtual,perfil=ST.perfil){
  const valores=cargasDisponiveisExercicio(exercicio,perfil).filter(v=>v<+cargaAtual-0.001);
  return valores.length?valores.at(-1):0;
}
function cargaConfiguradaMaisProxima163K(exercicio,carga,perfil=ST.perfil,{preferirInferior=true}={}){
  const valores=cargasDisponiveisExercicio(exercicio,perfil);
  if(!valores.length) return 0;
  const exata=valores.find(v=>Math.abs(v-carga)<0.001);
  if(exata) return exata;
  if(preferirInferior){const inferiores=valores.filter(v=>v<carga);if(inferiores.length)return inferiores.at(-1);}
  return valores.reduce((melhor,v)=>Math.abs(v-carga)<Math.abs(melhor-carga)?v:melhor,valores[0]);
}
function referenciaCargaInicialConservadora163K(exercicio,perfil=ST.perfil){
  const valores=cargasDisponiveisExercicio(exercicio,perfil);
  if(!valores.length) return 0;
  // Sem histórico, a referência é um teste conservador; não uma afirmação de carga ideal.
  return valores[0];
}
const sugerirCargaInicialExercicioBase163K=sugerirCargaInicialExercicio;
sugerirCargaInicialExercicio=function(exercicio,perfil=ST.perfil,historico=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return null;
  const planejada=cargaPlanejadaExercicio(exercicio);
  if(planejada){
    const valida=cargaConfiguradaMaisProxima163K(exercicio,planejada,perfil);
    if(valida) return{valor:valida,tipo:'planejada',texto:`Carga planejada: ${fmtKg(valida)}. Mantenha séries e repetições.`};
  }
  const logs=arr(historico).map(h=>h?.log||h);
  const usadas=logs.map(l=>cargaRegistradaExercicio(exercicio,l)).filter(v=>v>0);
  if(usadas.length){
    const ultima=usadas.at(-1),ajustada=cargaConfiguradaMaisProxima163K(exercicio,ultima,perfil);
    if(ajustada&&Math.abs(ajustada-ultima)<0.001) return{valor:ajustada,tipo:'usada',texto:`Carga usada mais recente: ${fmtKg(ajustada)}`};
    if(ajustada) return{valor:ajustada,tipo:'ajustada',texto:`A carga anterior (${fmtKg(ultima)}) não está disponível. Use ${fmtKg(ajustada)} como referência conservadora.`};
  }
  const inicial=referenciaCargaInicialConservadora163K(exercicio,perfil);
  if(inicial){
    const equip=chaveCargaExercicio(exercicio);
    const unidade=equip==='Halteres'?' por halter':'';
    return{valor:inicial,tipo:'referencia',texto:`Teste inicial conservador: ${fmtKg(inicial)}${unidade}. Ajuste apenas se concluir com técnica boa, sem dor e esforço controlado.`};
  }
  return sugerirCargaInicialExercicioBase163K(exercicio,perfil,historico);
};
function ultimosRegistrosCarga163K(exercicio,historico=[]){
  return arr(historico).filter(item=>cargaRegistradaExercicio(exercicio,item?.log||item)>0).slice(-2);
}
podeProgredirCarga=function(exercicio,historicoExecucoes=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return{permitido:false,motivo:'resistência qualitativa, sem progressão numérica de carga'};
  const nome=nomeTecnicoExercicio(exercicio)||'Exercício';
  const ultimos=ultimosRegistrosCarga163K(exercicio,historicoExecucoes);
  if(ultimos.length<2) return{permitido:false,motivo:'são necessários dois registros detalhados com a mesma carga'};
  const cargas=ultimos.map(item=>cargaRegistradaExercicio(exercicio,item?.log||item));
  const atual=cargas[1];
  if(Math.abs(cargas[0]-cargas[1])>=0.001) return{permitido:false,atual,motivo:'a carga atual ainda não foi consolidada em dois registros consecutivos'};
  for(const item of ultimos){
    const log=item?.log||item;
    if(temDorLog(log)) return{permitido:false,atual,motivo:'dor registrada'};
    if(tecnicaRuimLog(log)||normTxt(log.tecnica)!=='boa') return{permitido:false,atual,motivo:'técnica não confirmada como boa'};
    if(log.feito!=='sim'||!completouMeta(exercicio,log)) return{permitido:false,atual,motivo:'execução incompleta'};
    const rpe=rpeLog(log);
    if(!rpe||rpe<6||rpe>8) return{permitido:false,atual,motivo:'esforço ausente ou fora da faixa segura de 6 a 8'};
  }
  const proxima=proximaCargaRealDisponivel(nome,atual,ST.perfil);
  return proxima?{permitido:true,atual,proxima,variavel:'carga'}:{permitido:false,atual,motivo:'não há próxima carga realmente configurável'};
};
function podeProgredirResistenciaElastico163K(exercicio,historico=[]){
  if(!usaElasticoExercicio(exercicio)) return{permitido:false,motivo:'exercício sem elástico'};
  const ultimos=arr(historico).filter(item=>resistenciaElasticoRegistrada163K(item?.log||item)).slice(-2);
  if(ultimos.length<2) return{permitido:false,motivo:'registre a resistência usada em duas sessões'};
  const resistencias=ultimos.map(item=>resistenciaElasticoRegistrada163K(item?.log||item));
  const atual=resistencias[1];
  if(resistencias[0]!==atual) return{permitido:false,atual,motivo:'a resistência atual ainda não foi consolidada em duas sessões'};
  for(const item of ultimos){
    const log=item?.log||item;
    if(temDorLog(log)) return{permitido:false,atual,motivo:'dor registrada'};
    if(tecnicaRuimLog(log)||normTxt(log.tecnica)!=='boa') return{permitido:false,atual,motivo:'técnica não confirmada como boa'};
    if(log.feito!=='sim'||!completouMeta(exercicio,log)) return{permitido:false,atual,motivo:'execução incompleta'};
    const rpe=rpeLog(log);if(!rpe||rpe<6||rpe>8)return{permitido:false,atual,motivo:'esforço ausente ou fora da faixa segura de 6 a 8'};
  }
  const disponiveis=resistenciasElasticoDisponiveis163K(ST.perfil);
  const idx=disponiveis.indexOf(atual),proxima=idx>=0?disponiveis[idx+1]||'':'';
  return proxima?{permitido:true,atual,proxima,variavel:'resistencia'}:{permitido:false,atual,motivo:'não há resistência superior configurada'};
}
function decisaoReduzirCarga163K(exercicio,historico=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return null;
  const item=arr(historico).filter(h=>cargaRegistradaExercicio(exercicio,h?.log||h)>0).at(-1);
  if(!item) return null;
  const log=item?.log||item,atual=cargaRegistradaExercicio(exercicio,log);
  const pesado=rpeLog(log)>=9||['pesado','muito'].includes(normTxt(log.diff))||tecnicaRuimLog(log)||log.feito==='parcial'||log.feito==='nao';
  if(!pesado&&!temDorLog(log)) return null;
  const anterior=cargaAnteriorDisponivel163K(exercicio,atual,ST.perfil);
  return{atual,anterior,motivo:temDorLog(log)?'dor registrada':tecnicaRuimLog(log)?'técnica ruim':log.feito!=='sim'?'execução incompleta':'esforço alto'};
}

function ajusteVolumeUnico163K1(exercicio,{forte=false}={}){
  const series=Math.max(1,+exercicio?.s||1);
  if(series>1){
    const reduzir=forte?Math.max(1,Math.ceil(series*.2)):1;
    const novas=Math.max(1,series-reduzir);
    return{variavel:'séries',antes:`${series} séries`,depois:`${novas} séries`,texto:`reduza de ${series} para ${novas} séries e mantenha ${exercicio?.r||'as repetições planejadas'}`};
  }
  const r=String(exercicio?.r||'').trim();
  const nums=(r.match(/\d+(?:[.,]\d+)?/g)||[]).map(v=>+v.replace(',','.'));
  if(nums.length){
    const min=nums[0],max=nums.length>1?nums.at(-1):nums[0];
    const novoMax=Math.max(1,max-1),novoMin=Math.min(min,novoMax);
    const novo=novoMin===novoMax?String(novoMax):`${novoMin}–${novoMax}`;
    return{variavel:'repetições',antes:r,depois:novo,texto:`mantenha uma série e reduza as repetições de ${r} para ${novo}`};
  }
  return{variavel:'variação',antes:'variação atual',depois:'variação sem carga',texto:'use uma variação sem carga ou mais simples e mantenha o restante da prescrição'};
}
function feedbackPesadoAtual163K1(log={}){
  const regra=regraDificuldadeLog(log);
  return (+rpeLog(log)>=9)||regra?.acao==='manter'||regra?.acao==='reduzir_ou_regredir';
}
function registroCargaConsistente163K1(exercicio,item){
  const log=item?.log||item||{};
  const carga=cargaRegistradaExercicio(exercicio,log);
  const rpe=rpeLog(log);
  return !!(carga>0&&log.feito==='sim'&&completouMeta(exercicio,log)&&!temDorLog(log)&&!tecnicaRuimLog(log)&&normTxt(log.tecnica)==='boa'&&rpe>=6&&rpe<=8);
}
function estadoConsolidacaoCarga163K1(exercicio,historico=[]){
  if(!exercicioUsaCargaNumerica(exercicio)) return null;
  const comCarga=arr(historico).filter(item=>cargaRegistradaExercicio(exercicio,item?.log||item)>0);
  if(!comCarga.length) return{tipo:'inicial',titulo:'Progressão de carga',texto:'Nenhuma sessão detalhada com carga foi concluída. Registre carga, técnica, dor e esforço para iniciar a contagem.'};
  const ultimo=comCarga.at(-1),atual=cargaRegistradaExercicio(exercicio,ultimo?.log||ultimo);
  let consistentes=0;
  for(let i=comCarga.length-1;i>=0;i--){
    const item=comCarga[i],carga=cargaRegistradaExercicio(exercicio,item?.log||item);
    if(Math.abs(carga-atual)>=0.001||!registroCargaConsistente163K1(exercicio,item)) break;
    consistentes++;
  }
  const proxima=proximaCargaRealDisponivel(nomeTecnicoExercicio(exercicio)||exercicio?.n||'',atual,ST.perfil);
  if(consistentes>=2){
    return proxima
      ?{tipo:'pronto',titulo:'Critério de carga atingido',texto:`2 de 2 sessões consistentes com ${fmtKg(atual)}. A próxima carga disponível (${fmtKg(proxima)}) será avaliada ao gerar a próxima semana.`}
      :{tipo:'consolidado',titulo:'Carga consolidada',texto:`2 de 2 sessões consistentes com ${fmtKg(atual)}. Não há carga maior configurada; progrida por outra variável somente se o plano indicar.`};
  }
  if(consistentes===1) return{tipo:'andamento',titulo:'Consolidação de carga',texto:`1 de 2 sessões consistentes com ${fmtKg(atual)}. Repita com técnica boa, sem dor e esforço entre 6 e 8.`};
  const log=ultimo?.log||ultimo||{};
  let motivo='o último registro não cumpriu todos os critérios';
  if(temDorLog(log)) motivo='houve dor';
  else if(tecnicaRuimLog(log)||normTxt(log.tecnica)!=='boa') motivo='a técnica não foi confirmada como boa';
  else if(log.feito!=='sim'||!completouMeta(exercicio,log)) motivo='a execução ficou incompleta';
  else if(!rpeLog(log)||rpeLog(log)<6||rpeLog(log)>8) motivo='o esforço ficou ausente ou fora da faixa de 6 a 8';
  return{tipo:'pausado',titulo:'Contagem não avançou',texto:`A carga de ${fmtKg(atual)} ainda não conta para progressão porque ${motivo}. A contagem recomeça após uma sessão consistente.`};
}
function registroElasticoConsistente163K1(exercicio,item){
  const log=item?.log||item||{};
  const res=resistenciaElasticoRegistrada163K(log),rpe=rpeLog(log);
  return !!(res&&log.feito==='sim'&&completouMeta(exercicio,log)&&!temDorLog(log)&&!tecnicaRuimLog(log)&&normTxt(log.tecnica)==='boa'&&rpe>=6&&rpe<=8);
}
function estadoConsolidacaoElastico163K1(exercicio,historico=[]){
  if(!usaElasticoExercicio(exercicio)) return null;
  const itens=arr(historico).filter(item=>resistenciaElasticoRegistrada163K(item?.log||item));
  if(!itens.length) return{tipo:'inicial',titulo:'Progressão do elástico',texto:'Registre a resistência usada, técnica, dor e esforço para iniciar a contagem.'};
  const atual=resistenciaElasticoRegistrada163K(itens.at(-1)?.log||itens.at(-1));
  let consistentes=0;
  for(let i=itens.length-1;i>=0;i--){
    const item=itens[i],res=resistenciaElasticoRegistrada163K(item?.log||item);
    if(res!==atual||!registroElasticoConsistente163K1(exercicio,item)) break;
    consistentes++;
  }
  const disp=resistenciasElasticoDisponiveis163K(ST.perfil),idx=disp.indexOf(atual),proxima=idx>=0?disp[idx+1]||'':'';
  if(consistentes>=2){
    return proxima
      ?{tipo:'pronto',titulo:'Critério de resistência atingido',texto:`2 de 2 sessões consistentes com resistência ${atual}. A resistência ${proxima} será avaliada ao gerar a próxima semana.`}
      :{tipo:'consolidado',titulo:'Resistência consolidada',texto:`2 de 2 sessões consistentes com resistência ${atual}. Não há resistência superior configurada.`};
  }
  if(consistentes===1) return{tipo:'andamento',titulo:'Consolidação do elástico',texto:`1 de 2 sessões consistentes com resistência ${atual}. Repita com técnica boa, sem dor e esforço entre 6 e 8.`};
  return{tipo:'pausado',titulo:'Contagem não avançou',texto:`A resistência ${atual} ainda não conta para progressão. Confira execução completa, técnica, dor e esforço.`};
}
function htmlEstadoConsolidacao163K1(exercicio,historico=[]){
  const estado=estadoConsolidacaoCarga163K1(exercicio,historico)||estadoConsolidacaoElastico163K1(exercicio,historico);
  if(!estado) return'';
  const classe=estado.tipo==='pronto'||estado.tipo==='consolidado'?'ig':estado.tipo==='pausado'?'io':'ib';
  return `<div class="info ${classe} progressao-carga-status" style="margin:9px 0;font-size:12px"><strong>${escHtml(estado.titulo)}:</strong> ${escHtml(estado.texto)}</div>`;
}

const avaliarProgressaoBase163K=avaliarProgressao;
avaliarProgressao=function(exercicio,historicoExecucoes,perfil){
  const base=avaliarProgressaoBase163K(exercicio,historicoExecucoes,perfil);
  const nome=exercicio?.n||exercicio?.nome||'Exercício';
  if(exercicioUsaCargaNumerica(exercicio)){
    const reduzir=decisaoReduzirCarga163K(exercicio,historicoExecucoes);
    if(reduzir){
      if(reduzir.anterior) return{status:'regredir',motivo:`${reduzir.motivo} com ${fmtKg(reduzir.atual)}.`,sugestao:`Use ${fmtKg(reduzir.anterior)} na próxima sessão e mantenha séries e repetições. Não reduza carga e volume ao mesmo tempo.`};
      if(reduzir.motivo==='dor registrada'||reduzir.motivo==='técnica ruim') return{...base,status:base.status==='trocar'?'trocar':'regredir',sugestao:`${fmtKg(reduzir.atual)} já é a menor carga disponível. Use uma variação sem carga ou mais simples até executar com técnica boa e sem dor; não aumente séries nem repetições.`};
      const ajuste=ajusteVolumeUnico163K1(exercicio,{forte:(rpeLog((arr(historicoExecucoes).at(-1)?.log||arr(historicoExecucoes).at(-1)||{}))>=10)});
      return{...base,status:'reduzir_volume',sugestao:`${fmtKg(reduzir.atual)} já é a menor carga disponível. Mantenha essa carga e ${ajuste.texto}. Altere somente ${ajuste.variavel}.`};
    }
    const carga=podeProgredirCarga(exercicio,historicoExecucoes);
    if(carga.permitido) return{status:'progredir',motivo:`Duas sessões completas com ${fmtKg(carga.atual)}, técnica boa, sem dor e esforço controlado.`,sugestao:`Próxima carga disponível: ${fmtKg(carga.proxima)}. Mantenha ${exercicio.s||''}${exercicio.s?' séries':''}${exercicio.r?` e ${exercicio.r}`:''}; altere somente a carga.`};
    if(base.status==='progredir') return{status:'manter',motivo:`A carga ainda não pode avançar: ${carga.motivo}.`,sugestao:`Mantenha a carga atual e as repetições de ${nome}. Registre carga, técnica, dor e esforço até consolidar duas sessões.`};
  }
  if(usaElasticoExercicio(exercicio)){
    const elastico=podeProgredirResistenciaElastico163K(exercicio,historicoExecucoes);
    if(elastico.permitido) return{status:'progredir',motivo:`Duas sessões completas com resistência ${elastico.atual}, técnica boa e sem dor.`,sugestao:`Passe para resistência ${elastico.proxima} e mantenha séries e repetições; altere somente a resistência.`};
    if(base.status==='progredir') return{status:'manter',motivo:`A resistência ainda não pode avançar: ${elastico.motivo}.`,sugestao:'Mantenha séries, repetições e resistência. Registre a resistência usada em cada sessão.'};
  }
  return base;
};
const linhasResistenciaElasticoBase163K=linhasResistenciaElastico;
linhasResistenciaElastico=function(exercicio,perfil=ST.perfil){
  const linhas=linhasResistenciaElasticoBase163K(exercicio,perfil);
  if(!usaElasticoExercicio(exercicio)) return linhas;
  const hist=coletarHistoricoExecucoes(exercicio),ult=arr(hist).map(h=>resistenciaElasticoRegistrada163K(h?.log||h)).filter(Boolean).at(-1);
  const planejada=normalizarResistenciaElastico163K(exercicio?.resistenciaElastico||'');
  const prog=podeProgredirResistenciaElastico163K(exercicio,hist);
  if(planejada) linhas.push({label:'Resistência planejada',texto:`${planejada}; mantenha séries e repetições`});
  else if(ult) linhas.push({label:'Última resistência usada',texto:ult});
  if(!planejada&&prog.permitido) linhas.push({label:'Próxima resistência',texto:`${prog.proxima}; mantenha séries e repetições`});
  return linhas.filter((l,i,a)=>a.findIndex(x=>x.label===l.label&&x.texto===l.texto)===i);
};


