function nivelDiagramaExercicioCalifit(){
  try{
    const perfil=ST?.perfil||{};
    const nivel=typeof avaliarProntidaoInicial==='function'?(avaliarProntidaoInicial(perfil)?.nivelEfetivo||perfil.nivel):perfil.nivel;
    return ['init','inter','avanc'].includes(nivel)?nivel:'init';
  }catch{return 'init';}
}
function htmlDiagramaExercicioCalifit(nome,compacto=false){
  const cobertura=classificarCoberturaDiagramaCalifit(nome);
  if(cobertura.modo!=='proprio'&&cobertura.modo!=='compartilhado') return '';
  const tipo=cobertura.tipo;
  const dados=dadosDiagramaExercicioCalifit(tipo);
  const svg=svgDiagramaExercicioCalifit(tipo);
  if(!dados||!svg) return '';
  const nivel=nivelDiagramaExercicioCalifit();
  const tag=cobertura.modo==='proprio'?'Diagrama específico do exercício':'Ilustração de referência';
  const aviso=cobertura.modo==='proprio'
    ?'<div class="exercise-visual-shared-note">Representa diretamente o exercício selecionado.</div>'
    :'<div class="exercise-visual-shared-note">Usa uma base visual próxima para apoiar o entendimento. Siga as instruções escritas desta variação.</div>';
  return `<div class="exercise-visual priority${compacto?' compact':''}" data-ex-diagrama="${escHtml(tipo)}" data-diagrama-qualidade="prioritario" data-diagrama-cobertura="${escHtml(cobertura.modo)}" data-nivel-diagrama="${escHtml(nivel)}"><div class="exercise-visual-head"><span>${escHtml(dados.titulo)}</span><span class="exercise-visual-tag">${escHtml(tag)}</span></div>${svg}${aviso}<div class="exercise-visual-cues"><div class="exercise-visual-cue"><strong>O que deve se mover</strong>${escHtml(dados.move)}</div><div class="exercise-visual-cue avoid"><strong>Evite isto</strong>${escHtml(dados.evite)}</div></div><div class="exercise-visual-note">${escHtml(dados.nota)}</div></div>`;
}
function listarDiagramasExerciciosCalifit(){return listarCoberturaDiagramasCalifit().filter(x=>x.modo==='proprio'||x.modo==='compartilhado').map(x=>({...x,qualidade:svgDiagramaExercicioCalifit(x.tipo)?'prioritario':'sem_diagrama'}));}


// ═══════════════════════════════════════════════════════════
// 163N3 — DOR, RECUPERAÇÃO E RETORNO PROGRESSIVO
// Ciclo regional derivado do histórico: cautela → adaptação →
// retorno controlado → liberação gradual → resolução.
// Não altera o schema nem mantém bloqueios antigos indefinidamente.
// ═══════════════════════════════════════════════════════════
const ORDEM_DOR_163N3={nenhuma:0,leve:1,moderada:2,forte:3};
const DIAS_163N3=24*60*60*1000;
function nivelDorMaximo163N3(niveis=[]){
  return arr(niveis).reduce((melhor,n)=>((ORDEM_DOR_163N3[n]||0)>(ORDEM_DOR_163N3[melhor]||0)?n:melhor),'nenhuma');
}
function dataRegistro163N3(reg={},fallback=''){
  const bruto=reg.data||reg.dataPlanejada||reg.treino?.data||fallback||'';
  const ts=new Date(bruto).getTime();
  return Number.isFinite(ts)?ts:0;
}
function semanasAte163N3(estado=ST,semanaLimite=null){
  const semanas=arr(estado?.semanas).filter(Boolean);
  if(!semanaLimite) return semanas;
  const idx=semanas.findIndex(s=>String(s.id)===String(semanaLimite.id));
  return idx>=0?semanas.slice(0,idx+1):semanas;
}
function coletarEventosDorHistoricoCalifit(estado=ST,semanaLimite=null){
  const eventos=[];
  const exposicoes=[];
  const semanas=semanasAte163N3(estado,semanaLimite);
  const ids=new Set(semanas.map(s=>String(s.id)));
  semanas.forEach(sem=>{
    Object.entries(sem?.registros||{}).forEach(([diaIdx,reg])=>{
      const ts=dataRegistro163N3(reg,sem.inicio||sem.fim);
      if(reg?.tipo==='feito'&&reg.treino){
        exerciciosRegistradosDoTreino(reg.treino,+diaIdx).forEach(ex=>{
          const log=ex.log||ex;
          const info=analisarDorRegistro(log);
          const feito=log?.feito||ex?.feito||'';
          const nome=ex.nome||ex.n||'Exercício';
          if(info.temDor){
            const regioes=info.regioes?.length?info.regioes:['sem_regiao'];
            regioes.forEach(regiao=>eventos.push({
              tipo:'dor',regiao,nivel:info.nivel||'leve',ts,semanaId:sem.id,diaIdx:+diaIdx,
              exercicio:nome,padrao:padraoExercicioCodigo(ex)||'',alertaProfissional:!!info.alertaProfissional,
              texto:info.texto||dorRegistroEfetiva(log)||''
            }));
          }else if(feito==='sim'&&!tecnicaRuimLog(log)&&(!rpeLog(log)||rpeLog(log)<=8)){
            exposicoes.push({tipo:'sem_dor',ts,semanaId:sem.id,diaIdx:+diaIdx,exercicio:cloneObj(ex),nome});
          }
        });
      }
      if(reg?.tipo==='descanso'&&String(reg.obs||'').trim()){
        const info=analisarDorTexto(reg.obs);
        if(info.temDor) (info.regioes?.length?info.regioes:['sem_regiao']).forEach(regiao=>eventos.push({
          tipo:'dor',regiao,nivel:info.nivel||'leve',ts,semanaId:sem.id,diaIdx:+diaIdx,
          exercicio:'Recuperação/descanso',padrao:'',alertaProfissional:!!info.alertaProfissional,texto:info.texto||reg.obs||''
        }));
      }
    });
  });
  arr(estado?.checkins).filter(c=>ids.has(String(c.semanaId))).forEach(c=>{
    const info=analisarDorCheckin(c.respostas||{});
    if(!info.temDor) return;
    const sem=semanas.find(s=>String(s.id)===String(c.semanaId));
    const ts=dataRegistro163N3(c,sem?.fim||sem?.inicio);
    (info.regioes?.length?info.regioes:['sem_regiao']).forEach(regiao=>{
      // O check-in semanal consolida a semana; não deve duplicar como nova recorrência
      // quando já existe dor da mesma região nos registros de exercício/descanso.
      if(eventos.some(e=>String(e.semanaId)===String(c.semanaId)&&e.regiao===regiao)) return;
      eventos.push({
        tipo:'dor',regiao,nivel:info.nivel||'leve',ts,semanaId:c.semanaId,diaIdx:null,
        exercicio:'Check-in semanal',padrao:'',alertaProfissional:!!info.alertaProfissional,texto:info.texto||c.respostas?.dor||''
      });
    });
  });
  eventos.sort((a,b)=>a.ts-b.ts);
  exposicoes.sort((a,b)=>a.ts-b.ts);
  return{eventos,exposicoes};
}
function exposicaoRelacionadaDor163N3(exposicao,regiao){
  if(!exposicao?.exercicio||regiao==='sem_regiao') return false;
  return exercicioRelacionadoRegioes(exposicao.exercicio,[regiao]);
}
function classificarEpisodioDorCalifit({regiao,eventos=[],exposicoes=[],semanaLimite=null}={}){
  const dores=arr(eventos).filter(e=>e.regiao===regiao).sort((a,b)=>a.ts-b.ts);
  if(!dores.length) return null;
  const ultima=dores.at(-1);
  const referencia=new Date(semanaLimite?.fim||semanaLimite?.inicio||ultima.ts||Date.now()).getTime();
  const tsReferencia=Number.isFinite(referencia)?referencia:ultima.ts;
  const recentes=dores.filter(e=>ultima.ts-e.ts<=21*DIAS_163N3);
  let nivel=nivelDorMaximo163N3(recentes.map(e=>e.alertaProfissional?'forte':e.nivel));
  const recorrencias=recentes.length;
  const semanasComDor=[...new Set(recentes.map(e=>String(e.semanaId)))].length;
  if(recorrencias>=2&&nivel==='leve') nivel='moderada';
  else if(semanasComDor>=2&&nivel==='moderada') nivel='forte';
  const semDorDepois=arr(exposicoes).filter(x=>x.ts>ultima.ts&&exposicaoRelacionadaDor163N3(x,regiao));
  const sessoesSemDor=[...new Set(semDorDepois.map(x=>`${x.semanaId}|${x.diaIdx}`))].length;
  const diasDesde=Math.max(0,Math.floor((tsReferencia-ultima.ts)/DIAS_163N3));
  const dorNaSemana=semanaLimite?dores.some(e=>String(e.semanaId)===String(semanaLimite.id)):false;
  const necessario={leve:1,moderada:2,forte:3}[nivel]||1;
  let status='retorno_controlado';
  if(dorNaSemana) status=nivel==='forte'?'bloqueada':nivel==='moderada'?'adaptacao':'cautela';
  else if((sessoesSemDor>=necessario+2&&diasDesde>=7)||diasDesde>=35) status='resolvida';
  else if(sessoesSemDor>=necessario||(diasDesde>=21&&sessoesSemDor>=1)) status='liberada_gradual';
  const bloqueiaProgressao=status!=='resolvida';
  const acao=status==='bloqueada'?'substituir':(['adaptacao','retorno_controlado'].includes(status)?'reduzir':(status==='cautela'||status==='liberada_gradual'?'manter':'liberar'));
  const rotulo={
    bloqueada:'dor forte: padrão temporariamente bloqueado',adaptacao:'dor moderada: volume reduzido e retorno controlado',
    cautela:'dor leve: manter sem progressão e observar',retorno_controlado:'recuperação ainda sem evidência suficiente',
    liberada_gradual:'boa resposta sem dor: retirar restrições aos poucos',resolvida:'episódio antigo sem recorrência: bloqueio automático encerrado'
  }[status];
  return{
    regiao,nivelOriginal:nivelDorMaximo163N3(dores.map(e=>e.nivel)),nivelEfetivo:nivel,status,acao,
    bloqueiaProgressao,dorNaSemana,recorrencias,sessoesSemDor,diasDesde,necessario,
    ultimaDorEm:ultima.ts?new Date(ultima.ts).toISOString():'',ultimaDor:ultima,rotulo,
    alertaProfissional:nivel==='forte'||dores.some(e=>e.alertaProfissional)
  };
}
function estadoRecuperacaoDoresCalifit(estado=ST,semanaLimite=null){
  const historico=coletarEventosDorHistoricoCalifit(estado,semanaLimite);
  const regioes=[...new Set(historico.eventos.map(e=>e.regiao).filter(Boolean))];
  const episodios=regioes.map(regiao=>classificarEpisodioDorCalifit({regiao,eventos:historico.eventos,exposicoes:historico.exposicoes,semanaLimite})).filter(Boolean);
  const ativos=episodios.filter(e=>e.status!=='resolvida');
  const bloqueados=ativos.filter(e=>e.status==='bloqueada');
  const adaptacao=ativos.filter(e=>['adaptacao','retorno_controlado'].includes(e.status));
  const liberacaoGradual=ativos.filter(e=>e.status==='liberada_gradual');
  return{
    episodios,ativos,bloqueados,adaptacao,liberacaoGradual,
    temAtivo:ativos.length>0,temBloqueio:bloqueados.length>0,
    regioesAtivas:ativos.map(e=>e.regiao),
    resumo:!ativos.length
      ?'Sem episódio de dor ativo no histórico recente.'
      :ativos.map(e=>`${rotuloRegiaoDorCurto(e.regiao)}: ${e.rotulo} (${e.sessoesSemDor}/${e.necessario} sessões relacionadas sem dor)`).join('; ')
  };
}
function episodioDorMaisRestritivo163N3(episodios=[]){
  const pesoStatus={bloqueada:5,adaptacao:4,retorno_controlado:3,cautela:2,liberada_gradual:1,resolvida:0};
  return arr(episodios).slice().sort((a,b)=>(pesoStatus[b.status]||0)-(pesoStatus[a.status]||0)||(ORDEM_DOR_163N3[b.nivelEfetivo]||0)-(ORDEM_DOR_163N3[a.nivelEfetivo]||0))[0]||null;
}
function substitutoRecuperacaoDorCalifit(ex,episodio,perfil=ST.perfil){
  const reg=normTxt(episodio?.regiao);
  const nome=normTxt(nomeTecnicoExercicio(ex));
  let candidato='';
  if(reg==='ombro') candidato=/core|prancha|hollow/.test(nome)?'Dead Bug':'Retração Escapular no Solo/Parede';
  else if(['joelho','tornozelo','pe','quadril','quadriceps','panturrilha','posterior de coxa'].includes(reg)) candidato='Ponte de Glúteo';
  else if(['lombar','cervical'].includes(reg)) candidato='Dead Bug';
  else if(reg==='toracica') candidato='Mobilidade Torácica';
  else if(['punho','cotovelo','antebraco','peitoral','biceps','triceps'].includes(reg)) candidato='Retração Escapular no Solo/Parede';
  if(!candidato||normTxt(candidato)===nome||!equipamentoDisponivel(candidato,perfil)) return null;
  return{
    ...ex,n:candidato,s:1,r:candidato==='Ponte de Glúteo'?'8–10':candidato==='Dead Bug'?'6 cada':'8–10',ds:45,p:'',
    nota:`Substituição temporária por dor ${rotuloRegiaoDorCurto(episodio.regiao)}. Executar leve e somente sem dor.`,
    substituicaoDor163N3:true,exercicioOriginalDor163N3:ex.n||ex.nome||''
  };
}
function prescricaoAcimaBase163N3(ex,base){
  if(!base) return false;
  if((+ex.s||1)>(+base.s||1)) return true;
  const max=v=>Math.max(...((String(v||'').match(/\d+(?:[.,]\d+)?/g)||['0']).map(n=>+n.replace(',','.'))));
  return max(ex.r)>max(base.r);
}
function restaurarPrescricaoBase163N3(ex,base){
  if(!base) return ex;
  return{...ex,s:base.s,r:base.r,ds:Math.max(+ex.ds||0,+base.ds||0),p:base.p||ex.p};
}
function aplicarCicloDorPreviaCalifit(previa,ciclo,semana){
  if(!previa||!ciclo) return previa;
  previa.recuperacaoDor=cloneObj(ciclo);
  previa.resumoAjustes=arr(previa.resumoAjustes);
  previa.alteracoesAplicadas=arr(previa.alteracoesAplicadas||previa.alteracoes);
  const addResumo=t=>{if(t&&!previa.resumoAjustes.some(x=>normTxt(x)===normTxt(t))) previa.resumoAjustes.push(t);};
  const addAlt=a=>{
    const chave=[a.tipo,a.dia,a.exercicioOriginal,a.exercicioNovo,a.antes,a.depois,a.motivo].map(normTxt).join('|');
    if(!previa.alteracoesAplicadas.some(x=>[x.tipo,x.dia,x.exercicioOriginal,x.exercicioNovo,x.antes,x.depois,x.motivo].map(normTxt).join('|')===chave)) previa.alteracoesAplicadas.push(a);
  };
  ciclo.episodios.filter(e=>e.status==='resolvida').forEach(e=>addResumo(`Dor antiga ${formatarRegioesDor([e.regiao])}: sem recorrência recente; bloqueio automático encerrado.`));
  if(!ciclo.temAtivo){previa.alteracoes=previa.alteracoesAplicadas;return previa;}
  ciclo.ativos.forEach(e=>{
    const alvo=formatarRegioesDor([e.regiao]);
    if(e.status==='bloqueada') addResumo(`Dor forte ${alvo}: exercícios relacionados foram suspensos ou substituídos temporariamente. Procure avaliação profissional antes de insistir.`);
    else if(e.status==='adaptacao') addResumo(`Dor moderada ${alvo}: apenas exercícios relacionados tiveram redução conservadora; demais padrões foram preservados.`);
    else if(e.status==='cautela') addResumo(`Dor leve ${alvo}: treino mantido sem progressão no padrão relacionado; registre a próxima resposta.`);
    else if(e.status==='retorno_controlado') addResumo(`Recuperação ${alvo}: mantenha adaptação até completar ${e.necessario} sessões relacionadas sem dor.`);
    else if(e.status==='liberada_gradual') addResumo(`Recuperação ${alvo}: restrições estão sendo retiradas gradualmente, sem salto de volume ou dificuldade.`);
    if(e.recorrencias>=2) addResumo(`Dor recorrente ${alvo}: a cautela foi elevada um nível para evitar repetição do problema.`);
  });
  const planoBase=cloneObj(previa.planoBaseSemTempo||previa.plano);
  const estrutural=previa.planoBaseEstrutural||previa.planoBaseEstruturalOrigem||ST.planoBaseEstrutural||{};
  Object.entries(planoBase?.dias||{}).forEach(([diaIdx,dia])=>{
    if(!dia||['descanso','atividade','recuperacao'].includes(dia.tipo)) return;
    ['ex','core','ombro','aq'].forEach(bloco=>{
      const baseLista=arr(estrutural?.dias?.[diaIdx]?.[bloco]);
      dia[bloco]=arr(dia[bloco]).map((ex,indice)=>{
        const relacionados=ciclo.ativos.filter(ep=>ep.regiao!=='sem_regiao'&&exercicioRelacionadoRegioes(ex,[ep.regiao]));
        if(!relacionados.length) return ex;
        const ep=episodioDorMaisRestritivo163N3(relacionados);
        const base=baseLista[indice]&&nomeCombina(baseLista[indice].n||baseLista[indice].nome,ex.n||ex.nome)?baseLista[indice]:baseLista.find(b=>nomeCombina(b.n||b.nome,ex.n||ex.nome));
        const antes=`${ex.s||1}x${ex.r||''}`;
        if(ep.status==='bloqueada'){
          const sub=substitutoRecuperacaoDorCalifit(ex,ep,ST.perfil);
          if(sub){
            addAlt({tipo:'substituicao',dia:DPT_FULL[+diaIdx]||'',exercicioOriginal:ex.n||ex.nome,exercicioNovo:sub.n,motivo:`dor forte ${formatarRegioesDor([ep.regiao])}; padrão temporariamente substituído.`,antes,depois:`${sub.s}x${sub.r}`});
            return sub;
          }
          addAlt({tipo:'nota',dia:DPT_FULL[+diaIdx]||'',exercicioOriginal:ex.n||ex.nome,exercicioNovo:ex.n||ex.nome,motivo:`dor forte ${formatarRegioesDor([ep.regiao])}; exercício suspenso até revisão.`,antes,depois:'Suspenso temporariamente'});
          return null;
        }
        let novo={...ex};
        if(['adaptacao','retorno_controlado'].includes(ep.status)){
          if(prescricaoAcimaBase163N3(novo,base)) novo=restaurarPrescricaoBase163N3(novo,base);
          if(!base||(+novo.s||1)>1){
            const sAtual=+novo.s||1;
            const sBase=+base?.s||sAtual;
            if(sAtual>=sBase) novo.s=Math.max(1,sAtual-1);
          }
          novo.nota=[novo.nota,`retorno controlado por dor ${rotuloRegiaoDorCurto(ep.regiao)}; executar somente sem dor`].filter(Boolean).join(' · ');
          if((+novo.s||1)!=(+ex.s||1)||novo.r!==ex.r) addAlt({tipo:'volume',dia:DPT_FULL[+diaIdx]||'',exercicioOriginal:ex.n||ex.nome,exercicioNovo:novo.n||novo.nome,motivo:`recuperação de dor ${formatarRegioesDor([ep.regiao])}; volume relacionado reduzido sem alterar exercícios não relacionados.`,antes,depois:`${novo.s||1}x${novo.r||''}`});
          else addAlt({tipo:'nota',dia:DPT_FULL[+diaIdx]||'',exercicioOriginal:ex.n||ex.nome,exercicioNovo:novo.n||novo.nome,motivo:`recuperação de dor ${formatarRegioesDor([ep.regiao])}; manter sem progressão.`,antes,depois:antes});
          return novo;
        }
        if(ep.status==='liberada_gradual'&&prescricaoAcimaBase163N3(novo,base)) novo=restaurarPrescricaoBase163N3(novo,base);
        novo.nota=[novo.nota,ep.status==='liberada_gradual'?`retorno gradual após dor ${rotuloRegiaoDorCurto(ep.regiao)}; consolidar antes de progredir`:`cautela por dor leve ${rotuloRegiaoDorCurto(ep.regiao)}; não progredir se houver desconforto`].filter(Boolean).join(' · ');
        addAlt({tipo:'nota',dia:DPT_FULL[+diaIdx]||'',exercicioOriginal:ex.n||ex.nome,exercicioNovo:novo.n||novo.nome,motivo:ep.status==='liberada_gradual'?`boa resposta sem dor ${formatarRegioesDor([ep.regiao])}; restrição retirada gradualmente.`:`dor leve ${formatarRegioesDor([ep.regiao])}; manter sem progressão no padrão relacionado.`,antes,depois:`${novo.s||1}x${novo.r||''}`});
        return novo;
      }).filter(Boolean);
    });
  });
  deduplicarPlano(planoBase);
  previa.planoBaseSemTempo=limparMetadadosTempoPlano(ajustarDescansosPlano(planoBase));
  previa.plano=ajustarPlanoAoTempo(cloneObj(previa.planoBaseSemTempo),ST.perfil);
  previa.alteracoesAplicadas=normalizarAlteracoesPreviaCalifit(previa.alteracoesAplicadas);
  previa.alteracoes=previa.alteracoesAplicadas;
  const bloqueio=ciclo.bloqueados.length>0;
  const retorno=ciclo.ativos.some(e=>['adaptacao','retorno_controlado','liberada_gradual'].includes(e.status));
  const cautelaAtual=ciclo.ativos.some(e=>e.status==='cautela'&&e.dorNaSemana);
  if(bloqueio){
    previa.decisaoPrevia={...(previa.decisaoPrevia||{}),confianca:'bloqueada',ajuste:'Ajuste bloqueado por dor forte',aviso:'Interrompa o padrão dolorido e procure avaliação profissional antes de insistir.'};
  }else if(retorno){
    const dorAtual=ciclo.ativos.some(e=>e.dorNaSemana);
    previa.decisaoPrevia={
      ...(previa.decisaoPrevia||{}),
      confianca:dorAtual?'bloqueada':(previa.decisaoPrevia?.confianca==='bloqueada'?'bloqueada':'baixa'),
      ajuste:dorAtual?'Reduzido por dor':'Mantido por retorno gradual da dor',
      aviso:dorAtual?'Apenas padrões relacionados foram reduzidos; exercícios não relacionados foram preservados.':'O plano retira restrições por etapas, somente após sessões relacionadas sem dor.'
    };
  }else if(cautelaAtual){
    previa.decisaoPrevia={
      ...(previa.decisaoPrevia||{}),confianca:'baixa',ajuste:'Mantido por dor leve',
      aviso:'O treino foi mantido, mas o padrão relacionado não receberá progressão até novo registro sem dor.'
    };
  }
  return previa;
}
const gerarPreviaProximaSemanaBase163N3=gerarPreviaProximaSemana;
